window.SHLAV_TESTS = [{"title": "מבחן תרגול 1", "html": "<section class=\"cover\">\n  <h1>מִבְחַן תִּרְגּוּל – שָׁלָב א'<\/h1>\n  <div>כִּיתָּה ב' · מִבְחָן מִסְפָּר 1<\/div>\n  <div class=\"fields\">שֵׁם: ____________________<br>תַּאֲרִיךְ: ________________<\/div>\n<\/section>\n\n<h2>חֵלֶק רִאשׁוֹן: קִטְעֵי קְרִיאָה וּשְׁאֵלוֹת<\/h2>\n<p class=\"instr\">קִרְאוּ אֶת קֶטַע הַמֵּידָע שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרָיו.<\/p>\n<div class=\"passage-title\">הַדּוֹלְפִין<\/div>\n<ol class=\"lines\">\n  <li>הַדּוֹלְפִין חַי בַּיָּם וְשׂוֹחֶה כְּמוֹ דָּג, אֲבָל הוּא בִּכְלָל אֵינוֹ דָּג.<\/li>\n  <li>הַדּוֹלְפִין הוּא יוֹנֵק: הָאִימָּא יוֹלֶדֶת גּוּר וּמֵינִיקָה אוֹתוֹ בְּחָלָב.<\/li>\n  <li>דָּגִים נוֹשְׁמִים בְּתוֹךְ הַמַּיִם, אֲבָל הַדּוֹלְפִין נוֹשֵׁם אֲוִויר, כָּמוֹנוּ.<\/li>\n  <li>לָכֵן הוּא חַיָּיב לַעֲלוֹת אֶל פְּנֵי הַמַּיִם כָּל כַּמָּה דַּקּוֹת.<\/li>\n  <li>בְּרֹאשׁ הַדּוֹלְפִין יֵשׁ נְחִיר, פֶּתַח קָטָן שֶׁדַּרְכּוֹ הוּא שׁוֹאֵף אֲוִויר.<\/li>\n  <li>כְּשֶׁהַדּוֹלְפִין צוֹלֵל, הַנְּחִיר נִסְגָּר הֵיטֵב וּמַיִם אֵינָם נִכְנָסִים לְתוֹכוֹ.<\/li>\n  <li>אֲבָל אֵיךְ הַדּוֹלְפִין יָשֵׁן? הֲרֵי אִם יֵירָדֵם לְגַמְרֵי, לֹא יַעֲלֶה לִנְשׁוֹם!<\/li>\n  <li>חוֹקְרִים גִּילּוּ שֶׁהוּא יָשֵׁן בְּדֶרֶךְ מְיוּחֶדֶת: רַק חֲצִי מֵהַמּוֹחַ שֶׁלּוֹ נִרְדָּם.<\/li>\n  <li>הַחֵצִי הַשֵּׁנִי נִשְׁאָר עֵר, וְדוֹאֵג שֶׁהַדּוֹלְפִין יַעֲלֶה לִנְשׁוֹם בַּזְּמַן.<\/li>\n  <li>בִּזְמַן הַשֵּׁינָה גַּם עַיִן אַחַת נִשְׁאֶרֶת פְּקוּחָה, וְשׁוֹמֶרֶת מִפְּנֵי כְּרִישִׁים.<\/li>\n  <li>אַחֲרֵי כִּשְׁעָתַיִים הַחֲצָאִים מִתְחַלְּפִים: הַחֵצִי הָעֵר נִרְדָּם, וְהַיָּשֵׁן מִתְעוֹרֵר.<\/li>\n  <li>דּוֹלְפִינִים חַיִּים בִּקְבוּצוֹת, וְהֵם \"מְדַבְּרִים\" זֶה עִם זֶה בִּשְׁרִיקוֹת.<\/li>\n  <li>לְכָל דּוֹלְפִין יֵשׁ שְׁרִיקָה מְיוּחֶדֶת מִשֶּׁלּוֹ, וְהִיא מְשַׁמֶּשֶׁת לוֹ כְּמוֹ שֵׁם.<\/li>\n  <li>כְּשֶׁדּוֹלְפִין מִתְרַחֵק מֵהַקְּבוּצָה, חֲבֵרָיו שׁוֹרְקִים אֶת הַשְּׁרִיקָה שֶׁלּוֹ וְקוֹרְאִים לוֹ.<\/li>\n  <li>גּוּר צָעִיר לוֹמֵד לְזַהוֹת אֶת שְׁרִיקַת אִימּוֹ כְּבָר בַּיָּמִים הָרִאשׁוֹנִים לְחַיָּיו.<\/li>\n  <li>אוּלַי יוֹם אֶחָד נִלְמַד גַּם אֲנַחְנוּ לְהָבִין אֶת שְׂפַת הַשְּׁרִיקוֹת.<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה בְּכָל שְׁאֵלָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. מַדּוּעַ הַדּוֹלְפִין חַיָּיב לַעֲלוֹת אֶל פְּנֵי הַמַּיִם כָּל כַּמָּה דַּקּוֹת?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כְּדֵי לִשְׁמוֹר עַל עַצְמוֹ מִפְּנֵי כְּרִישִׁים<\/li><li><span class=\"l\">ב.<\/span>כִּי הוּא נוֹשֵׁם אֲוִויר<\/li><li><span class=\"l\">ג.<\/span>כְּדֵי לִשְׁרוֹק לַחֲבֵרָיו שֶׁבַּקְּבוּצָה<\/li><li><span class=\"l\">ד.<\/span>כִּי הוּא רוֹצֶה לִישׁוֹן עַל פְּנֵי הַמַּיִם<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. בְּשׁוּרָה 7 כְּתוּבָה שְׁאֵלָה: \"אֲבָל אֵיךְ הַדּוֹלְפִין יָשֵׁן?\"<br>הַמַּטָּרָה שֶׁל הַשְּׁאֵלָה הַזֹּאת הִיא –<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>לְהַרְאוֹת שֶׁדּוֹלְפִינִים אֵינָם יְשֵׁנִים אַף פַּעַם<\/li><li><span class=\"l\">ב.<\/span>לְסַפֵּר שֶׁהַחוֹקְרִים עֲדַיִין אֵינָם יוֹדְעִים אֶת הַתְּשׁוּבָה<\/li><li><span class=\"l\">ג.<\/span>לְהַסְבִּיר מַדּוּעַ דָּגִים נוֹשְׁמִים בְּתוֹךְ הַמַּיִם<\/li><li><span class=\"l\">ד.<\/span>לְהַצִּיג בְּעָיָה, שֶׁהַשּׁוּרוֹת הַבָּאוֹת מַסְבִּירוֹת אֵיךְ הַדּוֹלְפִין פּוֹתֵר אוֹתָהּ<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. בְּשׁוּרָה 13 כָּתוּב: \"וְהִיא מְשַׁמֶּשֶׁת לוֹ כְּמוֹ שֵׁם\".<br>לְמִי אוֹ לְמָה מִתְיַיחֶסֶת הַמִּילָה \"הִיא\"?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>לַשְּׁרִיקָה הַמְּיוּחֶדֶת<\/li><li><span class=\"l\">ב.<\/span>לַקְּבוּצָה שֶׁל הַדּוֹלְפִינִים<\/li><li><span class=\"l\">ג.<\/span>לָאִימָּא שֶׁל הַגּוּר<\/li><li><span class=\"l\">ד.<\/span>לָעַיִן הַפְּקוּחָה<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. עַל אֵיזוֹ שְׁאֵלָה <u>אֵין<\/u> תְּשׁוּבָה בַּקֶּטַע?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>דֶּרֶךְ אֵיזֶה חֵלֶק בַּגּוּף הַדּוֹלְפִין שׁוֹאֵף אֲוִויר?<\/li><li><span class=\"l\">ב.<\/span>מָה קוֹרֶה לַמּוֹחַ שֶׁל הַדּוֹלְפִין בִּזְמַן הַשֵּׁינָה?<\/li><li><span class=\"l\">ג.<\/span>מָה אוֹכֵל הַדּוֹלְפִין?<\/li><li><span class=\"l\">ד.<\/span>אֵיךְ דּוֹלְפִינִים קוֹרְאִים לְחָבֵר שֶׁהִתְרַחֵק מֵהַקְּבוּצָה?<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">5. אֵיזֶה שֵׁם אַחֵר מַתְאִים בְּיוֹתֵר לַקֶּטַע כּוּלּוֹ?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>הַדָּג הֶחָכָם בְּיוֹתֵר בַּיָּם<\/li><li><span class=\"l\">ב.<\/span>יוֹנֵק מְיוּחָד בַּיָּם<\/li><li><span class=\"l\">ג.<\/span>אֵיךְ יְשֵׁנִים הַדּוֹלְפִינִים<\/li><li><span class=\"l\">ד.<\/span>כְּרִישִׁים וְדוֹלְפִינִים<\/li><\/ol><\/div>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">קִרְאוּ אֶת הַסִּיפּוּר שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרָיו.<\/p>\n<div class=\"passage-title\">שְׁאֵלָה אַחַת קְטַנָּה<\/div>\n<ol class=\"lines long\">\n  <li>בְּיוֹם שְׁלִישִׁי אַחַר הַצָּהֳרַיִים הָלַךְ עוֹמֶר עִם סַבָּא בֶּנִי לַסִּפְרִיָּיה הָעִירוֹנִית.<\/li>\n  <li>עוֹמֶר, יֶלֶד בֶּן שְׁמוֹנֶה, חִיפֵּשׂ סֵפֶר עַל כּוֹכָבִים בִּשְׁבִיל עֲבוֹדָה לַכִּיתָּה.<\/li>\n  <li>סַבָּא הִתְיַישֵּׁב עַל כּוּרְסָה לְיַד הַחַלּוֹן, וּפָתַח אֶת הָעִיתּוֹן שֶׁלּוֹ.<\/li>\n  <li>עוֹמֶר שׁוֹטֵט בֵּין הַמַּדָּפִים הַגְּבוֹהִים. הָיוּ שָׁם אַלְפֵי סְפָרִים!<\/li>\n  <li>הוּא חִיפֵּשׂ בְּמַדָּף אֶחָד, וְאַחַר כָּךְ בְּמַדָּף אַחֵר, אֲבָל לֹא מָצָא דָּבָר.<\/li>\n  <li>לְיַד הַדֶּלְפֵּק יָשְׁבָה הַסַּפְרָנִית וְהִקְלִידָה בַּמַּחְשֵׁב. עוֹמֶר הֵצִיץ בָּהּ מֵרָחוֹק.<\/li>\n  <li>\"וּמָה אִם הִיא עֲסוּקָה? וּמָה אִם הַשְּׁאֵלָה שֶׁלִּי טִיפְּשִׁית?\" חָשַׁב, וְלֹא נִיגַּשׁ.<\/li>\n  <li>אַחֲרֵי חֲצִי שָׁעָה חָזַר עוֹמֶר אֶל סַבָּא בְּיָדַיִים רֵיקוֹת.<\/li>\n  <li>\"אֵין כָּאן סֵפֶר עַל כּוֹכָבִים,\" מִלְמֵל. \"בּוֹא נַחֲזוֹר הַבַּיְתָה.\"<\/li>\n  <li>סַבָּא קִיפֵּל אֶת הָעִיתּוֹן. \"שָׁאַלְתָּ אֶת הַסַּפְרָנִית?\"<\/li>\n  <li>עוֹמֶר הִשְׁפִּיל אֶת עֵינָיו. \"לֹא נָעִים לִי. אֲנִי אָמוּר לִמְצוֹא לְבַד.\"<\/li>\n  <li>\"אֲנִי כְּבָר בֶּן שִׁבְעִים,\" אָמַר סַבָּא, \"וַאֲפִילּוּ אֲנִי שׁוֹאֵל שְׁאֵלוֹת כָּל יוֹם.<\/li>\n  <li>רַק הַבּוֹקֶר שָׁאַלְתִּי אֶת הַנֶּהָג אֵיפֹה לָרֶדֶת. מִי שֶׁשּׁוֹאֵל – אֵינוֹ הוֹלֵךְ לְאִיבּוּד.\"<\/li>\n  <li>עוֹמֶר הִיסֵּס, אֲבָל לְבַסּוֹף נִיגַּשׁ אֶל הַדֶּלְפֵּק בִּצְעָדִים קְטַנִּים.<\/li>\n  <li>\"סְלִיחָה,\" אָמַר בְּקוֹל חָלוּשׁ, \"אֵיפֹה יֵשׁ סְפָרִים עַל כּוֹכָבִים?\"<\/li>\n  <li>הַסַּפְרָנִית הֵרִימָה אֶת רֹאשָׁהּ וְחִיְּיכָה. \"אֵיזוֹ שְׁאֵלָה מְצוּיֶּנֶת! בּוֹא אִיתִּי.\"<\/li>\n  <li>הִיא הוֹבִילָה אוֹתוֹ אֶל מַדָּף בַּפִּינָּה, וְשָׁלְפָה מִמֶּנּוּ שְׁלוֹשָׁה סְפָרִים עָבִים.<\/li>\n  <li>\"בְּדִיּוּק הַיּוֹם קִיבַּלְנוּ סֵפֶר חָדָשׁ עַל כּוֹכָבִים. אַתָּה הָרִאשׁוֹן שֶׁקּוֹרֵא בּוֹ!\"<\/li>\n  <li>עוֹמֶר חִיבֵּק אֶת הַסְּפָרִים וְרָץ אֶל סַבָּא. פָּנָיו זָרְחוּ.<\/li>\n  <li>בַּדֶּרֶךְ הַחוּצָה נֶעֱצַר עוֹמֶר לְיַד הַדֶּלְפֵּק. \"אֶפְשָׁר לִשְׁאוֹל עוֹד שְׁאֵלָה?\"<\/li>\n  <li>\"בְּוַודַּאי,\" עָנְתָה הַסַּפְרָנִית.<\/li>\n  <li>\"יֵשׁ לָכֶם גַּם סְפָרִים עַל דִּינוֹזָאוּרִים?\" שָׁאַל עוֹמֶר, וְסַבָּא צָחַק.<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה בְּכָל שְׁאֵלָה.<\/p>\n\n<div class=\"tight\">\n<div class=\"q\"><div class=\"stem\">1. מַדּוּעַ עוֹמֶר לֹא נִיגַּשׁ אֶל הַסַּפְרָנִית כְּשֶׁרָאָה אוֹתָהּ לְיַד הַדֶּלְפֵּק (שׁוּרוֹת 6–7)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי סַבָּא בִּיקֵּשׁ מִמֶּנּוּ לִמְצוֹא אֶת הַסֵּפֶר לְבַד<\/li><li><span class=\"l\">ב.<\/span>כִּי כְּבָר מָצָא סֵפֶר עַל כּוֹכָבִים<\/li><li><span class=\"l\">ג.<\/span>כִּי הַסַּפְרָנִית אָמְרָה לוֹ שֶׁהִיא עֲסוּקָה<\/li><li><span class=\"l\">ד.<\/span>כִּי חָשַׁשׁ שֶׁהִיא עֲסוּקָה וְשֶׁהַשְּׁאֵלָה שֶׁלּוֹ טִיפְּשִׁית<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. מָה פֵּירוּשׁ הַמִּילָה \"שׁוֹטֵט\" (שׁוּרָה 4)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>הִסְתּוֹבֵב מִמָּקוֹם לְמָקוֹם<\/li><li><span class=\"l\">ב.<\/span>הִתְחַבֵּא<\/li><li><span class=\"l\">ג.<\/span>קָרָא בְּקוֹל רָם<\/li><li><span class=\"l\">ד.<\/span>טִיפֵּס לְמַעְלָה<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. מָה קָרָה <u>לִפְנֵי<\/u> שֶׁעוֹמֶר חָזַר אֶל סַבָּא בְּיָדַיִים רֵיקוֹת?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>סַבָּא סִיפֵּר שֶׁשָּׁאַל אֶת הַנֶּהָג אֵיפֹה לָרֶדֶת<\/li><li><span class=\"l\">ב.<\/span>הַסַּפְרָנִית שָׁלְפָה שְׁלוֹשָׁה סְפָרִים מֵהַמַּדָּף<\/li><li><span class=\"l\">ג.<\/span>עוֹמֶר הֵצִיץ בַּסַּפְרָנִית מֵרָחוֹק<\/li><li><span class=\"l\">ד.<\/span>עוֹמֶר שָׁאַל אִם יֵשׁ סְפָרִים עַל דִּינוֹזָאוּרִים<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. אֵיזוֹ מִילָה יְכוֹלָה לְהַחֲלִיף אֶת הַמִּילָה \"הִיסֵּס\" (שׁוּרָה 14)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>מִיהֵר<\/li><li><span class=\"l\">ב.<\/span>הִתְלַבֵּט<\/li><li><span class=\"l\">ג.<\/span>כָּעַס<\/li><li><span class=\"l\">ד.<\/span>צָחַק<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">5. בְּשׁוּרָה 12 סַבָּא אוֹמֵר: \"וַאֲפִילּוּ אֲנִי שׁוֹאֵל שְׁאֵלוֹת כָּל יוֹם\".<br>מַדּוּעַ הוּא אוֹמֵר \"אֲפִילּוּ\"?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי אֶפְשָׁר לַחְשׁוֹב שֶׁאָדָם מְבוּגָּר כְּבָר יוֹדֵעַ הַכּוֹל וְאֵינוֹ צָרִיךְ לִשְׁאוֹל<\/li><li><span class=\"l\">ב.<\/span>כִּי סַבָּא שׁוֹאֵל שְׁאֵלוֹת רַק אֶת הַסַּפְרָנִית<\/li><li><span class=\"l\">ג.<\/span>כִּי גַּם הַנֶּהָג שׁוֹאֵל שְׁאֵלוֹת כָּל יוֹם<\/li><li><span class=\"l\">ד.<\/span>כִּי סַבָּא אֵינוֹ אוֹהֵב לִשְׁאוֹל שְׁאֵלוֹת<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">6. לְמָה הִתְכַּוֵּון סַבָּא כְּשֶׁאָמַר: \"מִי שֶׁשּׁוֹאֵל – אֵינוֹ הוֹלֵךְ לְאִיבּוּד\" (שׁוּרָה 13)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>שֶׁעוֹמֶר עָלוּל לָלֶכֶת לְאִיבּוּד בֵּין הַמַּדָּפִים הַגְּבוֹהִים<\/li><li><span class=\"l\">ב.<\/span>שֶׁהַנֶּהָג לֹא יָדַע אֶת הַדֶּרֶךְ לַסִּפְרִיָּיה<\/li><li><span class=\"l\">ג.<\/span>שֶׁמִּי שֶׁמְּבַקֵּשׁ עֶזְרָה מַצְלִיחַ לִמְצוֹא אֶת מָה שֶׁהוּא מְחַפֵּשׂ<\/li><li><span class=\"l\">ד.<\/span>שֶׁכְּדַאי לְעוֹמֶר לְהִישָּׁאֵר קָרוֹב לְסַבָּא<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">7. בְּאֵיזֶה צֶמֶד מִילִים הַמִּילִים <u>אֵינָן<\/u> מִילִים נִרְדָּפוֹת?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>הֵצִיץ – הִבִּיט<\/li><li><span class=\"l\">ב.<\/span>שָׁלְפָה – הוֹצִיאָה<\/li><li><span class=\"l\">ג.<\/span>חָלוּשׁ – חַלָּשׁ<\/li><li><span class=\"l\">ד.<\/span>עָבִים – דַּקִּים<\/li><\/ol><\/div>\n\n<p class=\"stop\">עִבְרוּ לָעַמּוּד הַבָּא רַק לְאַחַר שֶׁתְּקַבְּלוּ הוֹרָאָה לְכָךְ מֵהַמּוֹרָה.<\/p>\n\n<\/div>\n<div class=\"page-break\"><\/div>\n<h2>חֵלֶק שֵׁנִי: שְׁאֵלוֹת בְּחֶשְׁבּוֹן<\/h2>\n<h3>מְשִׂימָה א': תַּרְגִּילִים<\/h3>\n<p class=\"instr\">פִּתְרוּ אֶת הַתַּרְגִּילִים וְכִתְבוּ אֶת הַתּוֹצָאָה.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\">46 + 37 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\">72 − 48 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\">7 × 6 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">4. <span class=\"ex\">36 : 4 = <span class=\"blank\"><\/span><\/span><\/div>\n\n<h3>מְשִׂימָה ב': הַמִּסְפָּר הֶחָסֵר<\/h3>\n<p class=\"instr\">כִּתְבוּ אֶת הַמִּסְפָּר הֶחָסֵר בְּכָל תַּרְגִּיל.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\">38 + <span class=\"blank\"><\/span> = 74<\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\">95 − <span class=\"blank\"><\/span> = 58<\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\">7 × <span class=\"blank\"><\/span> = 63<\/span><\/div>\n<div class=\"q mathq\">4. <span class=\"ex\">20 − <span class=\"blank\"><\/span> = 36 : 4<\/span><\/div>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כִּתְבוּ עַל הַקַּו מִסְפָּר מַתְאִים.<br>שִׂימוּ לֵב: בְּכָל תַּרְגִּיל יֵשׁ יוֹתֵר מִתְּשׁוּבָה נְכוֹנָה אַחַת.<\/p>\n<div data-accept=\"range:0-4\" class=\"q mathq\">5. <span class=\"ex\">45 + <span class=\"blank\"><\/span> &lt; 50<\/span><\/div>\n<div data-accept=\"range:19-63\" class=\"q mathq\">6. <span class=\"ex\">63 − 18 &gt; 63 − <span class=\"blank\"><\/span><\/span><\/div>\n\n<h3>מְשִׂימָה ג': בְּעָיוֹת מִילּוּלִיּוֹת<\/h3>\n<p class=\"instr\">קִרְאוּ כָּל בְּעָיָה וְהַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. לְדָנָה יֵשׁ 3 קוּפְסוֹת שֶׁל כַּדּוּרִים. בַּקּוּפְסָה הָרִאשׁוֹנָה יֵשׁ 5 כַּדּוּרִים. בַּקּוּפְסָה הַשְּׁנִיָּיה יֵשׁ 3 כַּדּוּרִים יוֹתֵר מֵאֲשֶׁר בָּרִאשׁוֹנָה. בַּקּוּפְסָה הַשְּׁלִישִׁית יֵשׁ 2 כַּדּוּרִים פָּחוֹת מֵאֲשֶׁר בַּשְּׁנִיָּיה.<br>כַּמָּה כַּדּוּרִים יֵשׁ לְדָנָה בְּסַךְ הַכּוֹל?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>16<\/li><li><span class=\"l\">ב.<\/span>19<\/li><li><span class=\"l\">ג.<\/span>13<\/li><li><span class=\"l\">ד.<\/span>21<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. אִימּוּן הַכַּדּוּרֶגֶל שֶׁל עִידָן מַתְחִיל בְּשָׁעָה <span class=\"ex\">10:45<\/span> וְנִמְשָׁךְ 20 דַּקּוֹת.<br>בְּאֵיזוֹ שָׁעָה מִסְתַּיֵּים הָאִימּוּן?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span><span class=\"ex\">10:25<\/span><\/li><li><span class=\"l\">ב.<\/span><span class=\"ex\">11:20<\/span><\/li><li><span class=\"l\">ג.<\/span><span class=\"ex\">12:05<\/span><\/li><li><span class=\"l\">ד.<\/span><span class=\"ex\">11:05<\/span><\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. לְדָנָה יֵשׁ 24 חֲרוּזִים, וּלְעִידָן יֵשׁ 8 חֲרוּזִים.<br>פִּי כַּמָּה יוֹתֵר חֲרוּזִים יֵשׁ לְדָנָה מֵאֲשֶׁר לְעִידָן?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>פִּי 3<\/li><li><span class=\"l\">ב.<\/span>פִּי 16<\/li><li><span class=\"l\">ג.<\/span>פִּי 32<\/li><li><span class=\"l\">ד.<\/span>פִּי 4<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. 29 יְלָדִים נוֹסְעִים לְטִיּוּל בִּמְכוֹנִיּוֹת. בְּכָל מְכוֹנִית יֵשׁ מָקוֹם לְ-5 יְלָדִים.<br>כַּמָּה מְכוֹנִיּוֹת צָרִיךְ <u>לְפָחוֹת<\/u> כְּדֵי לְהַסִּיעַ אֶת כָּל הַיְּלָדִים?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>5<\/li><li><span class=\"l\">ב.<\/span>4<\/li><li><span class=\"l\">ג.<\/span>6<\/li><li><span class=\"l\">ד.<\/span>24<\/li><\/ol><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ד': חִידוֹת בְּצִיּוּרִים<\/h3>\n<p class=\"instr\">בְּכָל חִידָה, כָּל צִיּוּר מַסְתִּיר מִסְפָּר. אוֹתוֹ צִיּוּר מַסְתִּיר תָּמִיד אוֹתוֹ מִסְפָּר.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">●<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>★ + ★ + ★ = 21<\/td><\/tr><tr><td>★ + ● = 12<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>7<\/li><li><span class=\"l\">ב.<\/span>9<\/li><li><span class=\"l\">ג.<\/span>5<\/li><li><span class=\"l\">ד.<\/span>4<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">♥<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>▲ + ▲ = 10<\/td><\/tr><tr><td>▲ + ♥ + ♥ = 19<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>7<\/li><li><span class=\"l\">ב.<\/span>14<\/li><li><span class=\"l\">ג.<\/span>5<\/li><li><span class=\"l\">ד.<\/span>9<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">✿<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>☀&#xFE0E; + ☂&#xFE0E; = 9<\/td><\/tr><tr><td>☀&#xFE0E; + ☂&#xFE0E; + ☀&#xFE0E; + ☂&#xFE0E; + ✿ = 26<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>17<\/li><li><span class=\"l\">ב.<\/span>9<\/li><li><span class=\"l\">ג.<\/span>18<\/li><li><span class=\"l\">ד.<\/span>8<\/li><\/ol><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ה': תַּרְגִּילֵי מְשׁוּלָּשִׁים<\/h3>\n<p class=\"instr\">בְּכָל תַּרְגִּיל הַמְּשׁוּלָּשׁ ∆ מַסְתִּיר סִפְרָה. בְּאוֹתוֹ תַּרְגִּיל כָּל הַמְּשׁוּלָּשִׁים מַסְתִּירִים אוֹתָהּ סִפְרָה.<br>אֵיזוֹ סִפְרָה מַסְתִּיר הַמְּשׁוּלָּשׁ? הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. <span class=\"ex\">1∆ + 2∆ = 34<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>4<\/li><li><span class=\"l\">ב.<\/span>2<\/li><li><span class=\"l\">ג.<\/span>7<\/li><li><span class=\"l\">ד.<\/span>1<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. <span class=\"ex\">∆2 + ∆2 = 64<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>6<\/li><li><span class=\"l\">ב.<\/span>2<\/li><li><span class=\"l\">ג.<\/span>3<\/li><li><span class=\"l\">ד.<\/span>4<\/li><\/ol><\/div>\n\n<p class=\"end\">סוֹף הַמִּבְחָן<\/p>\n\n<section class=\"answers\"><h2>פִּתְרוֹנוֹת – מבחן 1<\/h2>\n<table>\n<tr><th>שאלה<\/th><th>תשובה<\/th><th>הסבר + טריק<\/th><\/tr>\n<tr><th colspan=\"3\">קטע 1 – הדולפין<\/th><\/tr>\n<tr><td>1<\/td><td>ב<\/td><td>שורות 3–4: \"נושם אוויר... לכן הוא חייב לעלות\". טריק: \"לכן\" מסמן סיבה; בוחרים רק לפי הכתוב.<\/td><\/tr>\n<tr><td>2<\/td><td>ד<\/td><td>השאלה מציגה בעיה (אם יירדם – לא ינשום), ושורות 8–11 פותרות אותה. טריק: מטרת משפט – לקרוא שורה לפני ושורה אחרי.<\/td><\/tr>\n<tr><td>3<\/td><td>א<\/td><td>\"יש שריקה מיוחדת... והיא משמשת לו כמו שם\" – היא = השריקה. טריק: כינוי גוף – להחליף את המילה ולקרוא בקול.<\/td><\/tr>\n<tr><td>4<\/td><td>ג<\/td><td>נחיר (ש' 5), מוח בשינה (ש' 8–9), קריאה לחבר (ש' 14) – מופיעים; מזון – לא. טריק: לסמן ✓ ליד מה שמופיע.<\/td><\/tr>\n<tr><td>5<\/td><td>ב<\/td><td>הקטע כולו על יונק ימי מיוחד (נשימה, שינה, שריקות). א' שגוי (אינו דג); ג', ד' – רק פרט אחד. טריק: כותרת חייבת להתאים לכל הקטע.<\/td><\/tr>\n<tr><th colspan=\"3\">קטע 2 – שאלה אחת קטנה<\/th><\/tr>\n<tr><td>1<\/td><td>ד<\/td><td>שורה 7: \"ומה אם היא עסוקה? ומה אם השאלה שלי טיפשית?\". טריק: מסיח שמשתמש במילים מהקטע (\"לבד\", \"עסוקה\") בחיבור שגוי.<\/td><\/tr>\n<tr><td>2<\/td><td>א<\/td><td>\"שוטט בין המדפים\" + \"חיפש במדף אחד ואחר כך באחר\" = הסתובב. טריק: לקרוא שורה לפני ושורה אחרי.<\/td><\/tr>\n<tr><td>3<\/td><td>ג<\/td><td>הצצה בספרנית – שורה 6; החזרה לסבא – שורה 8. שאר האירועים בשורות 13, 17, 22 – אחרי. טריק: סדר אירועים – לסמן מספר שורה ליד כל אפשרות.<\/td><\/tr>\n<tr><td>4<\/td><td>ב<\/td><td>\"היסס, אבל לבסוף ניגש\" – לא היה בטוח = התלבט. טריק: להציב כל מילה במשפט ולבדוק שהמשמעות נשמרת.<\/td><\/tr>\n<tr><td>5<\/td><td>א<\/td><td>\"כבר בן שבעים\" – מפתיע שגם מבוגר ומנוסה צריך לשאול. טריק: ב\"אפילו\" שואלים \"מה היה מפתיע?\".<\/td><\/tr>\n<tr><td>6<\/td><td>ג<\/td><td>סבא מעודד את עומר לשאול את הספרנית – מי שמבקש עזרה מוצא. טריק: כוונת הדובר – לא לפרש מילה במילה (\"ללכת לאיבוד\").<\/td><\/tr>\n<tr><td>7<\/td><td>ד<\/td><td>עבים ↔ דקים – הפכים. טריק: להציב במשפט; לשים לב ל\"אינן\".<\/td><\/tr>\n<tr><th colspan=\"3\">חשבון – משימה א'<\/th><\/tr>\n<tr><td>1<\/td><td>83<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">46+30=76<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">76+7=83<\/span>. טריק: להשלים לעשרת; ספרות בסדר הנכון (לא 38).<\/td><\/tr>\n<tr><td>2<\/td><td>24<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">72−50=22<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">22+2=24<\/span>. טריק: לבדוק חיסור בחיבור (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">24+48=72<\/span>).<\/td><\/tr>\n<tr><td>3<\/td><td>42<\/td><td>לוח הכפל: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">7×6=42<\/span>. טריק: ספרות בסדר הנכון (לא 24).<\/td><\/tr>\n<tr><td>4<\/td><td>9<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">9×4=36<\/span>. טריק: חילוק כהפוך כפל.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ב'<\/th><\/tr>\n<tr><td>1<\/td><td>36<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">74−38=36<\/span>. טריק: בדיקה בהצבה (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">38+36=74<\/span>).<\/td><\/tr>\n<tr><td>2<\/td><td>37<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">95−58=37<\/span>. טריק: כשהמחסר חסר – מחסרים את התוצאה מהמספר הראשון (לא מחברים!).<\/td><\/tr>\n<tr><td>3<\/td><td>9<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">7×9=63<\/span>. טריק: חילוק כהפוך כפל.<\/td><\/tr>\n<tr><td>4<\/td><td>11<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">36:4=9<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">20−11=9<\/span>. טריק: מאזניים – לכסות ולפתור קודם את הצד המלא.<\/td><\/tr>\n<tr><td>5<\/td><td>כל מספר מ-0 עד 4<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">45+5=50<\/span> כבר לא קטן מ-50, לכן רק מספר קטן מ-5. טריק: אי-שוויון עם גבול עליון.<\/td><\/tr>\n<tr><td>6<\/td><td>כל מספר מ-19 עד 63<\/td><td>63 משני הצדדים; בחיסור הכיוון מתהפך: מורידים יותר → נשאר פחות. למשל 20.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ג'<\/th><\/tr>\n<tr><td>1<\/td><td>ב (19)<\/td><td>שנייה: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">5+3=8<\/span>; שלישית: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">8−2=6<\/span>; <span dir=\"ltr\" style=\"unicode-bidi:isolate\">5+8+6=19<\/span>. טריק: שרשרת השוואות – \"פחות ממי?\" (מהשנייה, לא מהראשונה → 16).<\/td><\/tr>\n<tr><td>2<\/td><td>ד (11:05)<\/td><td>15 דקות עד 11:00, ועוד 5 דקות. טריק: שעון – לקפוץ לשעה העגולה; מוסיפים דקות לדקות, לא לשעות.<\/td><\/tr>\n<tr><td>3<\/td><td>א (פי 3)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">24:8=3<\/span>. טריק: \"פי כמה\" = חילוק, \"בכמה\" = חיסור (16).<\/td><\/tr>\n<tr><td>4<\/td><td>ג (6)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">5×5=25<\/span> – נשארו 4 ילדים, וגם הם צריכים מכונית. טריק: \"כמה לפחות\" – עיגול כלפי מעלה.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ד'<\/th><\/tr>\n<tr><td>1<\/td><td>ג (5)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">★=21:3=7<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">●=12−7=5<\/span>. טריק: להתחיל מהשורה עם סמל אחד בלבד; 7 הוא תוצאת ביניים.<\/td><\/tr>\n<tr><td>2<\/td><td>א (7)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">▲=5<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">♥+♥=19−5=14<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">♥=7<\/span>. טריק: סמל כפול + החלפה; בדיקה בהצבה.<\/td><\/tr>\n<tr><td>3<\/td><td>ד (8)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">☀&#xFE0E;+☂&#xFE0E;=9<\/span> היא \"חבילה\" שמופיעה פעמיים: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">9+9=18<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">26−18=8<\/span>. טריק: החלפת קבוצה שלמה.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ה'<\/th><\/tr>\n<tr><td>1<\/td><td>ב (2)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">12+22=34<\/span>. טריק: ספרת האחדות – <span dir=\"ltr\" style=\"unicode-bidi:isolate\">∆+∆<\/span> מסתיים ב-4 → 2 או 7; <span dir=\"ltr\" style=\"unicode-bidi:isolate\">17+27=44<\/span> לא מתאים.<\/td><\/tr>\n<tr><td>2<\/td><td>ג (3)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">32+32=64<\/span>. טריק: ∆ בעשרות – <span dir=\"ltr\" style=\"unicode-bidi:isolate\">2+2=4<\/span> באחדות, נשאר <span dir=\"ltr\" style=\"unicode-bidi:isolate\">∆+∆=6<\/span>.<\/td><\/tr>\n<\/table><\/section>", "id": 1, "pdf": "pdf/test_1.pdf", "questions": 31}, {"title": "מבחן תרגול 2", "html": "<section class=\"cover\">\n  <h1>מִבְחַן תִּרְגּוּל – שָׁלָב א'<\/h1>\n  <div>כִּיתָה ב' · מִבְחָן מִסְפָּר 2<\/div>\n  <div class=\"fields\">שֵׁם: ____________________<br>תַּאֲרִיךְ: ________________<\/div>\n<\/section>\n\n<h2>חֵלֶק רִאשׁוֹן: קִטְעֵי קְרִיאָה וּשְׁאֵלוֹת<\/h2>\n<p class=\"instr\">קִרְאוּ אֶת קֶטַע הַמֵּידָע שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרָיו.<\/p>\n<div class=\"passage-title\">קוּרֵי הָעַכָּבִישׁ<\/div>\n<ol class=\"lines\">\n  <li>בְּפִינַּת הַחֶדֶר אוֹ בֵּין עַנְפֵי הָעֵץ אֶפְשָׁר לִרְאוֹת לִפְעָמִים רֶשֶׁת דַּקָּה וַעֲדִינָה.<\/li>\n  <li>אֶת הָרֶשֶׁת הַזֹּאת בָּנָה עַכָּבִישׁ, וְקוֹרְאִים לָהּ \"קוּרֵי עַכָּבִישׁ\".<\/li>\n  <li>הָעַכָּבִישׁ מְיַיצֵּר בְּתוֹךְ גּוּפוֹ חוּט מֶשִׁי דַּק, וּמִמֶּנּוּ הוּא טוֹוֶה אֶת הָרֶשֶׁת.<\/li>\n  <li>הַחוּט נִרְאֶה חַלָּשׁ, אֲבָל לְמַעֲשֶׂה הוּא חָזָק מְאוֹד. חוּט מֶשִׁי שֶׁל עַכָּבִישׁ<\/li>\n  <li>חָזָק אֲפִילּוּ יוֹתֵר מֵחוּט פְּלָדָה בְּאוֹתוֹ עוֹבִי. פְּלָדָה הִיא מַתֶּכֶת קָשָׁה וַחֲזָקָה!<\/li>\n  <li>לָמָּה הָעַכָּבִישׁ צָרִיךְ רֶשֶׁת? הָרֶשֶׁת הִיא הַמַּלְכּוֹדֶת שֶׁלּוֹ. חֵלֶק מֵהַחוּטִים<\/li>\n  <li>בָּרֶשֶׁת דְּבִיקִים כְּמוֹ דֶּבֶק. זְבוּב אוֹ יַתּוּשׁ שֶׁעָף אֶל הָרֶשֶׁת נִדְבָּק אֵלֶיהָ<\/li>\n  <li>וְאֵינוֹ מַצְלִיחַ לְהִשְׁתַּחְרֵר. הָעַכָּבִישׁ מַרְגִּישׁ שֶׁהָרֶשֶׁת רוֹעֶדֶת, וּמְמַהֵר אֶל הַטֶּרֶף.<\/li>\n  <li>וְאֵיךְ הָעַכָּבִישׁ עַצְמוֹ אֵינוֹ נִדְבָּק לָרֶשֶׁת שֶׁבָּנָה? הַתְּשׁוּבָה מַפְתִּיעָה:<\/li>\n  <li>לֹא כָּל הַחוּטִים בָּרֶשֶׁת דְּבִיקִים. הַחוּטִים שֶׁיּוֹצְאִים מִן הַמֶּרְכָּז הַחוּצָה<\/li>\n  <li>יְבֵשִׁים וַחֲלָקִים. הָעַכָּבִישׁ יוֹדֵעַ הֵיטֵב אֵילוּ חוּטִים יְבֵשִׁים, וְהוֹלֵךְ רַק עֲלֵיהֶם.<\/li>\n  <li>הָרוּחַ וְהַגֶּשֶׁם פּוֹגְעִים בָּרֶשֶׁת, וְהִיא נִקְרַעַת לְעִיתִּים קְרוֹבוֹת.<\/li>\n  <li>הָעַכָּבִישׁ אֵינוֹ מִתְיָיאֵשׁ: כִּמְעַט בְּכָל יוֹם הוּא בּוֹנֶה רֶשֶׁת חֲדָשָׁה.<\/li>\n  <li>לִפְנֵי כֵן הוּא אוֹכֵל אֶת הָרֶשֶׁת הַיְּשָׁנָה, וְכָךְ הַמֶּשִׁי הַיָּקָר אֵינוֹ מִתְבַּזְבֵּז.<\/li>\n  <li>יֵשׁ אֲנָשִׁים שֶׁפּוֹחֲדִים מֵעַכְּבִישִׁים, אֲבָל רוֹב הָעַכְּבִישִׁים אֵינָם מְסוּכָּנִים לִבְנֵי אָדָם.<\/li>\n  <li>לְהֶפֶךְ: הֵם מוֹעִילִים לָנוּ, כִּי הֵם טוֹרְפִים זְבוּבִים וְיַתּוּשִׁים שֶׁמַּטְרִידִים אוֹתָנוּ.<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה בְּכָל שְׁאֵלָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. מַדּוּעַ הָעַכָּבִישׁ אֵינוֹ נִדְבָּק לָרֶשֶׁת שֶׁלּוֹ?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי הָרַגְלַיִים שֶׁלּוֹ מְכוּסּוֹת בְּשֶׁמֶן<\/li><li><span class=\"l\">ב.<\/span>כִּי הוּא אוֹכֵל אֶת כָּל הַחוּטִים הַדְּבִיקִים<\/li><li><span class=\"l\">ג.<\/span>כִּי הוּא הוֹלֵךְ רַק עַל הַחוּטִים הַיְּבֵשִׁים<\/li><li><span class=\"l\">ד.<\/span>כִּי הַחוּט שֶׁלּוֹ חָזָק יוֹתֵר מִפְּלָדָה<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. מָה פֵּירוּשׁ הַמִּילָה \"מוֹעִילִים\" (שׁוּרָה 16)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>מַפְרִיעִים<\/li><li><span class=\"l\">ב.<\/span>עוֹזְרִים<\/li><li><span class=\"l\">ג.<\/span>מְסוּכָּנִים<\/li><li><span class=\"l\">ד.<\/span>מַפְחִידִים<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. בְּשׁוּרָה 5 כָּתוּב שֶׁחוּט הַמֶּשִׁי חָזָק אֲפִילּוּ יוֹתֵר מֵחוּט פְּלָדָה.<br>מַדּוּעַ כָּתוּב \"אֲפִילּוּ\"?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי מַפְתִּיעַ שֶׁחוּט דַּק כָּזֶה חָזָק יוֹתֵר מִמַּתֶּכֶת חֲזָקָה<\/li><li><span class=\"l\">ב.<\/span>כִּי גַּם הָעַכָּבִישׁ עַצְמוֹ חָזָק מְאוֹד<\/li><li><span class=\"l\">ג.<\/span>כִּי הָעַכָּבִישׁ בּוֹנֶה אֶת הָרֶשֶׁת שֶׁלּוֹ מִפְּלָדָה<\/li><li><span class=\"l\">ד.<\/span>כִּי חוּט פְּלָדָה הוּא חוּט חַלָּשׁ מְאוֹד<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. מָה אֶפְשָׁר לִלְמוֹד מִשּׁוּרוֹת 12–14?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>שֶׁהָעַכָּבִישׁ בּוֹנֶה רַק רֶשֶׁת אַחַת בְּכָל חַיָּיו<\/li><li><span class=\"l\">ב.<\/span>שֶׁהָעַכָּבִישׁ פּוֹחֵד מְאוֹד מֵהָרוּחַ וּמֵהַגֶּשֶׁם<\/li><li><span class=\"l\">ג.<\/span>שֶׁרֶשֶׁת יְשָׁנָה דְּבִיקָה יוֹתֵר מֵרֶשֶׁת חֲדָשָׁה<\/li><li><span class=\"l\">ד.<\/span>שֶׁהָעַכָּבִישׁ חָרוּץ, וְאֵינוֹ מְבַזְבֵּז אֶת הַמֶּשִׁי שֶׁלּוֹ<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">5. אֵיזֶה מִשְׁפָּט <u>אִי אֶפְשָׁר<\/u> לוֹמַר עַל פִּי הַקֶּטַע?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>חֵלֶק מֵהַחוּטִים בָּרֶשֶׁת אֵינָם דְּבִיקִים.<\/li><li><span class=\"l\">ב.<\/span>הָעַכָּבִישׁ מַרְגִּישׁ כְּשֶׁזְּבוּב נִלְכָּד בָּרֶשֶׁת.<\/li><li><span class=\"l\">ג.<\/span>רוֹב הָעַכְּבִישִׁים מְסוּכָּנִים לִבְנֵי אָדָם.<\/li><li><span class=\"l\">ד.<\/span>עַכְּבִישִׁים טוֹרְפִים זְבוּבִים וְיַתּוּשִׁים.<\/li><\/ol><\/div>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">קִרְאוּ אֶת הַסִּיפּוּר שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרָיו.<\/p>\n<div class=\"passage-title\">מָה מִסְתַּתֵּר בַּמַּחְסָן?<\/div>\n<ol class=\"lines long\">\n  <li>מָאיָה, יַלְדָּה בַּת שְׁמוֹנֶה, וְאָחִיהָ הַקָּטָן אֵיתָן גָּרִים בְּבַיִת עִם חָצֵר גְּדוֹלָה.<\/li>\n  <li>בִּקְצֵה הֶחָצֵר עוֹמֵד מַחְסָן יָשָׁן. בְּכָל עֶרֶב מָאיָה מַנִּיחָה לְיַד הַדֶּלֶת שֶׁלּוֹ<\/li>\n  <li>קַעֲרַת חָלָב בִּשְׁבִיל חֲתוּלָה אֲפוֹרָה שֶׁמְּבַקֶּרֶת בֶּחָצֵר.<\/li>\n  <li>כְּבָר שָׁבוּעַ שֶׁהַחֲתוּלָה לֹא נִרְאֲתָה בֶּחָצֵר, וּמָאיָה דָּאֲגָה לָהּ מְאוֹד.<\/li>\n  <li>\"מוּזָר,\" אָמְרָה לְאֵיתָן, \"הַחֲתוּלָה נֶעֶלְמָה, וּבְכָל זֹאת הַקְּעָרָה רֵיקָה בְּכָל בּוֹקֶר.\"<\/li>\n  <li>לַיְלָה אֶחָד הִתְעוֹרֵר אֵיתָן וְשָׁמַע רְעָשִׁים מוּזָרִים מִכִּיוּוּן הַמַּחְסָן.<\/li>\n  <li>הוּא רָץ אֶל הַמִּיטָּה שֶׁל מָאיָה וְהֵעִיר אוֹתָהּ. \"מָאיָה, תַּקְשִׁיבִי!\" לָחַשׁ.<\/li>\n  <li>מָאיָה הִקְשִׁיבָה. מִן הַמַּחְסָן נִשְׁמְעוּ רִשְׁרוּשִׁים, חֲרִיקוֹת וִילָלוֹת דַּקּוֹת.<\/li>\n  <li>\"יֵשׁ שָׁם גַּנָּב!\" אָמַר אֵיתָן, וְקוֹלוֹ רָעַד. \"הוּא בָּא לִגְנוֹב אֶת הָאוֹפַנַּיִים שֶׁלָּנוּ!\"<\/li>\n  <li>גַּם מָאיָה נִבְהֲלָה, אֲבָל הִיא לֹא רָצְתָה שֶׁאֵיתָן יִפְחַד עוֹד יוֹתֵר.<\/li>\n  <li>\"גַּנָּב לֹא מְיַילֵּל,\" אָמְרָה בְּקוֹל רָגוּעַ. \"בַּבּוֹקֶר נִבְדּוֹק יַחַד מָה יֵשׁ שָׁם.\"<\/li>\n  <li>בַּבּוֹקֶר לָקְחָה מָאיָה פָּנָס, וְאֵיתָן הֶחְזִיק מַטְאֲטֵא גָּדוֹל – לְיֶתֶר בִּיטָּחוֹן.<\/li>\n  <li>הֵם הָלְכוּ בְּשֶׁקֶט אֶל הַמַּחְסָן. הַקְּעָרָה שֶׁלְּיַד הַדֶּלֶת הָיְתָה שׁוּב רֵיקָה.<\/li>\n  <li>מָאיָה פָּתְחָה אֶת הַדֶּלֶת לְאַט לְאַט, וְהֵאִירָה בַּפָּנָס אֶל הַפִּינָּה הַחֲשׁוּכָה.<\/li>\n  <li>בְּתוֹךְ אַרְגַּז קַרְטוֹן יָשָׁן, עַל שְׂמִיכָה קְרוּעָה, שָׁכְבָה הַחֲתוּלָה הָאֲפוֹרָה.<\/li>\n  <li>לְיָדָהּ הִצְטוֹפְפוּ אַרְבָּעָה גּוּרִים זְעִירִים, וְעֵינֵיהֶם עֲדַיִין עֲצוּמוֹת.<\/li>\n  <li>הַגּוּרִים יִילְּלוּ בְּקוֹל דַּק וְחִיפְּשׂוּ אֶת אִימָּא שֶׁלָּהֶם.<\/li>\n  <li>\"אָז זֶה הַגַּנָּב שֶׁלְּךָ!\" צָחֲקָה מָאיָה. אֵיתָן הִנִּיחַ אֶת הַמַּטְאֲטֵא וְחִיֵּיךְ בִּמְבוּכָה.<\/li>\n  <li>\"עַכְשָׁיו אֲנִי מְבִינָה לְאָן נֶעֱלַם הֶחָלָב,\" אָמְרָה מָאיָה. \"אִימָּא חֲתוּלָה צְרִיכָה כּוֹחַ.\"<\/li>\n  <li>\"מֵהַיּוֹם אֲנִי אֲמַלֵּא אֶת הַקְּעָרָה,\" אָמַר אֵיתָן, \"וְאָבִיא לָהֶם גַּם שְׂמִיכָה חֲדָשָׁה.\"<\/li>\n  <li>הוּא הִתְכּוֹפֵף וְלָחַשׁ לַגּוּרִים: \"אַל תִּדְאֲגוּ, אֲנִי אֶשְׁמוֹר עֲלֵיכֶם מִפְּנֵי גַּנָּבִים.\"<\/li>\n  <li>בְּאוֹתוֹ לַיְלָה שׁוּב נִשְׁמְעוּ יְלָלוֹת מִן הַמַּחְסָן, אֲבָל הַפַּעַם אֵיתָן נִרְדַּם בְּחִיּוּךְ.<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה בְּכָל שְׁאֵלָה.<\/p>\n\n<div class=\"tight\">\n<div class=\"q\"><div class=\"stem\">1. בְּשׁוּרָה 12 כָּתוּב שֶׁאֵיתָן הֶחְזִיק מַטְאֲטֵא גָּדוֹל – לְיֶתֶר בִּיטָּחוֹן.<br>הַמַּטָּרָה שֶׁל הַמִּשְׁפָּט הַזֶּה הִיא –<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>לְהַרְאוֹת שֶׁאֵיתָן עֲדַיִין פָּחַד מִמָּה שֶׁיֵּשׁ בַּמַּחְסָן<\/li><li><span class=\"l\">ב.<\/span>לְסַפֵּר שֶׁאֵיתָן רָצָה לְנַקּוֹת אֶת הַמַּחְסָן<\/li><li><span class=\"l\">ג.<\/span>לְהַסְבִּיר שֶׁהַמַּטְאֲטֵא שַׁיָּיךְ לְאֵיתָן<\/li><li><span class=\"l\">ד.<\/span>לְהַדְגִּישׁ שֶׁאֵיתָן חָזָק יוֹתֵר מִמָּאיָה<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. מָה פֵּירוּשׁ הַמִּילָה \"הִצְטוֹפְפוּ\" (שׁוּרָה 16)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>רָבוּ זֶה עִם זֶה<\/li><li><span class=\"l\">ב.<\/span>בָּרְחוּ לְכָל הַכִּיוּוּנִים<\/li><li><span class=\"l\">ג.<\/span>קָפְצוּ וְשִׂיחֲקוּ<\/li><li><span class=\"l\">ד.<\/span>שָׁכְבוּ צְמוּדִים זֶה לָזֶה<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. מַדּוּעַ אֵיתָן חִיֵּיךְ בִּמְבוּכָה (שׁוּרָה 18)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי מָאיָה כָּעֲסָה עָלָיו שֶׁהֵעִיר אוֹתָהּ בַּלַּיְלָה<\/li><li><span class=\"l\">ב.<\/span>כִּי הֵבִין שֶׁפָּחַד לַשָּׁוְא, וְשֶׁאֵין בַּמַּחְסָן גַּנָּב<\/li><li><span class=\"l\">ג.<\/span>כִּי הַגּוּרִים נִבְהֲלוּ מֵהַמַּטְאֲטֵא שֶׁלּוֹ<\/li><li><span class=\"l\">ד.<\/span>כִּי הוּא לֹא אָהַב חֲתוּלִים<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. אֵיתָן חָשַׁב שֶׁיֵּשׁ בַּמַּחְסָן גַּנָּב. מָה בֶּאֱמֶת קָרָה בַּמַּחְסָן?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>גַּנָּב בָּא לִגְנוֹב אֶת הָאוֹפַנַּיִים שֶׁל הַיְּלָדִים<\/li><li><span class=\"l\">ב.<\/span>הָרוּחַ הֵזִיזָה אֶת הַדֶּלֶת שֶׁל הַמַּחְסָן<\/li><li><span class=\"l\">ג.<\/span>לַחֲתוּלָה הָאֲפוֹרָה נוֹלְדוּ שָׁם גּוּרִים<\/li><li><span class=\"l\">ד.<\/span>הַחֲתוּלָה נִתְקְעָה בְּתוֹךְ אַרְגָּז וְלֹא הִצְלִיחָה לָצֵאת<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">5. עַל אֵיזוֹ שְׁאֵלָה <u>אֵין<\/u> תְּשׁוּבָה בַּסִּיפּוּר?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כַּמָּה גּוּרִים הָיוּ בַּמַּחְסָן?<\/li><li><span class=\"l\">ב.<\/span>מָה הֶחְזִיק אֵיתָן בַּדֶּרֶךְ אֶל הַמַּחְסָן?<\/li><li><span class=\"l\">ג.<\/span>אֵיפֹה שָׁכְבָה הַחֲתוּלָה?<\/li><li><span class=\"l\">ד.<\/span>אֵילוּ שֵׁמוֹת נָתְנוּ הַיְּלָדִים לַגּוּרִים?<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">6. בְּאֵיזֶה צֶמֶד מִילִים הַמִּילִים <u>אֵינָן<\/u> מִילִים נִרְדָּפוֹת?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>מוּזָר – מְשׁוּנֶּה<\/li><li><span class=\"l\">ב.<\/span>רֵיקָה – מְלֵאָה<\/li><li><span class=\"l\">ג.<\/span>חֲשׁוּכָה – אֲפֵלָה<\/li><li><span class=\"l\">ד.<\/span>רָגוּעַ – שָׁלֵו<\/li><\/ol><\/div>\n\n<div data-accept=\"words:החתולה|חתולה|החתולה האפורה|חתולה אפורה\" class=\"q\"><div class=\"stem\">7. הַשְׁלִימוּ אֶת הַמִּשְׁפָּט לְפִי הַסִּיפּוּר. כִּתְבוּ מִילָּה אַחַת עַל הַקַּו.<\/div>\n<div>מִי שֶׁשָּׁתְתָה בְּכָל לַיְלָה אֶת הֶחָלָב מִן הַקְּעָרָה הָיְתָה <span class=\"blank\"><\/span> .<\/div><\/div>\n\n<p class=\"stop\">עִבְרוּ לָעַמּוּד הַבָּא רַק לְאַחַר שֶׁתְּקַבְּלוּ הוֹרָאָה לְכָךְ מֵהַמּוֹרָה.<\/p>\n\n<\/div>\n<div class=\"page-break\"><\/div>\n<h2>חֵלֶק שֵׁנִי: שְׁאֵלוֹת בְּחֶשְׁבּוֹן<\/h2>\n<h3>מְשִׂימָה א': תַּרְגִּילִים<\/h3>\n<p class=\"instr\">פִּתְרוּ אֶת הַתַּרְגִּילִים וְכִתְבוּ אֶת הַתּוֹצָאָה.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\">58 + 25 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\">91 − 36 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\">8 × 7 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">4. <span class=\"ex\">45 : 5 = <span class=\"blank\"><\/span><\/span><\/div>\n\n<h3>מְשִׂימָה ב': הַמִּסְפָּר הֶחָסֵר<\/h3>\n<p class=\"instr\">כִּתְבוּ אֶת הַמִּסְפָּר הֶחָסֵר בְּכָל תַּרְגִּיל.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\"><span class=\"blank\"><\/span> − 17 = 46<\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\">52 + <span class=\"blank\"><\/span> = 81<\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\"><span class=\"blank\"><\/span> × 6 = 48<\/span><\/div>\n<p class=\"instr\">כִּתְבוּ עַל הַקַּו מִסְפָּר מַתְאִים.<br>שִׂימוּ לֵב: בְּכָל תַּרְגִּיל יֵשׁ יוֹתֵר מִתְּשׁוּבָה נְכוֹנָה אַחַת.<\/p>\n<div data-accept=\"range:0-6\" class=\"q mathq\">4. <span class=\"ex\">6 × 7 &gt; 6 × <span class=\"blank\"><\/span><\/span><\/div>\n<div data-accept=\"gt:10\" class=\"q mathq\">5. <span class=\"ex\"><span class=\"blank\"><\/span> : 2 &gt; 10 : 2<\/span><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ג': בְּעָיוֹת מִילּוּלִיּוֹת<\/h3>\n<p class=\"instr\">קִרְאוּ כָּל בְּעָיָה וְהַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. בֶּן אָמַר: \"חָשַׁבְתִּי עַל מִסְפָּר. כָּפַלְתִּי אוֹתוֹ בְּ-3 וְהוֹסַפְתִּי 2. קִיבַּלְתִּי 20.\"<br>עַל אֵיזֶה מִסְפָּר חָשַׁב בֶּן?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>6<\/li><li><span class=\"l\">ב.<\/span>7<\/li><li><span class=\"l\">ג.<\/span>18<\/li><li><span class=\"l\">ד.<\/span>22<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. יַעֲרָה קָנְתָה מַחְבֶּרֶת בְּ-13 שְׁקָלִים, וְשִׁילְּמָה בִּשְׁטָר שֶׁל 20 שְׁקָלִים.<br>בְּאֵילוּ מַטְבְּעוֹת קִיבְּלָה יַעֲרָה אֶת הָעוֹדֶף?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>מַטְבֵּעַ שֶׁל 5 שְׁקָלִים וּמַטְבֵּעַ שֶׁל שֶׁקֶל 1<\/li><li><span class=\"l\">ב.<\/span>שְׁלוֹשָׁה מַטְבְּעוֹת שֶׁל 2 שְׁקָלִים<\/li><li><span class=\"l\">ג.<\/span>מַטְבֵּעַ שֶׁל 5 שְׁקָלִים וּמַטְבֵּעַ שֶׁל 2 שְׁקָלִים<\/li><li><span class=\"l\">ד.<\/span>מַטְבֵּעַ שֶׁל 5 שְׁקָלִים, מַטְבֵּעַ שֶׁל 2 שְׁקָלִים וּמַטְבֵּעַ שֶׁל שֶׁקֶל 1<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. יַעֲרָה כָּתְבָה סִדְרָה שֶׁל מִסְפָּרִים לְפִי חוּקִיּוּת:<br><span class=\"ex\">4, 10, 7, 13, 10, <span class=\"blank\"><\/span><\/span><br>אֵיזֶה מִסְפָּר צָרִיךְ לִהְיוֹת עַל הַקַּו?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>7<\/li><li><span class=\"l\">ב.<\/span>13<\/li><li><span class=\"l\">ג.<\/span>19<\/li><li><span class=\"l\">ד.<\/span>16<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. לְבֶן יֵשׁ 5 קוּפְסָאוֹת, וּבְכָל קוּפְסָה 4 עֶפְרוֹנוֹת. לְיַעֲרָה יֵשׁ 3 קוּפְסָאוֹת, וּבְכָל קוּפְסָה 6 עֶפְרוֹנוֹת.<br>בְּכַמָּה עֶפְרוֹנוֹת יֵשׁ לְבֶן יוֹתֵר מֵאֲשֶׁר לְיַעֲרָה?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>20<\/li><li><span class=\"l\">ב.<\/span>2<\/li><li><span class=\"l\">ג.<\/span>18<\/li><li><span class=\"l\">ד.<\/span>38<\/li><\/ol><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ד': חִידוֹת בְּצִיּוּרִים<\/h3>\n<p class=\"instr\">בְּכָל חִידָה, כָּל צִיּוּר מַסְתִּיר מִסְפָּר. אוֹתוֹ צִיּוּר מַסְתִּיר תָּמִיד אוֹתוֹ מִסְפָּר.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">♣<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>♥ + ♥ = 18<\/td><\/tr><tr><td>♥ + ♣ = 15<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>9<\/li><li><span class=\"l\">ב.<\/span>3<\/li><li><span class=\"l\">ג.<\/span>6<\/li><li><span class=\"l\">ד.<\/span>7<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">●<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>✿ + ✿ + ✿ + ✿ = 24<\/td><\/tr><tr><td>✿ + ● = 13<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>7<\/li><li><span class=\"l\">ב.<\/span>6<\/li><li><span class=\"l\">ג.<\/span>11<\/li><li><span class=\"l\">ד.<\/span>1<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">★<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>▲ + ★ = 11<\/td><\/tr><tr><td>▲ + ★ + ▲ = 17<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>6<\/li><li><span class=\"l\">ב.<\/span>11<\/li><li><span class=\"l\">ג.<\/span>4<\/li><li><span class=\"l\">ד.<\/span>5<\/li><\/ol><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ה': תַּרְגִּילֵי מְשׁוּלָּשִׁים<\/h3>\n<p class=\"instr\">בְּכָל תַּרְגִּיל הַמְּשׁוּלָּשׁ ∆ מַסְתִּיר סִפְרָה. בְּאוֹתוֹ תַּרְגִּיל כָּל הַמְּשׁוּלָּשִׁים מַסְתִּירִים אוֹתָהּ סִפְרָה.<br>אֵיזוֹ סִפְרָה מַסְתִּיר הַמְּשׁוּלָּשׁ? הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. <span class=\"ex\">2∆ + 2∆ = 50<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>0<\/li><li><span class=\"l\">ב.<\/span>5<\/li><li><span class=\"l\">ג.<\/span>2<\/li><li><span class=\"l\">ד.<\/span>7<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. <span class=\"ex\">1∆ + ∆1 = 55<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>4<\/li><li><span class=\"l\">ב.<\/span>5<\/li><li><span class=\"l\">ג.<\/span>3<\/li><li><span class=\"l\">ד.<\/span>6<\/li><\/ol><\/div>\n\n<p class=\"end\">סוֹף הַמִּבְחָן<\/p>\n\n<section class=\"answers\"><h2>פִּתְרוֹנוֹת – מבחן 2<\/h2>\n<table>\n<tr><th>שאלה<\/th><th>תשובה<\/th><th>הסבר + טריק<\/th><\/tr>\n<tr><th colspan=\"3\">קטע 1 – קורי העכביש<\/th><\/tr>\n<tr><td>1<\/td><td>ג<\/td><td>שורות 10–11: יש חוטים יבשים, והעכביש \"הולך רק עליהם\". טריק: בוחרים רק לפי הכתוב (ד נכון בקטע אבל לא עונה לשאלה).<\/td><\/tr>\n<tr><td>2<\/td><td>ב<\/td><td>\"להפך\" (מול \"מסוכנים\") + \"כי הם טורפים זבובים שמטרידים אותנו\" = עוזרים לנו. טריק: לקרוא שורה לפני ושורה אחרי; לחפש ניגוד.<\/td><\/tr>\n<tr><td>3<\/td><td>א<\/td><td>פלדה היא מתכת חזקה, והחוט דק ו\"נראה חלש\" – לכן זה מפתיע. טריק: ב\"אפילו\" שואלים \"מה מפתיע כאן?\".<\/td><\/tr>\n<tr><td>4<\/td><td>ד<\/td><td>הרשת נקרעת → בונה חדשה כמעט כל יום (חרוץ), ואוכל את הישנה כדי שהמשי לא יתבזבז. טריק: לסכם את השורות במשפט אחד לפני שקוראים את האפשרויות.<\/td><\/tr>\n<tr><td>5<\/td><td>ג<\/td><td>שורה 15: רוב העכבישים <b>אינם<\/b> מסוכנים. א (ש' 10), ב (ש' 8), ד (ש' 16) – כתובים. טריק: \"אי אפשר לומר\" – לסמן ✓ ליד כל משפט שמופיע; לשים לב למילת השלילה.<\/td><\/tr>\n<tr><th colspan=\"3\">קטע 2 – מה מסתתר במחסן?<\/th><\/tr>\n<tr><td>1<\/td><td>א<\/td><td>\"ליתר ביטחון\" – איתן לוקח משהו להגן על עצמו, כי עדיין חושש מגנב. טריק: \"המטרה של המשפט\" → להראות / להדגיש רגש של הדמות.<\/td><\/tr>\n<tr><td>2<\/td><td>ד<\/td><td>גורים זעירים בתוך ארגז, ליד האימא – שוכבים צמודים. טריק: מילה בהקשר – להציב כל אפשרות במשפט.<\/td><\/tr>\n<tr><td>3<\/td><td>ב<\/td><td>מאיה צוחקת \"אז זה הגנב שלך!\" – איתן מבין שפחד מגורי חתולים. טריק: רגש של דמות – לקרוא מה קרה רגע לפני.<\/td><\/tr>\n<tr><td>4<\/td><td>ג<\/td><td>שורות 15–17: החתולה והגורים במחסן; היללות היו שלהם. א = החשד של איתן (מסיח). טריק: \"מה באמת קרה\" – לחפש את הרמז המוקדם (הקערה שמתרוקנת, ש' 5).<\/td><\/tr>\n<tr><td>5<\/td><td>ד<\/td><td>ארבעה גורים (ש' 16), מטאטא (ש' 12), בארגז קרטון (ש' 15) – כתובים; שמות לגורים – לא. טריק: לסמן ✓ ליד מה שמופיע.<\/td><\/tr>\n<tr><td>6<\/td><td>ב<\/td><td>ריקה ↔ מלאה הן הפכים; שאר הצמדים נרדפים. טריק: להציב במשפט; לשים לב ל\"אינן\".<\/td><\/tr>\n<tr><td>7<\/td><td>החתולה<\/td><td>שורות 5 ו-19: הקערה מתרוקנת אף שהחתולה \"נעלמה\" – היא שתתה בלילה. מתקבל גם: חתולה / החתולה האפורה / אימא חתולה / אימא של הגורים. לא מתקבל: הגורים, איתן. טריק: השלמה לפי הקטע – לחזור לרמז.<\/td><\/tr>\n<tr><th colspan=\"3\">חשבון – משימה א'<\/th><\/tr>\n<tr><td>1<\/td><td>83<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">58+20=78<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">78+5=83<\/span>. טריק: להשלים לעשרת.<\/td><\/tr>\n<tr><td>2<\/td><td>55<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">91−40=51<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">51+4=55<\/span>. בדיקה: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">55+36=91<\/span>. טריק: לבדוק חיסור בחיבור.<\/td><\/tr>\n<tr><td>3<\/td><td>56<\/td><td>לוח הכפל: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">8×7=56<\/span>. טריק: ספרות בסדר הנכון (לא 65).<\/td><\/tr>\n<tr><td>4<\/td><td>9<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">9×5=45<\/span>, לכן <span dir=\"ltr\" style=\"unicode-bidi:isolate\">45:5=9<\/span>. טריק: חילוק כהפוך כפל.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ב'<\/th><\/tr>\n<tr><td>1<\/td><td>63<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">46+17=63<\/span>. טריק: נעלם במקום הראשון בחיסור – <b>מחברים<\/b>; בדיקה בהצבה (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">63−17=46<\/span>).<\/td><\/tr>\n<tr><td>2<\/td><td>29<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">81−52=29<\/span>. טריק: בדיקה בהצבה (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">52+29=81<\/span>).<\/td><\/tr>\n<tr><td>3<\/td><td>8<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">8×6=48<\/span>. טריק: חילוק כהפוך כפל.<\/td><\/tr>\n<tr><td>4<\/td><td>כל מספר מ-0 עד 6<\/td><td>6 משני הצדדים – משווים רק את מה ששונה: צריך מספר קטן מ-7. למשל 5 (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">42 &gt; 30<\/span>). לא מתקבל: 7 ומעלה.<\/td><\/tr>\n<tr><td>5<\/td><td>כל מספר גדול מ-10<\/td><td>מחלקים ב-2 בשני הצדדים – צריך מספר גדול מ-10. הכי נוח לבחור מספר זוגי, למשל 12 (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">6 &gt; 5<\/span>) או 20. לא מתקבל: 10 ומטה.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ג'<\/th><\/tr>\n<tr><td>1<\/td><td>א (6)<\/td><td>הופכים את הפעולות מהסוף: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">20−2=18<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">18:3=6<\/span>. בדיקה: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">6×3+2=20<\/span>. 18 = תוצאת ביניים. טריק: \"חשבתי על מספר\" – להפוך את הפעולה ולבדוק בהצבה.<\/td><\/tr>\n<tr><td>2<\/td><td>ג (5 + 2)<\/td><td>עודף: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">20−13=7<\/span>. רק <span dir=\"ltr\" style=\"unicode-bidi:isolate\">5+2=7<\/span>; א = 6, ב = 6, ד = 8. טריק: קודם מחשבים את העודף, ואז מחברים את המטבעות בכל אפשרות.<\/td><\/tr>\n<tr><td>3<\/td><td>ד (16)<\/td><td>ההפרשים: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">+6, −3, +6, −3<\/span> ולכן <span dir=\"ltr\" style=\"unicode-bidi:isolate\">10+6=16<\/span>. (כל מספר שני: 4, 7, 10 וגם 10, 13, 16.) טריק: סדרה מתחלפת – לכתוב את ההפרשים מתחת / להסתכל על כל מספר שני.<\/td><\/tr>\n<tr><td>4<\/td><td>ב (2)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">5×4=20<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">3×6=18<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">20−18=2<\/span>. 20 ו-18 = תוצאות ביניים, 38 = סכום. טריק: \"בכמה יותר\" = הפרש (חיסור), לא סכום.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ד'<\/th><\/tr>\n<tr><td>1<\/td><td>ג (6)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">♥=18:2=9<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">♣=15−9=6<\/span>. טריק: להתחיל מהשורה עם סמל אחד בלבד.<\/td><\/tr>\n<tr><td>2<\/td><td>א (7)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">✿=24:4=6<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">●=13−6=7<\/span>. טריק: לספור כמה פעמים הסמל מופיע (4, לא 2); בדיקה בהצבה.<\/td><\/tr>\n<tr><td>3<\/td><td>ד (5)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">▲+★=11<\/span> היא \"חבילה\": <span dir=\"ltr\" style=\"unicode-bidi:isolate\">▲=17−11=6<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">★=11−6=5<\/span>. 6 = הערך של ▲ (לא מה שנשאל). טריק: החלפת קבוצה שלמה; לענות על הסמל שנשאל.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ה'<\/th><\/tr>\n<tr><td>1<\/td><td>ב (5)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">25+25=50<\/span>. טריק: ספרת האחדות – <span dir=\"ltr\" style=\"unicode-bidi:isolate\">∆+∆<\/span> מסתיים ב-0 → 0 או 5; <span dir=\"ltr\" style=\"unicode-bidi:isolate\">20+20=40<\/span> לא מתאים.<\/td><\/tr>\n<tr><td>2<\/td><td>א (4)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">14+41=55<\/span>. טריק: ספרת האחדות – <span dir=\"ltr\" style=\"unicode-bidi:isolate\">∆+1<\/span> מסתיים ב-5 → 4; לבדוק בהצבה. 1∆ זה \"עשר ומשהו\".<\/td><\/tr>\n<\/table><\/section>", "id": 2, "pdf": "pdf/test_2.pdf", "questions": 30}, {"title": "מבחן תרגול 3", "html": "<section class=\"cover\">\n  <h1>מִבְחַן תִּרְגּוּל – שָׁלָב א'<\/h1>\n  <div>כִּיתָה ב' · מִבְחָן מִסְפָּר 3<\/div>\n  <div class=\"fields\">שֵׁם: ____________________<br>תַּאֲרִיךְ: ________________<\/div>\n<\/section>\n\n<h2>חֵלֶק רִאשׁוֹן: קִטְעֵי קְרִיאָה וּשְׁאֵלוֹת<\/h2>\n<p class=\"instr\">קִרְאוּ אֶת הַהוֹרָאוֹת שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרֵיהֶן.<\/p>\n<div class=\"passage-title\">אֵיךְ מְגַדְּלִים שְׁעוּעִית בְּצִנְצֶנֶת?<\/div>\n<ol class=\"lines\">\n  <li>רוֹצִים לִרְאוֹת בְּמוֹ עֵינֵיכֶם אֵיךְ זֶרַע קָטָן הוֹפֵךְ לְצֶמַח יָרוֹק?<\/li>\n  <li>לֹא צָרִיךְ גִּינָּה וְגַם לֹא עָצִיץ. מַסְפִּיקָה צִנְצֶנֶת אַחַת לְיַד הַחַלּוֹן.<\/li>\n  <li>מָה צָרִיךְ לְהָכִין? צִנְצֶנֶת זְכוּכִית שְׁקוּפָה, צֶמֶר גֶּפֶן, מְעַט מַיִם<\/li>\n  <li>וּשְׁלוֹשָׁה זְרָעִים שֶׁל שְׁעוּעִית יְבֵשָׁה. וְעַכְשָׁיו – לַעֲבוֹדָה!<\/li>\n  <li>שָׁלָב 1: מַשְׁרִים אֶת הַזְּרָעִים בְּכוֹס מַיִם לְמֶשֶׁךְ לַיְלָה שָׁלֵם.<\/li>\n  <li>שָׁלָב 2: מְרַפְּדִים אֶת תַּחְתִּית הַצִּנְצֶנֶת בְּשִׁכְבָה עָבָה שֶׁל צֶמֶר גֶּפֶן.<\/li>\n  <li>שָׁלָב 3: מַרְטִיבִים אֶת צֶמֶר הַגֶּפֶן בִּמְעַט מַיִם, עַד שֶׁהוּא לַח.<\/li>\n  <li>שָׁלָב 4: מַנִּיחִים אֶת הַזְּרָעִים בֵּין צֶמֶר הַגֶּפֶן וּבֵין דּוֹפֶן הַצִּנְצֶנֶת,<\/li>\n  <li>כָּךְ שֶׁאֶפְשָׁר יִהְיֶה לִרְאוֹת אוֹתָם מִבַּחוּץ.<\/li>\n  <li>שָׁלָב 5: מַעֲמִידִים אֶת הַצִּנְצֶנֶת לְיַד הַחַלּוֹן, וּמְחַכִּים בְּסַבְלָנוּת.<\/li>\n  <li>כַּמָּה עֵצוֹת חֲשׁוּבוֹת: בִּדְקוּ אֶת צֶמֶר הַגֶּפֶן בְּכָל יוֹם. אִם הוּא יָבֵשׁ,<\/li>\n  <li>הוֹסִיפוּ לוֹ כַּמָּה טִיפּוֹת מַיִם. הִיזָּהֲרוּ לֹא לְהָצִיף אֶת הַצִּנְצֶנֶת בְּמַיִם!<\/li>\n  <li>זְרָעִים שֶׁשּׁוֹכְבִים בְּתוֹךְ שְׁלוּלִית אֵינָם נוֹבְטִים, אֶלָּא נִרְקָבִים.<\/li>\n  <li>הַזְּרָעִים צְרִיכִים אוֹר, אֲבָל לֹא שֶׁמֶשׁ יְשִׁירָה. שֶׁמֶשׁ חֲזָקָה מִדַּי<\/li>\n  <li>מְיַיבֶּשֶׁת אֶת צֶמֶר הַגֶּפֶן בִּמְהִירוּת וַעֲלוּלָה לִפְגּוֹעַ בַּנְּבָטִים הָעֲדִינִים.<\/li>\n  <li>אַחֲרֵי שְׁלוֹשָׁה אוֹ אַרְבָּעָה יָמִים יִבְקַע מִכָּל זֶרַע שׁוֹרֶשׁ לָבָן וְקָטָן.<\/li>\n  <li>כַּמָּה יָמִים אַחַר כָּךְ יִצְמַח גַּם גִּבְעוֹל יָרוֹק, וְעָלָיו שְׁנֵי עָלִים רִאשׁוֹנִים.<\/li>\n  <li>כְּשֶׁהַצֶּמַח יַגִּיעַ לְגוֹבַהּ שְׂפַת הַצִּנְצֶנֶת, הַעֲבִירוּ אוֹתוֹ לְעָצִיץ עִם אֲדָמָה.<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>בִּשְׁאֵלוֹת 1–4 הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה. בִּשְׁאֵלָה 5 כִּתְבוּ אֶת הַתְּשׁוּבָה עַל הַקַּו.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. מָה עוֹשִׂים מִיָּד אַחֲרֵי שֶׁמְּרַפְּדִים אֶת תַּחְתִּית הַצִּנְצֶנֶת בְּצֶמֶר גֶּפֶן?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>מַשְׁרִים אֶת הַזְּרָעִים בְּכוֹס מַיִם<\/li><li><span class=\"l\">ב.<\/span>מַנִּיחִים אֶת הַזְּרָעִים בַּצִּנְצֶנֶת<\/li><li><span class=\"l\">ג.<\/span>מַרְטִיבִים אֶת צֶמֶר הַגֶּפֶן בִּמְעַט מַיִם<\/li><li><span class=\"l\">ד.<\/span>מַעֲמִידִים אֶת הַצִּנְצֶנֶת לְיַד הַחַלּוֹן<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. מָה פֵּירוּשׁ הַמִּילָה \"לַח\" (שׁוּרָה 7)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>רָטוֹב מְעַט<\/li><li><span class=\"l\">ב.<\/span>יָבֵשׁ מְאוֹד<\/li><li><span class=\"l\">ג.<\/span>לָבָן וְנָקִי<\/li><li><span class=\"l\">ד.<\/span>עָבֶה וְרַךְ<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. יֶלֶד רוֹצֶה לְגַדֵּל שְׁעוּעִית בְּצִנְצֶנֶת לְפִי הַהוֹרָאוֹת שֶׁבַּקֶּטַע.<br>אֵיפֹה כְּדַאי לוֹ לְהַעֲמִיד אֶת הַצִּנְצֶנֶת?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>בְּתוֹךְ אָרוֹן סָגוּר וְחָשׁוּךְ<\/li><li><span class=\"l\">ב.<\/span>לְיַד חַלּוֹן מוּאָר, בְּמָקוֹם שֶׁקַּרְנֵי הַשֶּׁמֶשׁ אֵינָן מַגִּיעוֹת אֵלָיו<\/li><li><span class=\"l\">ג.<\/span>עַל אֶדֶן הַחַלּוֹן, בְּמָקוֹם שֶׁהַשֶּׁמֶשׁ זוֹרַחַת עָלָיו כָּל הַיּוֹם<\/li><li><span class=\"l\">ד.<\/span>בַּמְּקָרֵר, כְּדֵי שֶׁצֶּמֶר הַגֶּפֶן לֹא יִתְיַיבֵּשׁ<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. בְּשׁוּרָה 13 כָּתוּב שֶׁזְּרָעִים שֶׁשּׁוֹכְבִים בְּתוֹךְ שְׁלוּלִית אֵינָם נוֹבְטִים, אֶלָּא נִרְקָבִים.<br>הַמַּטָּרָה שֶׁל הַמִּשְׁפָּט הַזֶּה הִיא –<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>לְסַפֵּר שֶׁשְּׁעוּעִית גְּדֵלָה בִּשְׁלוּלִיּוֹת<\/li><li><span class=\"l\">ב.<\/span>לְהַדְגִּישׁ שֶׁהַזְּרָעִים צְרִיכִים הַרְבֵּה אוֹר<\/li><li><span class=\"l\">ג.<\/span>לְשַׁכְנֵעַ אוֹתָנוּ לְהַשְׁקוֹת אֶת הַזְּרָעִים פְּעָמִים רַבּוֹת<\/li><li><span class=\"l\">ד.<\/span>לְהַסְבִּיר מַדּוּעַ אָסוּר לְהָצִיף אֶת הַצִּנְצֶנֶת בְּמַיִם<\/li><\/ol><\/div>\n\n<div data-accept=\"words:שורש|השורש|שורש לבן|שורש לבן וקטן\" class=\"q\"><div class=\"stem\">5. הַשְׁלִימוּ אֶת הַמִּשְׁפָּט לְפִי הַקֶּטַע. כִּתְבוּ מִילָה אַחַת עַל הַקַּו.<\/div>\n<p>הַדָּבָר הָרִאשׁוֹן שֶׁיּוֹצֵא מִן הַזֶּרַע הוּא <span class=\"blank\"><\/span> .<\/p><\/div>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">קִרְאוּ אֶת הַסִּיפּוּר שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרָיו.<\/p>\n<div class=\"passage-title\">אַלּוֹן רוֹצֶה כֶּלֶב<\/div>\n<ol class=\"lines long\">\n  <li>אַלּוֹן בֶּן הַשְּׁמוֹנֶה חָלַם עַל דָּבָר אֶחָד בִּלְבַד: כֶּלֶב מִשֶּׁלּוֹ.<\/li>\n  <li>\"כֶּלֶב הוּא לֹא צַעֲצוּעַ,\" אָמְרָה אִימָּא. \"צָרִיךְ לְטַפֵּל בּוֹ בְּכָל יוֹם.\"<\/li>\n  <li>\"אֲנִי אֲטַפֵּל בּוֹ! אֲנִי מַבְטִיחַ!\" קָרָא אַלּוֹן.<\/li>\n  <li>אַבָּא חָשַׁב רֶגַע וְאָמַר: \"הַבְטָחוֹת קַל לָתֵת. בּוֹא נִרְאֶה מַעֲשִׂים.<\/li>\n  <li>הַשְּׁכֵנָה צִילָה נוֹסַעַת לְשָׁבוּעַ. אִם תְּטַפֵּל בַּכֶּלֶב שֶׁלָּהּ, שׁוֹקוֹ,<\/li>\n  <li>שָׁבוּעַ שָׁלֵם בְּלִי שֶׁנַּזְכִּיר לְךָ – נְדַבֵּר עַל כֶּלֶב.\"<\/li>\n  <li>אַלּוֹן הִסְכִּים מִיָּד. \"שָׁבוּעַ? זֶה קַלֵּי קַלּוּת!\" אָמַר בְּבִיטָּחוֹן.<\/li>\n  <li>בִּשְׁלוֹשֶׁת הַיָּמִים הָרִאשׁוֹנִים הוּא קָם מוּקְדָּם, הֶאֱכִיל אֶת שׁוֹקוֹ וְיָצָא אִיתּוֹ לְטִיּוּל.<\/li>\n  <li>בַּיּוֹם הָרְבִיעִי יָרַד גֶּשֶׁם שׁוֹטֵף. אַלּוֹן הֵצִיץ מֵהַחַלּוֹן וְנֶאֱנַח.<\/li>\n  <li>\"אוּלַי הַיּוֹם שׁוֹקוֹ יְוַותֵּר עַל הַטִּיּוּל?\" שָׁאַל בְּשֶׁקֶט.<\/li>\n  <li>אִימָּא וְאַבָּא לֹא עָנוּ. הֵם רַק הִבִּיטוּ זֶה בָּזֶה.<\/li>\n  <li>אַלּוֹן הִבִּיט בְּשׁוֹקוֹ. הַכֶּלֶב עָמַד לְיַד הַדֶּלֶת וְכִשְׁכֵּשׁ בִּזְנָבוֹ.<\/li>\n  <li>\"טוֹב, בְּסֵדֶר,\" מִלְמֵל אַלּוֹן, לָבַשׁ מְעִיל וְיָצָא אִיתּוֹ אֶל הַגֶּשֶׁם.<\/li>\n  <li>בַּיּוֹם הַחֲמִישִׁי הִזְמִינוּ אוֹתוֹ הַחֲבֵרִים לְמִשְׂחַק כַּדּוּרֶגֶל בַּמִּגְרָשׁ.<\/li>\n  <li>אַלּוֹן כְּבָר רָץ אֶל הַדֶּלֶת, וְאָז נֶעֱצַר. \"קוֹדֶם שׁוֹקוֹ,\" אָמַר לְעַצְמוֹ.<\/li>\n  <li>הוּא טִיֵּיל עִם הַכֶּלֶב, וְרַק אַחַר כָּךְ הִצְטָרֵף לַמִּשְׂחָק.<\/li>\n  <li>בַּיּוֹם הַשְּׁבִיעִי חָזְרָה צִילָה, וְשׁוֹקוֹ קָפַץ עָלֶיהָ. אַלּוֹן הִרְגִּישׁ צְבִיטָה בַּלֵּב.<\/li>\n  <li>\"אָז מָה אַתָּה אוֹמֵר עַכְשָׁיו?\" שָׁאַל אַבָּא. \"עֲדַיִין קַלֵּי קַלּוּת?\"<\/li>\n  <li>\"דַּוְוקָא לֹא,\" הוֹדָה אַלּוֹן. \"זֶה הָיָה קָשֶׁה. אֲפִילּוּ בַּגֶּשֶׁם צָרִיךְ לָצֵאת.<\/li>\n  <li>אֲבָל כְּשֶׁשּׁוֹקוֹ שָׂמַח לִקְרָאתִי, שָׁכַחְתִּי אֶת כָּל הַקּוֹשִׁי.\"<\/li>\n  <li>אִימָּא חִיְּיכָה. \"זֹאת הַתְּשׁוּבָה שֶׁחִיכִּינוּ לָהּ,\" אָמְרָה.<\/li>\n  <li>\"בְּשַׁבָּת נִיסַּע יַחַד לִבְחוֹר כֶּלֶב – וְאַתָּה תִּבְחַר לוֹ שֵׁם.\"<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה בְּכָל שְׁאֵלָה.<\/p>\n\n<div class=\"tight\">\n<div class=\"q\"><div class=\"stem\">1. מַדּוּעַ בִּיקֵּשׁ אַבָּא מֵאַלּוֹן לְטַפֵּל בַּכֶּלֶב שֶׁל הַשְּׁכֵנָה?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי הַשְּׁכֵנָה צִילָה בִּיקְּשָׁה מֵאַלּוֹן עֶזְרָה<\/li><li><span class=\"l\">ב.<\/span>כְּדֵי לִרְאוֹת אִם אַלּוֹן בֶּאֱמֶת מְסוּגָּל לְטַפֵּל בְּכֶלֶב בְּכָל יוֹם<\/li><li><span class=\"l\">ג.<\/span>כִּי אַלּוֹן פָּחַד מִכְּלָבִים, וְאַבָּא רָצָה שֶׁיִּתְרַגֵּל אֲלֵיהֶם<\/li><li><span class=\"l\">ד.<\/span>כְּדֵי שֶׁאַלּוֹן יִשְׁכַּח שֶׁהוּא רוֹצֶה כֶּלֶב מִשֶּׁלּוֹ<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. בְּשׁוּרָה 9 כָּתוּב: \"אַלּוֹן הֵצִיץ מֵהַחַלּוֹן\".<br>אֵיזוֹ מִילָה יְכוֹלָה לְהַחְלִיף אֶת הַמִּילָה \"הֵצִיץ\"?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>קָפַץ<\/li><li><span class=\"l\">ב.<\/span>צָעַק<\/li><li><span class=\"l\">ג.<\/span>יָצָא<\/li><li><span class=\"l\">ד.<\/span>הִסְתַּכֵּל<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. בְּשׁוּרָה 19 אַלּוֹן אוֹמֵר: \"אֲפִילּוּ בַּגֶּשֶׁם צָרִיךְ לָצֵאת\".<br>מַדּוּעַ הוּא אוֹמֵר \"אֲפִילּוּ\"?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כְּדֵי לְהַדְגִּישׁ שֶׁמְּטַפְּלִים בְּכֶלֶב גַּם כְּשֶׁזֶּה לֹא נָעִים<\/li><li><span class=\"l\">ב.<\/span>כִּי שׁוֹקוֹ אוֹהֵב לְטַיֵּיל בַּגֶּשֶׁם יוֹתֵר מֵאֲשֶׁר בַּשֶּׁמֶשׁ<\/li><li><span class=\"l\">ג.<\/span>כִּי בְּכָל יְמֵי הַשָּׁבוּעַ יָרַד גֶּשֶׁם<\/li><li><span class=\"l\">ד.<\/span>כִּי גַּם הַחֲבֵרִים שֶׁלּוֹ שִׂיחֲקוּ כַּדּוּרֶגֶל בַּגֶּשֶׁם<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. מַדּוּעַ הִרְגִּישׁ אַלּוֹן צְבִיטָה בַּלֵּב (שׁוּרָה 17)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי שׁוֹקוֹ קָפַץ עָלָיו וְהִפִּיל אוֹתוֹ<\/li><li><span class=\"l\">ב.<\/span>כִּי פָּחַד שֶׁצִּילָה תִּכְעַס עָלָיו<\/li><li><span class=\"l\">ג.<\/span>כִּי נִקְשַׁר לְשׁוֹקוֹ, וְהָיָה לוֹ עָצוּב לְהִיפָּרֵד מִמֶּנּוּ<\/li><li><span class=\"l\">ד.<\/span>כִּי הָיָה עָיֵיף מְאוֹד מֵהַטִּיּוּלִים<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">5. עַל אֵיזוֹ שְׁאֵלָה <u>אֵין<\/u> תְּשׁוּבָה בַּסִּיפּוּר?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>בֶּן כַּמָּה אַלּוֹן?<\/li><li><span class=\"l\">ב.<\/span>אֵיזֶה שֵׁם בָּחַר אַלּוֹן לַכֶּלֶב הֶחָדָשׁ?<\/li><li><span class=\"l\">ג.<\/span>מָה שֵׁם הַכֶּלֶב שֶׁל הַשְּׁכֵנָה?<\/li><li><span class=\"l\">ד.<\/span>מָה עָשָׂה אַלּוֹן בַּיּוֹם שֶׁבּוֹ יָרַד גֶּשֶׁם?<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">6. בְּאֵיזֶה צֶמֶד מִילִים הַמִּילִים <u>אֵינָן<\/u> מִילִים נִרְדָּפוֹת?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>הִבִּיט – הִתְבּוֹנֵן<\/li><li><span class=\"l\">ב.<\/span>מִיָּד – תֵּכֶף<\/li><li><span class=\"l\">ג.<\/span>בִּלְבַד – רַק<\/li><li><span class=\"l\">ד.<\/span>מוּקְדָּם – מְאוּחָר<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">7. אֵיזוֹ כּוֹתֶרֶת אַחֶרֶת מַתְאִימָה לַסִּיפּוּר?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>\"הַמִּבְחָן שֶׁל אַלּוֹן\"<\/li><li><span class=\"l\">ב.<\/span>\"טִיּוּל בַּגֶּשֶׁם\"<\/li><li><span class=\"l\">ג.<\/span>\"הַכֶּלֶב שֶׁבָּרַח\"<\/li><li><span class=\"l\">ד.<\/span>\"מִשְׂחַק הַכַּדּוּרֶגֶל\"<\/li><\/ol><\/div>\n\n<p class=\"stop\">עִבְרוּ לָעַמּוּד הַבָּא רַק לְאַחַר שֶׁתְּקַבְּלוּ הוֹרָאָה לְכָךְ מֵהַמּוֹרָה.<\/p>\n\n<\/div>\n<div class=\"page-break\"><\/div>\n<h2>חֵלֶק שֵׁנִי: שְׁאֵלוֹת בְּחֶשְׁבּוֹן<\/h2>\n<h3>מְשִׂימָה א': תַּרְגִּילִים<\/h3>\n<p class=\"instr\">פִּתְרוּ אֶת הַתַּרְגִּילִים וְכִתְבוּ אֶת הַתּוֹצָאָה.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\">39 + 44 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\">83 − 27 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\">9 × 4 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">4. <span class=\"ex\">56 : 8 = <span class=\"blank\"><\/span><\/span><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ב': הַמִּסְפָּר הֶחָסֵר<\/h3>\n<p class=\"instr\">כִּתְבוּ אֶת הַמִּסְפָּר הֶחָסֵר בְּכָל תַּרְגִּיל.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\">29 + <span class=\"blank\"><\/span> = 65<\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\">84 − <span class=\"blank\"><\/span> = 39<\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\">5 × <span class=\"blank\"><\/span> = 45<\/span><\/div>\n<div class=\"q mathq\">4. <span class=\"ex\">9 + 15 = 3 × <span class=\"blank\"><\/span><\/span><\/div>\n<p class=\"instr\">כִּתְבוּ עַל הַקַּו מִסְפָּר מַתְאִים.<br>שִׂימוּ לֵב: בְּכָל תַּרְגִּיל יֵשׁ יוֹתֵר מִתְּשׁוּבָה נְכוֹנָה אַחַת.<\/p>\n<div data-accept=\"range:0-2\" class=\"q mathq\">5. <span class=\"ex\">27 + <span class=\"blank\"><\/span> &lt; 30<\/span><\/div>\n<div data-accept=\"range:27-80\" class=\"q mathq\">6. <span class=\"ex\">80 − <span class=\"blank\"><\/span> &lt; 80 − 26<\/span><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ג': בְּעָיוֹת מִילּוּלִיּוֹת<\/h3>\n<p class=\"instr\">קִרְאוּ כָּל בְּעָיָה וְהַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. אוֹר קָרָא בַּחוּפְשָׁה 3 סְפָרִים. לִיָּה קָרְאָה פִּי 2 סְפָרִים מֵאוֹר.<br>סַבְתָּא קָרְאָה פִּי 3 סְפָרִים מִלִּיָּה.<br>כַּמָּה סְפָרִים קָרְאָה סַבְתָּא?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>6<\/li><li><span class=\"l\">ב.<\/span>9<\/li><li><span class=\"l\">ג.<\/span>18<\/li><li><span class=\"l\">ד.<\/span>8<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. בַּשּׁוּק, 3 תַּפּוּחִים עוֹלִים 5 שְׁקָלִים.<br>כַּמָּה שְׁקָלִים עוֹלִים 9 תַּפּוּחִים?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>15<\/li><li><span class=\"l\">ב.<\/span>11<\/li><li><span class=\"l\">ג.<\/span>45<\/li><li><span class=\"l\">ד.<\/span>10<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. לִיָּה כָּתְבָה סִדְרָה שֶׁל מִסְפָּרִים לְפִי חוּקִיּוּת:<br><span class=\"ex\">50, 42, 35, 29, 24, <span class=\"blank\"><\/span><\/span><br>אֵיזֶה מִסְפָּר צָרִיךְ לִהְיוֹת עַל הַקַּו?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>21<\/li><li><span class=\"l\">ב.<\/span>20<\/li><li><span class=\"l\">ג.<\/span>19<\/li><li><span class=\"l\">ד.<\/span>18<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. אוֹר כָּתַב תַּרְגִּיל, אֲבָל שָׁכַח לִכְתּוֹב בּוֹ אֶת סִימַן הַפְּעוּלָּה:<br><span class=\"ex\">48 <span class=\"blank\"><\/span> 6 = 8<\/span><br>אֵיזֶה סִימָן חָסֵר בַּתַּרְגִּיל?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span><span class=\"ex\">+<\/span><\/li><li><span class=\"l\">ב.<\/span><span class=\"ex\">−<\/span><\/li><li><span class=\"l\">ג.<\/span><span class=\"ex\">×<\/span><\/li><li><span class=\"l\">ד.<\/span><span class=\"ex\">:<\/span><\/li><\/ol><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ד': חִידוֹת בְּצִיּוּרִים<\/h3>\n<p class=\"instr\">בְּכָל חִידָה, כָּל צִיּוּר מַסְתִּיר מִסְפָּר. אוֹתוֹ צִיּוּר מַסְתִּיר תָּמִיד אוֹתוֹ מִסְפָּר.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">✈&#xFE0E;<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>● + ● + ● = 27<\/td><\/tr><tr><td>● + ✈&#xFE0E; = 16<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>9<\/li><li><span class=\"l\">ב.<\/span>11<\/li><li><span class=\"l\">ג.<\/span>7<\/li><li><span class=\"l\">ד.<\/span>25<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">♠<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>☀&#xFE0E; + ☀&#xFE0E; = 12<\/td><\/tr><tr><td>☀&#xFE0E; + ♠ + ♠ = 22<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>8<\/li><li><span class=\"l\">ב.<\/span>16<\/li><li><span class=\"l\">ג.<\/span>6<\/li><li><span class=\"l\">ד.<\/span>10<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">▲<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>♣ + ♥ = 14<\/td><\/tr><tr><td>♣ + ♥ + ♣ + ♥ + ▲ = 31<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>17<\/li><li><span class=\"l\">ב.<\/span>14<\/li><li><span class=\"l\">ג.<\/span>7<\/li><li><span class=\"l\">ד.<\/span>3<\/li><\/ol><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ה': תַּרְגִּילֵי מְשׁוּלָּשִׁים<\/h3>\n<p class=\"instr\">בְּכָל תַּרְגִּיל הַמְּשׁוּלָּשׁ ∆ מַסְתִּיר סִפְרָה. בְּאוֹתוֹ תַּרְגִּיל כָּל הַמְּשׁוּלָּשִׁים מַסְתִּירִים אוֹתָהּ סִפְרָה.<br>אֵיזוֹ סִפְרָה מַסְתִּיר הַמְּשׁוּלָּשׁ? הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. <span class=\"ex\">3∆ + 1∆ = 56<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>3<\/li><li><span class=\"l\">ב.<\/span>8<\/li><li><span class=\"l\">ג.<\/span>6<\/li><li><span class=\"l\">ד.<\/span>4<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. <span class=\"ex\">∆∆ + 1 = 34<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>4<\/li><li><span class=\"l\">ב.<\/span>2<\/li><li><span class=\"l\">ג.<\/span>3<\/li><li><span class=\"l\">ד.<\/span>1<\/li><\/ol><\/div>\n\n<p class=\"end\">סוֹף הַמִּבְחָן<\/p>\n\n<section class=\"answers\"><h2>פִּתְרוֹנוֹת – מבחן 3<\/h2>\n<table>\n<tr><th>שאלה<\/th><th>תשובה<\/th><th>הסבר + טריק<\/th><\/tr>\n<tr><th colspan=\"3\">קטע 1 – איך מגדלים שעועית בצנצנת? (טקסט הוראות)<\/th><\/tr>\n<tr><td>1<\/td><td>ג<\/td><td>ריפוד = שלב 2 (ש' 6); מיד אחריו שלב 3 – מרטיבים (ש' 7). א' = שלב 1 (לפני), ב' = שלב 4. טריק: סדר שלבים – למצוא את השלב ולקרוא את המספר הבא.<\/td><\/tr>\n<tr><td>2<\/td><td>א<\/td><td>\"מרטיבים... במעט מים, עד שהוא לח\" – רטוב מעט. טריק: לקרוא את כל המשפט שסביב המילה.<\/td><\/tr>\n<tr><td>3<\/td><td>ב<\/td><td>ש' 10 + 14: ליד החלון, \"אור, אבל לא שמש ישירה\". ג' = שמש ישירה (הטקסט אומר להימנע); א', ד' = בלי אור. טריק: שאלת יישום – לחפש את ההמלצה ולפסול מה שהטקסט אוסר.<\/td><\/tr>\n<tr><td>4<\/td><td>ד<\/td><td>המשפט בא מיד אחרי \"היזהרו לא להציף\" (ש' 12) ומנמק את האזהרה. טריק: \"מטרת המשפט\" → כדי להסביר; לקרוא את השורה שלפני.<\/td><\/tr>\n<tr><td>5<\/td><td>שורש<\/td><td>ש' 16: \"יבקע מכל זרע שורש\", ורק אחר כך גבעול (ש' 17). מתקבל גם: \"שורש לבן\", \"שורש קטן\", \"השורש\". לא מתקבל: גבעול, עלים, נבט. טריק: השלמה – להעתיק מילה מהקטע, לא להמציא.<\/td><\/tr>\n<tr><th colspan=\"3\">קטע 2 – אלון רוצה כלב<\/th><\/tr>\n<tr><td>1<\/td><td>ב<\/td><td>ש' 4: \"הבטחות קל לתת. בוא נראה מעשים\" – אבא רוצה הוכחה. טריק: בוחרים רק לפי הכתוב (צילה לא ביקשה עזרה מאלון).<\/td><\/tr>\n<tr><td>2<\/td><td>ד<\/td><td>הציץ מהחלון = הסתכל (וראה גשם). טריק: להציב כל מילה במשפט ולבדוק שהמשמעות נשמרת.<\/td><\/tr>\n<tr><td>3<\/td><td>א<\/td><td>\"אפילו\" מדגיש מצב קשה ולא צפוי: גם כשיורד גשם יוצאים. גשם ירד רק ביום הרביעי. טריק: ב\"אפילו\" שואלים \"מה מפתיע/קשה כאן?\".<\/td><\/tr>\n<tr><td>4<\/td><td>ג<\/td><td>שוקו חוזר לבעלים, ואלון, שטיפל בו שבוע ונהנה (ש' 20), עצוב להיפרד. טריק: רגש של דמות – לבדוק מה קרה שורה לפני.<\/td><\/tr>\n<tr><td>5<\/td><td>ב<\/td><td>גיל (ש' 1), שם הכלב (ש' 5), היום הגשום (ש' 13) – מופיעים; השם שיבחר – עוד לא נבחר. טריק: לסמן ✓ ליד מה שמופיע.<\/td><\/tr>\n<tr><td>6<\/td><td>ד<\/td><td>מוקדם ↔ מאוחר – הפכים. שאר הצמדים קרובים במשמעות. טריק: לשים לב ל\"אינן\"; להציב במשפט.<\/td><\/tr>\n<tr><td>7<\/td><td>א<\/td><td>כל הסיפור הוא שבוע המבחן שבו אלון מוכיח שהוא מסוגל. ב', ד' = רק חלק מהסיפור; ג' לא קרה. טריק: כותרת מתאימה לכל הסיפור, לא לאירוע אחד.<\/td><\/tr>\n<tr><th colspan=\"3\">חשבון – משימה א'<\/th><\/tr>\n<tr><td>1<\/td><td>83<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">39+44 = 40+43 = 83<\/span>. טריק: להשלים לעשרת.<\/td><\/tr>\n<tr><td>2<\/td><td>56<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">83−30=53<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">53+3=56<\/span>. בדיקה: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">56+27=83<\/span>. טריק: לבדוק חיסור בחיבור.<\/td><\/tr>\n<tr><td>3<\/td><td>36<\/td><td>לוח הכפל: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">9×4=36<\/span>. טריק: ספרות בסדר הנכון (לא 63).<\/td><\/tr>\n<tr><td>4<\/td><td>7<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">7×8=56<\/span>, ולכן <span dir=\"ltr\" style=\"unicode-bidi:isolate\">56:8=7<\/span>. טריק: חילוק כהפוך כפל.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ב'<\/th><\/tr>\n<tr><td>1<\/td><td>36<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">65−29=36<\/span>. טריק: בדיקה בהצבה (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">29+36=65<\/span>).<\/td><\/tr>\n<tr><td>2<\/td><td>45<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">84−39=45<\/span>. טריק: כשהמחסר חסר – מחסרים את התוצאה מהמספר הראשון (לא מחברים!).<\/td><\/tr>\n<tr><td>3<\/td><td>9<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">5×9=45<\/span>. טריק: חילוק כהפוך כפל.<\/td><\/tr>\n<tr><td>4<\/td><td>8<\/td><td>מאזניים: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">9+15=24<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">3×8=24<\/span>. טריק: לכסות ולפתור קודם את הצד המלא (לא לכתוב 24!).<\/td><\/tr>\n<tr><td>5<\/td><td>0, 1 או 2<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">27+3=30<\/span> כבר לא קטן מ-30. טריק: גבול עליון – למצוא מתי מגיעים בדיוק ל-30 ולבחור פחות.<\/td><\/tr>\n<tr><td>6<\/td><td>כל מספר מ-27 עד 80<\/td><td>80 משני הצדדים; כדי שיישאר פחות צריך להוריד יותר מ-26. למשל 30. טריק: בחיסור הכיוון מתהפך.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ג'<\/th><\/tr>\n<tr><td>1<\/td><td>ג (18)<\/td><td>ליה: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">2×3=6<\/span>; סבתא: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">3×6=18<\/span>. טריק: שרשרת כפלית – \"פי 3 ממי?\" מליה, לא מאור (9); 6 = תוצאת ביניים.<\/td><\/tr>\n<tr><td>2<\/td><td>א (15)<\/td><td>9 תפוחים = 3 קבוצות של 3; <span dir=\"ltr\" style=\"unicode-bidi:isolate\">3×5=15<\/span>. טריק: יחס – כמה פעמים נכנסת הקבוצה; לא להוסיף 6 (11) ולא לכפול <span dir=\"ltr\" style=\"unicode-bidi:isolate\">9×5<\/span> (45).<\/td><\/tr>\n<tr><td>3<\/td><td>ב (20)<\/td><td>ההפרשים: 8, 7, 6, 5 ואז 4; <span dir=\"ltr\" style=\"unicode-bidi:isolate\">24−4=20<\/span>. טריק: סדרה יורדת – לכתוב את ההפרשים מתחת (19 = שוב פחות 5).<\/td><\/tr>\n<tr><td>4<\/td><td>ד (:)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">48:6=8<\/span>. (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">48+6=54<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">48−6=42<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">48×6<\/span> גדול מאוד.) טריק: סימן חסר – לנסות את 4 הסימנים; תוצאה קטנה בהרבה → חילוק.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ד'<\/th><\/tr>\n<tr><td>1<\/td><td>ג (7)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">●=27:3=9<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">✈&#xFE0E;=16−9=7<\/span>. טריק: להתחיל מהשורה עם סמל אחד בלבד (9 = הערך של ●, לא מה שנשאל).<\/td><\/tr>\n<tr><td>2<\/td><td>א (8)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">☀&#xFE0E;=6<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">♠+♠=22−6=16<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">♠=8<\/span>. טריק: סמל כפול + החלפה; לא לשכוח לחלק ב-2 (16).<\/td><\/tr>\n<tr><td>3<\/td><td>ד (3)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">♣+♥=14<\/span> היא \"חבילה\" שמופיעה פעמיים: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">14+14=28<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">31−28=3<\/span>. טריק: החלפת קבוצה שלמה (17 = הורדת חבילה אחת בלבד).<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ה'<\/th><\/tr>\n<tr><td>1<\/td><td>ב (8)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">38+18=56<\/span>. טריק: ספרת האחדות – <span dir=\"ltr\" style=\"unicode-bidi:isolate\">∆+∆<\/span> מסתיים ב-6 → 3 או 8; <span dir=\"ltr\" style=\"unicode-bidi:isolate\">33+13=46<\/span> לא מתאים.<\/td><\/tr>\n<tr><td>2<\/td><td>ג (3)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">33+1=34<\/span>. טריק: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">∆∆<\/span> הוא מספר דו-ספרתי עם שתי ספרות זהות; <span dir=\"ltr\" style=\"unicode-bidi:isolate\">34−1=33<\/span>.<\/td><\/tr>\n<\/table><\/section>", "id": 3, "pdf": "pdf/test_3.pdf", "questions": 31}, {"title": "מבחן תרגול 4", "html": "<section class=\"cover\">\n  <h1>מִבְחַן תִּרְגּוּל – שָׁלָב א'<\/h1>\n  <div>כִּיתָּה ב' · מִבְחָן מִסְפָּר 4<\/div>\n  <div class=\"fields\">שֵׁם: ____________________<br>תַּאֲרִיךְ: ________________<\/div>\n<\/section>\n\n<h2>חֵלֶק רִאשׁוֹן: קִטְעֵי קְרִיאָה וּשְׁאֵלוֹת<\/h2>\n<p class=\"instr\">קִרְאוּ אֶת קֶטַע הַמֵּידָע שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרָיו.<\/p>\n<div class=\"passage-title\">פִּינְגְּוִין הַקֵּיסָר<\/div>\n<ol class=\"lines\">\n  <li>בְּאַנְטַארְקְטִיקָה, הַיַּבֶּשֶׁת הַקָּרָה בְּיוֹתֵר בָּעוֹלָם, חַי עוֹף מְיוּחָד: פִּינְגְּוִין הַקֵּיסָר.<\/li>\n  <li>זֶהוּ הַפִּינְגְּוִין הַגָּדוֹל בְּיוֹתֵר, וְגוֹבְהוֹ כִּמְעַט כְּגוֹבַהּ שֶׁל יֶלֶד בְּכִיתָּה ב'.<\/li>\n  <li>רוֹב הַצִּיפּוֹרִים מְטִילוֹת בֵּיצִים בָּאָבִיב, כְּשֶׁמֶּזֶג הָאֲוִויר נָעִים וְחָמִים.<\/li>\n  <li>אֲבָל אִימָּא פִּינְגְּוִין מְטִילָה בֵּיצָה דַּוְוקָא בְּאֶמְצַע הַחוֹרֶף, כְּשֶׁהַקּוֹר נוֹרָא.<\/li>\n  <li>הִיא מְטִילָה בֵּיצָה אַחַת בִּלְבַד, וּמִיָּד מַעֲבִירָה אוֹתָהּ בִּזְהִירוּת אֶל הָאַבָּא.<\/li>\n  <li>אַחַר כָּךְ הָאִימָּא יוֹצֵאת לְמַסָּע אָרוֹךְ אֶל הַיָּם, כְּדֵי לֶאֱכוֹל דָּגִים וּלְהִתְחַזֵּק.<\/li>\n  <li>הָאַבָּא נִשְׁאָר לִשְׁמוֹר עַל הַבֵּיצָה. הוּא מַנִּיחַ אוֹתָהּ עַל כַּפּוֹת רַגְלָיו<\/li>\n  <li>וּמְכַסֶּה אוֹתָהּ בְּקֶפֶל עוֹר חַם. אִם הַבֵּיצָה תִּיגַּע בַּקֶּרַח, הִיא תִּקְפָּא בִּמְהֵרָה.<\/li>\n  <li>בְּמֶשֶׁךְ חוֹדְשַׁיִים הָאַבָּא עוֹמֵד כָּךְ בַּקּוֹר וּבָרוּחַ, וְאֵינוֹ אוֹכֵל דָּבָר!<\/li>\n  <li>כְּדֵי לְהִתְחַמֵּם, כָּל הָאֲבוֹת נִצְמָדִים זֶה לָזֶה בִּקְבוּצָה גְּדוֹלָה וּצְפוּפָה.<\/li>\n  <li>הֵם גַּם מִתְחַלְּפִים בַּמְּקוֹמוֹת: מִי שֶׁעָמַד בַּחוּץ, בָּרוּחַ, נִכְנָס לְהִתְחַמֵּם בָּאֶמְצַע.<\/li>\n  <li>כַּעֲבוֹר חוֹדְשַׁיִים הַבֵּיצָה בּוֹקַעַת, וְגוֹזָל קָטָן וְאָפוֹר מֵצִיץ מִתּוֹכָהּ.<\/li>\n  <li>בְּדִיּוּק אָז הָאִימָּא חוֹזֶרֶת מִן הַיָּם, וּבְבִטְנָהּ מָזוֹן רַב בִּשְׁבִיל הַגּוֹזָל.<\/li>\n  <li>אֵיךְ הִיא מוֹצֵאת אֶת מִשְׁפַּחְתָּהּ בֵּין אַלְפֵי פִּינְגְּוִינִים שֶׁנִּרְאִים אוֹתוֹ דָּבָר?<\/li>\n  <li>הִיא מְזַהָה אֶת הַקּוֹל שֶׁל הָאַבָּא! לְכָל פִּינְגְּוִין יֵשׁ קְרִיאָה מְיוּחֶדֶת מִשֶּׁלּוֹ.<\/li>\n  <li>עַכְשָׁיו הָאִימָּא שׁוֹמֶרֶת עַל הַגּוֹזָל, וְהָאַבָּא הָרָעֵב יוֹצֵא סוֹף־סוֹף אֶל הַיָּם.<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה בְּכָל שְׁאֵלָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. מַדּוּעַ הָאַבָּא מַנִּיחַ אֶת הַבֵּיצָה עַל כַּפּוֹת רַגְלָיו?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כְּדֵי שֶׁהָאִימָּא תְּזַהֶה אוֹתוֹ כְּשֶׁתַּחֲזוֹר מִן הַיָּם<\/li><li><span class=\"l\">ב.<\/span>כְּדֵי שֶׁיּוּכַל לָלֶכֶת אִיתָּהּ אֶל הַיָּם וְלֶאֱכוֹל דָּגִים<\/li><li><span class=\"l\">ג.<\/span>כְּדֵי שֶׁהַבֵּיצָה לֹא תִּיגַּע בַּקֶּרַח וְתִקְפָּא<\/li><li><span class=\"l\">ד.<\/span>כְּדֵי שֶׁהַבֵּיצָה תִּהְיֶה גְּדוֹלָה יוֹתֵר<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. בְּשׁוּרָה 4 כָּתוּב שֶׁאִימָּא פִּינְגְּוִין מְטִילָה בֵּיצָה דַּוְוקָא בְּאֶמְצַע הַחוֹרֶף.<br>מַדּוּעַ כָּתוּב \"דַּוְוקָא\"?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי זֶה מַפְתִּיעַ: רוֹב הַצִּיפּוֹרִים מְטִילוֹת בֵּיצִים כְּשֶׁחָמִים<\/li><li><span class=\"l\">ב.<\/span>כִּי הַפִּינְגְּוִינִים אוֹהֲבִים אֶת הַחוֹרֶף יוֹתֵר מֵאֶת הַקַּיִץ<\/li><li><span class=\"l\">ג.<\/span>כִּי בְּאֶמְצַע הַחוֹרֶף יֵשׁ בַּיָּם הַרְבֵּה דָּגִים<\/li><li><span class=\"l\">ד.<\/span>כִּי בַּחוֹרֶף הָאַבָּא אֵינוֹ אוֹכֵל דָּבָר<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. בְּשׁוּרָה 7 כָּתוּב: \"הוּא מַנִּיחַ אוֹתָהּ עַל כַּפּוֹת רַגְלָיו\".<br>לְמִי אוֹ לְמָה מִתְיַיחֶסֶת הַמִּילָה \"אוֹתָהּ\"?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>לָאִימָּא<\/li><li><span class=\"l\">ב.<\/span>לַבֵּיצָה<\/li><li><span class=\"l\">ג.<\/span>לָרֶגֶל<\/li><li><span class=\"l\">ד.<\/span>לַיַּבֶּשֶׁת<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. מָה אֶפְשָׁר לִלְמוֹד מִשּׁוּרוֹת 10–11?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>שֶׁהָאֲבוֹת רָבִים זֶה עִם זֶה עַל הַמָּקוֹם שֶׁבָּאֶמְצַע<\/li><li><span class=\"l\">ב.<\/span>שֶׁבְּאֶמְצַע הַקְּבוּצָה קַר יוֹתֵר מֵאֲשֶׁר בַּחוּץ<\/li><li><span class=\"l\">ג.<\/span>שֶׁהָאִימָּהוֹת מְחַמְּמוֹת אֶת הָאֲבוֹת בַּחוֹרֶף<\/li><li><span class=\"l\">ד.<\/span>שֶׁהָאֲבוֹת עוֹזְרִים זֶה לָזֶה לְהִתְגַּבֵּר עַל הַקּוֹר<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">5. עַל אֵיזוֹ שְׁאֵלָה <u>אֵין<\/u> תְּשׁוּבָה בַּקֶּטַע?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כַּמָּה בֵּיצִים מְטִילָה אִימָּא פִּינְגְּוִין?<\/li><li><span class=\"l\">ב.<\/span>כַּמָּה זְמַן שׁוֹמֵר הָאַבָּא עַל הַבֵּיצָה?<\/li><li><span class=\"l\">ג.<\/span>כַּמָּה שׁוֹקֵל פִּינְגְּוִין הַקֵּיסָר?<\/li><li><span class=\"l\">ד.<\/span>אֵיךְ הָאִימָּא מוֹצֵאת אֶת הָאַבָּא כְּשֶׁהִיא חוֹזֶרֶת?<\/li><\/ol><\/div>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">קִרְאוּ אֶת הַסִּיפּוּר שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרָיו.<\/p>\n<div class=\"passage-title\">יוֹם הַהוּלֶּדֶת שֶׁל שִׁירָן<\/div>\n<ol class=\"lines long\">\n  <li>הַבּוֹקֶר קָמָה שִׁירָן נִרְגֶּשֶׁת מְאוֹד: הַיּוֹם יוֹם הַהוּלֶּדֶת הַשְּׁמִינִי שֶׁלָּהּ!<\/li>\n  <li>בַּכִּיתָּה שֶׁל הַמּוֹרָה דַּפְנָה, כָּל יֶלֶד שֶׁחוֹגֵג יוֹם הוּלֶּדֶת מְקַבֵּל כֶּתֶר,<\/li>\n  <li>וְכָל הַכִּיתָּה שָׁרָה לוֹ שִׁיר כְּבָר בַּשִּׁיעוּר הָרִאשׁוֹן.<\/li>\n  <li>לְיַד הַשַּׁעַר פָּגְשָׁה שִׁירָן אֶת גִּלְעָד, שֶׁחָזַר לְבֵית הַסֵּפֶר אַחֲרֵי שָׁבוּעַ שֶׁל מַחֲלָה.<\/li>\n  <li>כְּשֶׁנִּכְנְסוּ לַכִּיתָּה, רָאֲתָה שִׁירָן שְׁלוֹשָׁה יְלָדִים מִתְלַחֲשִׁים לְיַד הַלּוּחַ.<\/li>\n  <li>כְּשֶׁהִתְקָרְבָה הֵם הִשְׁתַּתְּקוּ, וְאַחַת הַבָּנוֹת הִסְתִּירָה דַּף צִבְעוֹנִי מֵאֲחוֹרֵי גַּבָּהּ.<\/li>\n  <li>הַמּוֹרָה דַּפְנָה לִימְּדָה חֶשְׁבּוֹן, וְלֹא אָמְרָה אֲפִילּוּ מִילָּה אַחַת עַל יוֹם הַהוּלֶּדֶת.<\/li>\n  <li>בַּהַפְסָקָה יָשְׁבָה שִׁירָן עַל סַפְסָל בֶּחָצֵר, וְעֵינֶיהָ הִתְמַלְּאוּ דְּמָעוֹת.<\/li>\n  <li>\"הַמּוֹרָה פָּשׁוּט שָׁכְחָה אוֹתִי,\" לָחֲשָׁה לְגִלְעָד.<\/li>\n  <li>\"גַּם אֲנִי חוֹשֵׁב כָּךְ,\" נֶאֱנַח גִּלְעָד. \"וּמוּזָר שֶׁאַף יֶלֶד לֹא אָמַר לָךְ מַזָּל טוֹב.\"<\/li>\n  <li>\"אוּלַי כְּדַאי לְהַזְכִּיר לָהּ?\" הִצִּיעַ. שִׁירָן הֵנִידָה בְּרֹאשָׁהּ: \"לֹא, אֲנִי מִתְבַּיֶּישֶׁת.\"<\/li>\n  <li>לִפְנֵי הַשִּׁיעוּר הָאַחֲרוֹן נִיגְּשָׁה הַמּוֹרָה אֶל שִׁירָן וְהוֹשִׁיטָה לָהּ מַעֲטָפָה.<\/li>\n  <li>\"שִׁירָן, בְּבַקָּשָׁה קְחִי אֶת הַמַּעֲטָפָה לַמַּזְכִּירוּת. גִּלְעָד יְלַוֶּוה אוֹתָךְ,\" אָמְרָה.<\/li>\n  <li>הֵם הָלְכוּ לְאַט בַּמִּסְדְּרוֹן. \"אֲפִילּוּ עַכְשָׁיו הִיא לֹא נִזְכְּרָה,\" מִלְמְלָה שִׁירָן.<\/li>\n  <li>כְּשֶׁחָזְרוּ, הַדֶּלֶת הָיְתָה סְגוּרָה, וְהַכִּיתָּה הָיְתָה חֲשׁוּכָה וְדוֹמֶמֶת.<\/li>\n  <li>\"לְאָן נֶעֶלְמוּ כּוּלָּם?\" תָּמַהּ גִּלְעָד, וּפָתַח אֶת הַדֶּלֶת בִּזְהִירוּת.<\/li>\n  <li>פִּתְאוֹם נִדְלַק הָאוֹר. \"הַפְתָּעָה!\" צָעֲקוּ כָּל הַיְּלָדִים, וּפָרְצוּ בְּשִׁיר.<\/li>\n  <li>הַכִּיתָּה הָיְתָה מְקוּשֶּׁטֶת בְּבָלוֹנִים, וְעַל הַשּׁוּלְחָן חִיכְּתָה עוּגָה גְּדוֹלָה.<\/li>\n  <li>עַל הַלּוּחַ נִתְלָה דַּף צִבְעוֹנִי, וְעָלָיו בְּרָכוֹת וְצִיּוּרִים מִכָּל יַלְדֵי הַכִּיתָּה.<\/li>\n  <li>\"עַכְשָׁיו אֲנִי מְבִינָה עַל מָה הֵם הִתְלַחֲשׁוּ בַּבּוֹקֶר!\" צָחֲקָה שִׁירָן.<\/li>\n  <li>הַמּוֹרָה הִנִּיחָה כֶּתֶר זָהוֹב עַל רֹאשָׁהּ: \"אֶת הַכֶּתֶר הֵכַנּוּ כְּבָר לִפְנֵי כַּמָּה יָמִים!\"<\/li>\n  <li>שִׁירָן חִיְּיכָה מֵאוֹזֶן לְאוֹזֶן. \"זֶה יוֹם הַהוּלֶּדֶת הֲכִי יָפֶה שֶׁהָיָה לִי,\" אָמְרָה.<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה בְּכָל שְׁאֵלָה.<\/p>\n\n<div class=\"tight\">\n<div class=\"q\"><div class=\"stem\">1. בְּשׁוּרוֹת 2–3 מְסוּפָּר מָה קוֹרֶה בַּכִּיתָּה כְּשֶׁיֶּלֶד חוֹגֵג יוֹם הוּלֶּדֶת.<br>מַדּוּעַ מְסוּפָּר עַל כָּךְ בִּתְחִילַּת הַסִּיפּוּר?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כְּדֵי לְשַׁכְנֵעַ מוֹרוֹת אֲחֵרוֹת לַחְגּוֹג יְמֵי הוּלֶּדֶת בַּכִּיתָּה<\/li><li><span class=\"l\">ב.<\/span>כְּדֵי לְהַסְבִּיר מַדּוּעַ שִׁירָן חִיכְּתָה לְכֶתֶר וּלְשִׁיר כְּבָר בַּבּוֹקֶר<\/li><li><span class=\"l\">ג.<\/span>כְּדֵי לְהַסְבִּיר מַדּוּעַ גִּלְעָד לֹא בָּא לְבֵית הַסֵּפֶר<\/li><li><span class=\"l\">ד.<\/span>כְּדֵי לְהַדְגִּישׁ שֶׁהַמּוֹרָה דַּפְנָה שׁוֹכַחַת הַרְבֵּה דְּבָרִים<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. מַדּוּעַ עֵינֶיהָ שֶׁל שִׁירָן הִתְמַלְּאוּ דְּמָעוֹת (שׁוּרָה 8)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי גִּלְעָד הָיָה חוֹלֶה שָׁבוּעַ שָׁלֵם<\/li><li><span class=\"l\">ב.<\/span>כִּי לֹא הִצְלִיחָה לִפְתּוֹר אֶת הַתַּרְגִּילִים בְּחֶשְׁבּוֹן<\/li><li><span class=\"l\">ג.<\/span>כִּי נָפְלָה מִן הַסַּפְסָל בֶּחָצֵר<\/li><li><span class=\"l\">ד.<\/span>כִּי חָשְׁבָה שֶׁהַמּוֹרָה שָׁכְחָה אֶת יוֹם הַהוּלֶּדֶת שֶׁלָּהּ<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. מָה פֵּירוּשׁ הַמִּילָה \"דּוֹמֶמֶת\" (שׁוּרָה 15)?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>שְׁקֵטָה<\/li><li><span class=\"l\">ב.<\/span>רוֹעֶשֶׁת<\/li><li><span class=\"l\">ג.<\/span>מוּאֶרֶת<\/li><li><span class=\"l\">ד.<\/span>מְקוּשֶּׁטֶת<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. מַדּוּעַ בִּיקְּשָׁה הַמּוֹרָה מִשִּׁירָן לָקַחַת מַעֲטָפָה לַמַּזְכִּירוּת (שׁוּרוֹת 12–13)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי הַמַּזְכִּירָה חִיכְּתָה לַמַּעֲטָפָה כְּבָר מֵהַבּוֹקֶר<\/li><li><span class=\"l\">ב.<\/span>כִּי שִׁירָן וְגִלְעָד הִפְרִיעוּ בַּשִּׁיעוּר<\/li><li><span class=\"l\">ג.<\/span>כְּדֵי שֶׁשִּׁירָן תֵּצֵא מֵהַכִּיתָּה, וְהַיְּלָדִים יוּכְלוּ לְהָכִין אֶת הַהַפְתָּעָה<\/li><li><span class=\"l\">ד.<\/span>כְּדֵי שֶׁשִּׁירָן תַּזְכִּיר לַמַּזְכִּירָה אֶת יוֹם הַהוּלֶּדֶת<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">5. שִׁירָן וְגִלְעָד הָיוּ בְּטוּחִים שֶׁהַמּוֹרָה שָׁכְחָה אֶת יוֹם הַהוּלֶּדֶת.<br>מָה קָרָה בֶּאֱמֶת?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>הַמּוֹרָה וְהַיְּלָדִים זָכְרוּ אֶת יוֹם הַהוּלֶּדֶת, וְהֵכִינוּ לְשִׁירָן הַפְתָּעָה<\/li><li><span class=\"l\">ב.<\/span>הַמּוֹרָה שָׁכְחָה אֶת יוֹם הַהוּלֶּדֶת, וְנִזְכְּרָה בּוֹ רַק בְּסוֹף הַיּוֹם<\/li><li><span class=\"l\">ג.<\/span>הַיְּלָדִים כָּעֲסוּ עַל שִׁירָן, וְלָכֵן לֹא בֵּירְכוּ אוֹתָהּ בַּבּוֹקֶר<\/li><li><span class=\"l\">ד.<\/span>הַמּוֹרָה חָשְׁבָה שֶׁיּוֹם הַהוּלֶּדֶת שֶׁל שִׁירָן יִהְיֶה רַק מָחָר<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">6. אֵיזֶה מִשְׁפָּט <u>אִי אֶפְשָׁר<\/u> לוֹמַר עַל פִּי הַסִּיפּוּר?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>שִׁירָן הִתְבַּיְּישָׁה לְהַזְכִּיר לַמּוֹרָה אֶת יוֹם הַהוּלֶּדֶת.<\/li><li><span class=\"l\">ב.<\/span>יַלְדֵי הַכִּיתָּה כָּתְבוּ לְשִׁירָן בְּרָכוֹת.<\/li><li><span class=\"l\">ג.<\/span>גִּלְעָד לֹא הָיָה בְּבֵית הַסֵּפֶר בַּשָּׁבוּעַ שֶׁלִּפְנֵי יוֹם הַהוּלֶּדֶת.<\/li><li><span class=\"l\">ד.<\/span>גִּלְעָד יָדַע עַל הַהַפְתָּעָה כְּבָר בַּבּוֹקֶר.<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">7. בְּאֵיזֶה צֶמֶד מִילִים הַמִּילִים <u>אֵינָן<\/u> מִילִים נִרְדָּפוֹת?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>פִּתְאוֹם – לְפֶתַע<\/li><li><span class=\"l\">ב.<\/span>לָחֲשָׁה – צָעֲקָה<\/li><li><span class=\"l\">ג.<\/span>תָּמַהּ – הִתְפַּלֵּא<\/li><li><span class=\"l\">ד.<\/span>הוֹשִׁיטָה – הִגִּישָׁה<\/li><\/ol><\/div>\n\n<p class=\"stop\">עִבְרוּ לָעַמּוּד הַבָּא רַק לְאַחַר שֶׁתְּקַבְּלוּ הוֹרָאָה לְכָךְ מֵהַמּוֹרָה.<\/p>\n\n<\/div>\n<div class=\"page-break\"><\/div>\n<h2>חֵלֶק שֵׁנִי: שְׁאֵלוֹת בְּחֶשְׁבּוֹן<\/h2>\n<h3>מְשִׂימָה א': תַּרְגִּילִים<\/h3>\n<p class=\"instr\">פִּתְרוּ אֶת הַתַּרְגִּילִים וְכִתְבוּ אֶת הַתּוֹצָאָה.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\">67 + 26 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\">70 − 43 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\">6 × 8 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">4. <span class=\"ex\">42 : 6 = <span class=\"blank\"><\/span><\/span><\/div>\n\n<h3>מְשִׂימָה ב': הַמִּסְפָּר הֶחָסֵר<\/h3>\n<p class=\"instr\">כִּתְבוּ אֶת הַמִּסְפָּר הֶחָסֵר בְּכָל תַּרְגִּיל.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\"><span class=\"blank\"><\/span> − 28 = 35<\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\">47 + <span class=\"blank\"><\/span> = 93<\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\">9 × <span class=\"blank\"><\/span> = 72<\/span><\/div>\n<p class=\"instr\">כִּתְבוּ עַל הַקַּו מִסְפָּר מַתְאִים.<br>שִׂימוּ לֵב: בְּכָל תַּרְגִּיל יֵשׁ יוֹתֵר מִתְּשׁוּבָה נְכוֹנָה אַחַת.<\/p>\n<div data-accept=\"gt:3\" class=\"q mathq\">4. <span class=\"ex\">9 × 3 &lt; 9 × <span class=\"blank\"><\/span><\/span><\/div>\n<div data-accept=\"range:0-18\" class=\"q mathq\">5. <span class=\"ex\">54 + 19 &gt; 54 + <span class=\"blank\"><\/span><\/span><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ג': בְּעָיוֹת מִילּוּלִיּוֹת<\/h3>\n<p class=\"instr\">קִרְאוּ כָּל בְּעָיָה וְהַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. לְשָׁקֵד יֵשׁ 12 בּוּלִים. לְאַלְמוֹג יֵשׁ 4 בּוּלִים פָּחוֹת מֵאֲשֶׁר לְשָׁקֵד. לַאֲחוֹתָם יֵשׁ 3 בּוּלִים יוֹתֵר מֵאֲשֶׁר לְאַלְמוֹג.<br>כַּמָּה בּוּלִים יֵשׁ לִשְׁלוֹשְׁתָּם בְּיַחַד?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>23<\/li><li><span class=\"l\">ב.<\/span>27<\/li><li><span class=\"l\">ג.<\/span>31<\/li><li><span class=\"l\">ד.<\/span>35<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. אַלְמוֹג קָנָה כַּדּוּר בְּ-32 שְׁקָלִים, וְשִׁילֵּם לַמּוֹכֵר 50 שְׁקָלִים. לַמּוֹכֵר יֵשׁ מַטְבְּעוֹת שֶׁל 10 שְׁקָלִים, שֶׁל 5 שְׁקָלִים, שֶׁל 2 שְׁקָלִים וְשֶׁל שֶׁקֶל 1.<br>מָה מִסְפַּר הַמַּטְבְּעוֹת הַקָּטָן בְּיוֹתֵר שֶׁבּוֹ הַמּוֹכֵר יָכוֹל לָתֵת לְאַלְמוֹג אֶת הָעוֹדֶף?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>4<\/li><li><span class=\"l\">ב.<\/span>3<\/li><li><span class=\"l\">ג.<\/span>5<\/li><li><span class=\"l\">ד.<\/span>18<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. בְּאֵיזֶה תַּרְגִּיל הַתּוֹצָאָה הִיא הַקְּטַנָּה בְּיוֹתֵר?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span><span class=\"ex\">7 × 3<\/span><\/li><li><span class=\"l\">ב.<\/span><span class=\"ex\">11 + 9<\/span><\/li><li><span class=\"l\">ג.<\/span><span class=\"ex\">40 : 2<\/span><\/li><li><span class=\"l\">ד.<\/span><span class=\"ex\">45 − 26<\/span><\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. לְאַלְמוֹג יֵשׁ 34 גּוּלּוֹת וּלְשָׁקֵד יֵשׁ 18 גּוּלּוֹת.<br>כַּמָּה גּוּלּוֹת צָרִיךְ אַלְמוֹג לָתֵת לְשָׁקֵד, כְּדֵי שֶׁלִּשְׁנֵיהֶם יִהְיֶה אוֹתוֹ מִסְפַּר גּוּלּוֹת?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>16<\/li><li><span class=\"l\">ב.<\/span>8<\/li><li><span class=\"l\">ג.<\/span>4<\/li><li><span class=\"l\">ד.<\/span>26<\/li><\/ol><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ד': חִידוֹת בְּצִיּוּרִים<\/h3>\n<p class=\"instr\">בְּכָל חִידָה, כָּל צִיּוּר מַסְתִּיר מִסְפָּר. אוֹתוֹ צִיּוּר מַסְתִּיר תָּמִיד אוֹתוֹ מִסְפָּר.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">★<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>✈&#xFE0E; + ✈&#xFE0E; = 16<\/td><\/tr><tr><td>✈&#xFE0E; + ★ + ★ = 20<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>6<\/li><li><span class=\"l\">ב.<\/span>4<\/li><li><span class=\"l\">ג.<\/span>8<\/li><li><span class=\"l\">ד.<\/span>12<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">☂&#xFE0E;<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>♠&#xFE0E; + ♠&#xFE0E; + ♠&#xFE0E; = 15<\/td><\/tr><tr><td>♠&#xFE0E; + ☂&#xFE0E; = 13<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>5<\/li><li><span class=\"l\">ב.<\/span>10<\/li><li><span class=\"l\">ג.<\/span>8<\/li><li><span class=\"l\">ד.<\/span>18<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">▲<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>▲ + ● = 17<\/td><\/tr><tr><td>▲ + ● + ● = 25<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>8<\/li><li><span class=\"l\">ב.<\/span>9<\/li><li><span class=\"l\">ג.<\/span>7<\/li><li><span class=\"l\">ד.<\/span>17<\/li><\/ol><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ה': תַּרְגִּילֵי מְשׁוּלָּשִׁים<\/h3>\n<p class=\"instr\">בְּכָל תַּרְגִּיל הַמְּשׁוּלָּשׁ ∆ מַסְתִּיר סִפְרָה. בְּאוֹתוֹ תַּרְגִּיל כָּל הַמְּשׁוּלָּשִׁים מַסְתִּירִים אוֹתָהּ סִפְרָה.<br>אֵיזוֹ סִפְרָה מַסְתִּיר הַמְּשׁוּלָּשׁ? הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. <span class=\"ex\">4∆ + 4∆ = 86<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>6<\/li><li><span class=\"l\">ב.<\/span>8<\/li><li><span class=\"l\">ג.<\/span>2<\/li><li><span class=\"l\">ד.<\/span>3<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. <span class=\"ex\">∆7 + ∆7 = 94<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>2<\/li><li><span class=\"l\">ב.<\/span>9<\/li><li><span class=\"l\">ג.<\/span>4<\/li><li><span class=\"l\">ד.<\/span>5<\/li><\/ol><\/div>\n\n<p class=\"end\">סוֹף הַמִּבְחָן<\/p>\n\n<section class=\"answers\"><h2>פִּתְרוֹנוֹת – מבחן 4<\/h2>\n<table>\n<tr><th>שאלה<\/th><th>תשובה<\/th><th>הסבר + טריק<\/th><\/tr>\n<tr><th colspan=\"3\">קטע 1 – פינגווין הקיסר<\/th><\/tr>\n<tr><td>1<\/td><td>ג<\/td><td>שורה 8: \"אם הביצה תיגע בקרח, היא תקפא\". טריק: סיבה/מידע – בוחרים רק לפי הכתוב, לא \"נכון בעולם\".<\/td><\/tr>\n<tr><td>2<\/td><td>א<\/td><td>שורה 3: רוב הציפורים מטילות באביב החמים – כאן הפוך מהמצופה. טריק: ב\"דווקא\" שואלים \"מה מפתיע?\".<\/td><\/tr>\n<tr><td>3<\/td><td>ב<\/td><td>המשפט שלפני: \"לשמור על הביצה\" – מניח את הביצה. טריק: כינוי גוף – להחליף את המילה ולקרוא שוב.<\/td><\/tr>\n<tr><td>4<\/td><td>ד<\/td><td>נצמדים יחד ומתחלפים במקומות כדי שכולם יתחממו. טריק: \"מה אפשר ללמוד משורות\" – לסכם את השורות במשפט אחד לפני האפשרויות.<\/td><\/tr>\n<tr><td>5<\/td><td>ג<\/td><td>ביצה אחת (ש' 5), חודשיים (ש' 9), לפי הקול (ש' 15) – מופיעים; משקל – לא. טריק: \"אין תשובה\" – לסמן ✓ ליד מה שמופיע.<\/td><\/tr>\n<tr><th colspan=\"3\">קטע 2 – יום ההולדת של שירן<\/th><\/tr>\n<tr><td>1<\/td><td>ב<\/td><td>בלי המידע הזה לא נבין למה שירן התאכזבה כשלא היו כתר ושיר. טריק: מטרת משפט – \"כדי להסביר\", לא \"לשכנע\".<\/td><\/tr>\n<tr><td>2<\/td><td>ד<\/td><td>שורה 9: \"המורה פשוט שכחה אותי\". טריק: רגש של דמות – לקרוא שורה לפני ושורה אחרי.<\/td><\/tr>\n<tr><td>3<\/td><td>א<\/td><td>הדלת סגורה, חושך, \"לאן נעלמו כולם?\" – אין קול. טריק: פירוש מילה – להציב כל אפשרות במשפט.<\/td><\/tr>\n<tr><td>4<\/td><td>ג<\/td><td>כשחזרו הכיתה כבר הייתה מקושטת והילדים חיכו בחושך. טריק: סיבה נסתרת – לחפש מה קרה מיד אחר כך.<\/td><\/tr>\n<tr><td>5<\/td><td>א<\/td><td>הכתר הוכן \"לפני כמה ימים\" (ש' 21), והילדים התלחשו והסתירו דף כבר בבוקר (ש' 5–6). טריק: \"מה באמת קרה\" – לחפש את הרמז המוקדם; מסיח ב = הטעות של הדמות.<\/td><\/tr>\n<tr><td>6<\/td><td>ד<\/td><td>גלעד חשב כמו שירן (ש' 10) והופתע (ש' 16). א – ש' 11, ב – ש' 19, ג – ש' 4. טריק: \"אי אפשר לומר\" – לסמן ✓ ליד מה שכתוב.<\/td><\/tr>\n<tr><td>7<\/td><td>ב<\/td><td>לחשה = דיברה בשקט, צעקה = בקול רם – הפכים. טריק: נרדפות – להציב במשפט; לשים לב ל\"אינן\".<\/td><\/tr>\n<tr><th colspan=\"3\">חשבון – משימה א'<\/th><\/tr>\n<tr><td>1<\/td><td>93<\/td><td><span class=\"ex\">67+20=87<\/span>, <span class=\"ex\">87+6=93<\/span>. טריק: להשלים לעשרת.<\/td><\/tr>\n<tr><td>2<\/td><td>27<\/td><td><span class=\"ex\">70−40=30<\/span>, <span class=\"ex\">30−3=27<\/span>. טריק: לבדוק חיסור בחיבור (<span class=\"ex\">27+43=70<\/span>).<\/td><\/tr>\n<tr><td>3<\/td><td>48<\/td><td>לוח הכפל: <span class=\"ex\">6×8=48<\/span>. טריק: ספרות בסדר הנכון (לא 84).<\/td><\/tr>\n<tr><td>4<\/td><td>7<\/td><td><span class=\"ex\">6×7=42<\/span>. טריק: חילוק כהפוך כפל.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ב'<\/th><\/tr>\n<tr><td>1<\/td><td>63<\/td><td><span class=\"ex\">35+28=63<\/span>. טריק: נעלם במקום הראשון בחיסור → מחברים; בדיקה בהצבה.<\/td><\/tr>\n<tr><td>2<\/td><td>46<\/td><td><span class=\"ex\">93−47=46<\/span>. טריק: בדיקה בהצבה (<span class=\"ex\">47+46=93<\/span>).<\/td><\/tr>\n<tr><td>3<\/td><td>8<\/td><td><span class=\"ex\">9×8=72<\/span>. טריק: חילוק כהפוך כפל.<\/td><\/tr>\n<tr><td>4<\/td><td>כל מספר מ-4 ומעלה<\/td><td>9 משני הצדדים – משווים רק את מה ששונה: צריך מספר גדול מ-3. למשל 4.<\/td><\/tr>\n<tr><td>5<\/td><td>כל מספר מ-0 עד 18<\/td><td>54 משני הצדדים – צריך מספר קטן מ-19. למשל 10. טריק: לבחור מספר פשוט ובטוח.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ג'<\/th><\/tr>\n<tr><td>1<\/td><td>ג (31)<\/td><td>אלמוג <span class=\"ex\">12−4=8<\/span>, האחות <span class=\"ex\">8+3=11<\/span>, <span class=\"ex\">12+8+11=31<\/span>. טריק: שרשרת השוואות – \"יותר ממי?\" (35 = יותר משקד).<\/td><\/tr>\n<tr><td>2<\/td><td>א (4)<\/td><td>עודף <span class=\"ex\">50−32=18<\/span>; <span class=\"ex\">10+5+2+1=18<\/span> – 4 מטבעות. טריק: מינימום מטבעות – מתחילים מהמטבע הגדול; 18 הוא העודף, לא מספר המטבעות.<\/td><\/tr>\n<tr><td>3<\/td><td>ד (<span class=\"ex\">45−26<\/span>)<\/td><td>21, 20, 20, 19. טריק: הקטן מבין ארבעה – לחשב כל תרגיל ולכתוב את התוצאה לידו.<\/td><\/tr>\n<tr><td>4<\/td><td>ב (8)<\/td><td><span class=\"ex\">34+18=52<\/span>, חצי = 26, <span class=\"ex\">34−26=8<\/span>. טריק: העברה – נותנים חצי מההפרש (לא 16); הסכום נשמר.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ד'<\/th><\/tr>\n<tr><td>1<\/td><td>א (6)<\/td><td><span class=\"ex\">✈&#xFE0E;=8<\/span>, <span class=\"ex\">★+★=20−8=12<\/span>, <span class=\"ex\">★=6<\/span>. טריק: סמל כפול + החלפה; 12 הוא שני כוכבים.<\/td><\/tr>\n<tr><td>2<\/td><td>ג (8)<\/td><td><span class=\"ex\">♠&#xFE0E;=15:3=5<\/span>, <span class=\"ex\">☂&#xFE0E;=13−5=8<\/span>. טריק: להתחיל מהשורה עם סמל אחד בלבד.<\/td><\/tr>\n<tr><td>3<\/td><td>ב (9)<\/td><td>\"חבילה\" <span class=\"ex\">▲+●=17<\/span>: <span class=\"ex\">●=25−17=8<\/span>, <span class=\"ex\">▲=17−8=9<\/span>. טריק: החלפת קבוצה שלמה; לענות על הסמל שנשאל (לא 8).<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ה'<\/th><\/tr>\n<tr><td>1<\/td><td>ד (3)<\/td><td><span class=\"ex\">43+43=86<\/span>. טריק: ספרת האחדות – <span class=\"ex\">∆+∆<\/span> מסתיים ב-6 → 3 או 8; <span class=\"ex\">48+48=96<\/span> לא מתאים.<\/td><\/tr>\n<tr><td>2<\/td><td>ג (4)<\/td><td><span class=\"ex\">47+47=94<\/span>. טריק: <span class=\"ex\">7+7=14<\/span> – זוכרים 1 לעשרות: <span class=\"ex\">∆+∆+1=9<\/span>; בדיקה בהצבה.<\/td><\/tr>\n<\/table><\/section>", "id": 4, "pdf": "pdf/test_4.pdf", "questions": 30}, {"title": "מבחן תרגול 5", "html": "<section class=\"cover\">\n  <h1>מִבְחַן תִּרְגּוּל – שָׁלָב א'<\/h1>\n  <div>כִּיתָה ב' · מִבְחָן מִסְפָּר 5<\/div>\n  <div class=\"fields\">שֵׁם: ____________________<br>תַּאֲרִיךְ: ________________<\/div>\n<\/section>\n\n<h2>חֵלֶק רִאשׁוֹן: קִטְעֵי קְרִיאָה וּשְׁאֵלוֹת<\/h2>\n<p class=\"instr\">קִרְאוּ אֶת הַקֶּטַע שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרָיו.<\/p>\n<div class=\"passage-title\">אֵיךְ שׁוֹמְרִים עַל שִׁינַּיִים בְּרִיאוֹת?<\/div>\n<ol class=\"lines\">\n  <li>בְּתוֹךְ הַפֶּה שֶׁלָּנוּ חַיִּים חַיְידַּקִּים זְעִירִים, שֶׁאִי אֶפְשָׁר לִרְאוֹת בָּעַיִן.<\/li>\n  <li>הַחַיְידַּקִּים הָאֵלֶּה אוֹהֲבִים מְאוֹד סוּכָּר. כְּשֶׁאֲנַחְנוּ אוֹכְלִים מַמְתָּקִים, הֵם אוֹכְלִים<\/li>\n  <li>אֶת הַסּוּכָּר שֶׁנִּשְׁאָר עַל הַשִּׁינַּיִים, וְיוֹצְרִים מִמֶּנּוּ חוּמְצָה.<\/li>\n  <li>הַחוּמְצָה פּוֹגַעַת בַּשֵּׁן לְאַט לְאַט, עַד שֶׁנּוֹצָר בָּהּ חוֹר. חוֹר כָּזֶה עָלוּל לִכְאוֹב.<\/li>\n  <li>אֵיךְ אֶפְשָׁר לִמְנוֹעַ אֶת זֶה? הִנֵּה שָׁלוֹשׁ הַמְלָצוֹת שֶׁל רוֹפְאֵי שִׁינַּיִים:<\/li>\n  <li><b>הַמְלָצָה 1:<\/b> צַחְצְחוּ שִׁינַּיִים פַּעֲמַיִים בְּיוֹם – בַּבּוֹקֶר, וּבָעֶרֶב לִפְנֵי הַשֵּׁינָה.<\/li>\n  <li>כָּל צִחְצוּחַ צָרִיךְ לְהִימָּשֵׁךְ שְׁתֵּי דַּקּוֹת לְפָחוֹת. צִחְצוּחַ חָטוּף שֶׁל כַּמָּה שְׁנִיּוֹת<\/li>\n  <li>אֵינוֹ מְנַקֶּה אֶת כָּל הַשִּׁינַּיִים, וְהַחַיְידַּקִּים נִשְׁאָרִים בַּפֶּה.<\/li>\n  <li>הַצִּחְצוּחַ בָּעֶרֶב חָשׁוּב בִּמְיוּחָד: בַּלַּיְלָה הַחַיְידַּקִּים פּוֹעֲלִים שָׁעוֹת רַבּוֹת.<\/li>\n  <li><b>הַמְלָצָה 2:<\/b> אִכְלוּ מְעַט מַמְתָּקִים, וְאַל תְּנַשְׁנְשׁוּ אוֹתָם בְּמֶשֶׁךְ כָּל הַיּוֹם.<\/li>\n  <li>אִם אֲכַלְתֶּם מַשֶּׁהוּ מָתוֹק וְאֵין לָכֶם מִבְרֶשֶׁת, שִׁטְפוּ אֶת הַפֶּה בְּמַיִם.<\/li>\n  <li>שִׂימוּ לֵב: אֲפִילּוּ בְּמִיץ פֵּירוֹת וּבְפֵירוֹת יְבֵשִׁים יֵשׁ הַרְבֵּה סוּכָּר!<\/li>\n  <li><b>הַמְלָצָה 3:<\/b> בַּקְּרוּ אֵצֶל רוֹפֵא שִׁינַּיִים פַּעֲמַיִים בְּשָׁנָה, גַּם כְּשֶׁשּׁוּם דָּבָר אֵינוֹ כּוֹאֵב.<\/li>\n  <li>הָרוֹפֵא יָכוֹל לְגַלּוֹת חוֹר קָטָן וּלְטַפֵּל בּוֹ לִפְנֵי שֶׁהוּא גָּדֵל וּמַתְחִיל לִכְאוֹב.<\/li>\n  <li>הַשִּׁינַּיִים הַקְּבוּעוֹת שֶׁצּוֹמְחוֹת לָכֶם עַכְשָׁיו צְרִיכוֹת לְהַחְזִיק מַעֲמָד כָּל הַחַיִּים.<\/li>\n  <li>שִׁמְרוּ עֲלֵיהֶן הֵיטֵב – וְתוּכְלוּ לְחַיֵּיךְ חִיּוּךְ בָּרִיא וְיָפֶה גַּם בְּעוֹד שָׁנִים רַבּוֹת.<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה בְּכָל שְׁאֵלָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. לְפִי הַקֶּטַע, מָה גּוֹרֵם לְחוֹר בַּשֵּׁן?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>הַמִּבְרֶשֶׁת, שֶׁמְּשַׁפְשֶׁפֶת אֶת הַשֵּׁן חָזָק מִדַּי<\/li><li><span class=\"l\">ב.<\/span>הַמַּיִם, שֶׁשּׁוֹטְפִים אֶת הַפֶּה אַחֲרֵי הָאוֹכֶל<\/li><li><span class=\"l\">ג.<\/span>הַחוּמְצָה, שֶׁהַחַיְידַּקִּים יוֹצְרִים מִן הַסּוּכָּר<\/li><li><span class=\"l\">ד.<\/span>הַסּוּכָּר, שֶׁהַחַיְידַּקִּים יוֹצְרִים מִן הַחוּמְצָה<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. מָה פֵּירוּשׁ הַמִּילָה \"חָטוּף\" (שׁוּרָה 7)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>קָצָר וּמָהִיר<\/li><li><span class=\"l\">ב.<\/span>חָזָק וְכוֹאֵב<\/li><li><span class=\"l\">ג.<\/span>אִיטִּי וִיסוֹדִי<\/li><li><span class=\"l\">ד.<\/span>מְאוּחָר בַּלַּיְלָה<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. בְּשׁוּרָה 12 כָּתוּב: \"אֲפִילּוּ בְּמִיץ פֵּירוֹת וּבְפֵירוֹת יְבֵשִׁים יֵשׁ הַרְבֵּה סוּכָּר\".<br>מַדּוּעַ כָּתוּב \"אֲפִילּוּ\"?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי מִיץ פֵּירוֹת טָעִים יוֹתֵר מִמַּמְתָּקִים<\/li><li><span class=\"l\">ב.<\/span>כִּי בְּדֶרֶךְ כְּלָל לֹא חוֹשְׁבִים שֶׁהֵם מַמְתָּקִים, וְלָכֵן זֶה מַפְתִּיעַ<\/li><li><span class=\"l\">ג.<\/span>כִּי רוֹפְאֵי הַשִּׁינַּיִים מַמְלִיצִים לִשְׁתּוֹת הַרְבֵּה מִיץ<\/li><li><span class=\"l\">ד.<\/span>כִּי הַחַיְידַּקִּים אֵינָם אוֹהֲבִים פֵּירוֹת<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. נִיר אָכַל עוּגַת שׁוֹקוֹלָד בְּטִיּוּל, וְאֵין לוֹ מִבְרֶשֶׁת שִׁינַּיִים.<br>לְפִי הַקֶּטַע, מָה כְּדַאי לְנִיר לַעֲשׂוֹת?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>לֶאֱכוֹל פֵּירוֹת יְבֵשִׁים<\/li><li><span class=\"l\">ב.<\/span>לְחַכּוֹת לַבִּיקּוּר אֵצֶל רוֹפֵא הַשִּׁינַּיִים<\/li><li><span class=\"l\">ג.<\/span>לִשְׁתּוֹת מִיץ פֵּירוֹת<\/li><li><span class=\"l\">ד.<\/span>לִשְׁטוֹף אֶת הַפֶּה בְּמַיִם<\/li><\/ol><\/div>\n\n<div data-accept=\"words:פעמיים|2 פעמים|שתי פעמים|פעמיים בשנה\" class=\"q\"><div class=\"stem\">5. הַשְׁלִימוּ אֶת הַמִּשְׁפָּט לְפִי הַקֶּטַע. כִּתְבוּ מִילָּה אַחַת עַל הַקַּו.<\/div>\n<div>כְּדַאי לְבַקֵּר אֵצֶל רוֹפֵא שִׁינַּיִים <span class=\"blank\"><\/span> בְּשָׁנָה.<\/div><\/div>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">קִרְאוּ אֶת הַסִּיפּוּר שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרָיו.<\/p>\n<div class=\"passage-title\">הַיּוֹם הָרִאשׁוֹן שֶׁל רוֹתֶם<\/div>\n<ol class=\"lines long\">\n  <li>בְּאֶמְצַע הַשָּׁנָה עָבְרָה רוֹתֶם עִם מִשְׁפַּחְתָּהּ לְעִיר אַחֶרֶת, וְהִגִּיעָה לְבֵית סֵפֶר חָדָשׁ.<\/li>\n  <li>בַּבּוֹקֶר הָרִאשׁוֹן הִיא עָמְדָה לְיַד הַשַּׁעַר, וְהַלֵּב שֶׁלָּהּ דָּפַק בְּחוֹזְקָה.<\/li>\n  <li>\"אֲנִי לֹא מַכִּירָה כָּאן אַף אֶחָד,\" לָחֲשָׁה לְאִימָּא. אִימָּא חִיבְּקָה אוֹתָהּ וְאָמְרָה:<\/li>\n  <li>\"גַּם הַיְּלָדִים עֲדַיִין לֹא מַכִּירִים אוֹתָךְ. תְּנִי לָהֶם קְצָת זְמַן.\"<\/li>\n  <li>הַמּוֹרָה אוֹרִית הוֹשִׁיבָה אֶת רוֹתֶם לְיַד יַלְדָּה שְׁקֵטָה בְּשֵׁם נֶטַע.<\/li>\n  <li>נֶטַע הִנְהֲנָה לְעֶבְרָהּ, אֲבָל לֹא אָמְרָה מִילָּה. רוֹתֶם הִרְגִּישָׁה בּוֹדֵדָה עוֹד יוֹתֵר.<\/li>\n  <li>בַּהַפְסָקָה יָצְאוּ כָּל הַיְּלָדִים לְשַׂחֵק בֶּחָצֵר, וְרוֹתֶם יָשְׁבָה לְבַדָּהּ עַל סַפְסָל.<\/li>\n  <li>כְּשֶׁהַפַּעֲמוֹן צִלְצֵל, הִיא מִיהֲרָה לַחֲזוֹר, פָּתְחָה דֶּלֶת וְהִתְיַישְּׁבָה בַּכִּיסֵּא הָרִאשׁוֹן.<\/li>\n  <li>פִּתְאוֹם שָׂמָה לֵב שֶׁכָּל הַיְּלָדִים סְבִיבָהּ גְּדוֹלִים מִמֶּנָּה, וְכוּלָּם מִסְתַּכְּלִים עָלֶיהָ.<\/li>\n  <li>\"נִרְאֶה לִי שֶׁהִתְבַּלְבַּלְתְּ,\" חִיֵּיךְ הַמּוֹרֶה. \"זֹאת כִּיתָּה ו'. כִּיתָּה ב' בַּדֶּלֶת הַבָּאָה.\"<\/li>\n  <li>הַיְּלָדִים פָּרְצוּ בִּצְחוֹק. הַפָּנִים שֶׁל רוֹתֶם הֶאֱדִימוּ, וְהִיא רָצְתָה לְהֵיעָלֵם.<\/li>\n  <li>הִיא חָזְרָה לַכִּיתָּה שֶׁלָּהּ בְּרֹאשׁ מוּרְכָּן, הוֹצִיאָה דַּף וְהִתְחִילָה לְצַיֵּיר.<\/li>\n  <li>הִיא צִיְּירָה יַלְדָּה קְטַנָּה שֶׁיּוֹשֶׁבֶת בֵּין עֲנָקִים, וְהָעֲנָקִים צוֹחֲקִים.<\/li>\n  <li>נֶטַע הֵצִיצָה בַּדַּף. \"זֹאת אַתְּ, בְּכִיתָּה ו'?\" שָׁאֲלָה בְּשֶׁקֶט. רוֹתֶם הִנְהֲנָה.<\/li>\n  <li>\"בַּשָּׁבוּעַ הָרִאשׁוֹן שֶׁלִּי כָּאן נִכְנַסְתִּי בְּטָעוּת לַחֲדַר הַמּוֹרִים,\" סִיפְּרָה נֶטַע.<\/li>\n  <li>רוֹתֶם הֵרִימָה אֶת הָרֹאשׁ. \"בֶּאֱמֶת? גַּם אַתְּ הָיִית חֲדָשָׁה?\"<\/li>\n  <li>\"בַּשָּׁנָה שֶׁעָבְרָה,\" עָנְתָה נֶטַע. הִיא לָקְחָה עִיפָּרוֹן וְהוֹסִיפָה עֲנָק עִם מִשְׁקָפַיִים.<\/li>\n  <li>\"זֶה הַמּוֹרֶה,\" אָמְרָה. שְׁתֵּיהֶן הִתְפַּקְּעוּ מִצְּחוֹק, עַד שֶׁהַמּוֹרָה אוֹרִית בִּיקְּשָׁה שֶׁקֶט.<\/li>\n  <li>עַד סוֹף הַיּוֹם הֵן צִיְּירוּ יַחַד דַּף שָׁלֵם שֶׁל עֲנָקִים מַצְחִיקִים.<\/li>\n  <li>כְּשֶׁאִימָּא בָּאָה לֶאֱסוֹף אוֹתָהּ, רוֹתֶם רָצָה אֵלֶיהָ עִם הַצִּיּוּר בַּיָּד.<\/li>\n  <li>\"אֵיךְ הָיָה?\" שָׁאֲלָה אִימָּא. \"בַּהַתְחָלָה הָיָה נוֹרָא,\" עָנְתָה רוֹתֶם,<\/li>\n  <li>\"אֲבָל מָחָר אֲנִי בָּאָה מוּקְדָּם. נֶטַע וַאֲנִי צְרִיכוֹת לְסַיֵּים אֶת הַצִּיּוּר.\"<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה בְּכָל שְׁאֵלָה.<\/p>\n\n<div class=\"tight\">\n<div class=\"q\"><div class=\"stem\">1. מַדּוּעַ צָחֲקוּ הַיְּלָדִים בְּכִיתָּה ו' (שׁוּרָה 11)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי רוֹתֶם צִיְּירָה צִיּוּר מַצְחִיק<\/li><li><span class=\"l\">ב.<\/span>כִּי רוֹתֶם נִכְנְסָה בְּטָעוּת לַכִּיתָּה שֶׁלָּהֶם<\/li><li><span class=\"l\">ג.<\/span>כִּי הַמּוֹרֶה סִיפֵּר לָהֶם בְּדִיחָה<\/li><li><span class=\"l\">ד.<\/span>כִּי רוֹתֶם נִכְנְסָה בְּטָעוּת לַחֲדַר הַמּוֹרִים<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. בְּשׁוּרָה 17 כָּתוּב: \"הִיא לָקְחָה עִיפָּרוֹן\". מִי זֹאת \"הִיא\"?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>רוֹתֶם<\/li><li><span class=\"l\">ב.<\/span>הַמּוֹרָה אוֹרִית<\/li><li><span class=\"l\">ג.<\/span>אִימָּא<\/li><li><span class=\"l\">ד.<\/span>נֶטַע<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. בְּשׁוּרָה 15 נֶטַע מְסַפֶּרֶת שֶׁנִּכְנְסָה בְּטָעוּת לַחֲדַר הַמּוֹרִים.<br>מַדּוּעַ נֶטַע מְסַפֶּרֶת אֶת זֶה לְרוֹתֶם?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כְּדֵי לְהַרְאוֹת לָהּ שֶׁטָּעוּיוֹת כָּאֵלֶּה קוֹרוֹת גַּם לַאֲחֵרִים<\/li><li><span class=\"l\">ב.<\/span>כְּדֵי לְהַסְבִּיר לָהּ אֵיפֹה נִמְצָא חֲדַר הַמּוֹרִים<\/li><li><span class=\"l\">ג.<\/span>כְּדֵי לִצְחוֹק עַל הַטָּעוּת שֶׁל רוֹתֶם<\/li><li><span class=\"l\">ד.<\/span>כְּדֵי לְהִתְפָּאֵר שֶׁהִיא מַכִּירָה אֶת כָּל הַמּוֹרִים<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. מָה קָרָה <u>לִפְנֵי<\/u> שֶׁרוֹתֶם נִכְנְסָה לְכִיתָּה ו'?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>נֶטַע סִיפְּרָה לָהּ עַל חֲדַר הַמּוֹרִים<\/li><li><span class=\"l\">ב.<\/span>הִיא צִיְּירָה יַלְדָּה בֵּין עֲנָקִים<\/li><li><span class=\"l\">ג.<\/span>הִיא יָשְׁבָה לְבַדָּהּ בַּהַפְסָקָה<\/li><li><span class=\"l\">ד.<\/span>הִיא צָחֲקָה יַחַד עִם נֶטַע<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">5. לְמָה הִתְכַּוְּונָה רוֹתֶם כְּשֶׁאָמְרָה: \"אֲבָל מָחָר אֲנִי בָּאָה מוּקְדָּם\" (שׁוּרָה 22)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>שֶׁהִיא פּוֹחֶדֶת לְהִתְבַּלְבֵּל שׁוּב בֵּין הַכִּיתּוֹת<\/li><li><span class=\"l\">ב.<\/span>שֶׁאִימָּא אֵיחֲרָה לְהָבִיא אוֹתָהּ בַּבּוֹקֶר<\/li><li><span class=\"l\">ג.<\/span>שֶׁהַמּוֹרָה בִּיקְּשָׁה מִמֶּנָּה לְהַגִּיעַ מוּקְדָּם<\/li><li><span class=\"l\">ד.<\/span>שֶׁהִיא כְּבָר רוֹצָה לַחֲזוֹר לְבֵית הַסֵּפֶר, כִּי מָצְאָה חֲבֵרָה<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">6. אֵיזֶה מִשְׁפָּט <u>אִי אֶפְשָׁר<\/u> לוֹמַר עַל פִּי הַסִּיפּוּר?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>נֶטַע הִגִּיעָה לְבֵית הַסֵּפֶר לִפְנֵי רוֹתֶם.<\/li><li><span class=\"l\">ב.<\/span>הַמּוֹרֶה שֶׁל כִּיתָּה ו' כָּעַס עַל רוֹתֶם.<\/li><li><span class=\"l\">ג.<\/span>רוֹתֶם הִתְבַּיְּישָׁה כְּשֶׁיַּלְדֵי כִּיתָּה ו' צָחֲקוּ.<\/li><li><span class=\"l\">ד.<\/span>בְּסוֹף הַיּוֹם רוֹתֶם הָיְתָה שְׂמֵחָה יוֹתֵר מֵאֲשֶׁר בַּבּוֹקֶר.<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">7. בְּאֵיזֶה צֶמֶד מִילִים הַמִּילִים <u>אֵינָן<\/u> מִילִים נִרְדָּפוֹת?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>מִיהֲרָה – הִזְדָּרְזָה<\/li><li><span class=\"l\">ב.<\/span>הֵצִיצָה – הִסְתַּכְּלָה<\/li><li><span class=\"l\">ג.<\/span>הִתְחִילָה – סִיְּימָה<\/li><li><span class=\"l\">ד.<\/span>טָעוּת – שְׁגִיאָה<\/li><\/ol><\/div>\n\n<p class=\"stop\">עִבְרוּ לָעַמּוּד הַבָּא רַק לְאַחַר שֶׁתְּקַבְּלוּ הוֹרָאָה לְכָךְ מֵהַמּוֹרָה.<\/p>\n\n<\/div>\n<div class=\"page-break\"><\/div>\n<h2>חֵלֶק שֵׁנִי: שְׁאֵלוֹת בְּחֶשְׁבּוֹן<\/h2>\n<div class=\"tight\">\n<h3>מְשִׂימָה א': תַּרְגִּילִים<\/h3>\n<p class=\"instr\">פִּתְרוּ אֶת הַתַּרְגִּילִים וְכִתְבוּ אֶת הַתּוֹצָאָה.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\">28 + 55 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\">64 − 19 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\">9 × 6 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">4. <span class=\"ex\">72 : 9 = <span class=\"blank\"><\/span><\/span><\/div>\n\n<h3>מְשִׂימָה ב': הַמִּסְפָּר הֶחָסֵר<\/h3>\n<p class=\"instr\">כִּתְבוּ אֶת הַמִּסְפָּר הֶחָסֵר בְּכָל תַּרְגִּיל.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\">66 − <span class=\"blank\"><\/span> = 27<\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\"><span class=\"blank\"><\/span> + 38 = 92<\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\">4 × <span class=\"blank\"><\/span> = 36<\/span><\/div>\n<div class=\"q mathq\">4. <span class=\"ex\">7 × 4 = 40 − <span class=\"blank\"><\/span><\/span><\/div>\n<p class=\"instr\">כִּתְבוּ עַל הַקַּו מִסְפָּר מַתְאִים.<br>שִׂימוּ לֵב: בְּכָל תַּרְגִּיל יֵשׁ יוֹתֵר מִתְּשׁוּבָה נְכוֹנָה אַחַת.<\/p>\n<div data-accept=\"mult:5,lt:40\" class=\"q mathq\">5. <span class=\"ex\">40 : 5 &gt; <span class=\"blank\"><\/span> : 5<\/span><\/div>\n<div data-accept=\"gt:25\" class=\"q mathq\">6. <span class=\"ex\">37 + 25 &lt; 37 + <span class=\"blank\"><\/span><\/span><\/div>\n<\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ג': בְּעָיוֹת מִילּוּלִיּוֹת<\/h3>\n<p class=\"instr\">קִרְאוּ כָּל בְּעָיָה וְהַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. גִּיל אָמַר: \"חָשַׁבְתִּי עַל מִסְפָּר. חִילַּקְתִּי אוֹתוֹ בְּ-2,<br>וְקִיבַּלְתִּי מִסְפָּר שֶׁגָּדוֹל בְּ-3 מִ-5.\"<br>עַל אֵיזֶה מִסְפָּר חָשַׁב גִּיל?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>8<\/li><li><span class=\"l\">ב.<\/span>16<\/li><li><span class=\"l\">ג.<\/span>10<\/li><li><span class=\"l\">ד.<\/span>4<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. בִּ-2 שַׂקִּיּוֹת יֵשׁ 14 סוּכָּרִיּוֹת. בְּכָל שַׂקִּית יֵשׁ אוֹתוֹ מִסְפַּר סוּכָּרִיּוֹת.<br>כַּמָּה סוּכָּרִיּוֹת יֵשׁ בְּ-5 שַׂקִּיּוֹת כָּאֵלֶּה?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>17<\/li><li><span class=\"l\">ב.<\/span>28<\/li><li><span class=\"l\">ג.<\/span>35<\/li><li><span class=\"l\">ד.<\/span>70<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. הִילָה וְגִיל נוֹסְעִים בָּרַכֶּבֶת. הָרַכֶּבֶת יוֹצֵאת בְּשָׁעָה <span class=\"ex\">8:50<\/span>,<br>וְהַנְּסִיעָה נִמְשֶׁכֶת 25 דַּקּוֹת.<br>בְּאֵיזוֹ שָׁעָה הֵם מַגִּיעִים?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span><span class=\"ex\">9:15<\/span><\/li><li><span class=\"l\">ב.<\/span><span class=\"ex\">9:25<\/span><\/li><li><span class=\"l\">ג.<\/span><span class=\"ex\">8:25<\/span><\/li><li><span class=\"l\">ד.<\/span><span class=\"ex\">10:15<\/span><\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. לְהִילָה יֵשׁ 36 בּוּלִים, וּלְגִיל יֵשׁ 9 בּוּלִים.<br>פִּי כַּמָּה יוֹתֵר בּוּלִים יֵשׁ לְהִילָה מֵאֲשֶׁר לְגִיל?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>פִּי 27<\/li><li><span class=\"l\">ב.<\/span>פִּי 45<\/li><li><span class=\"l\">ג.<\/span>פִּי 5<\/li><li><span class=\"l\">ד.<\/span>פִּי 4<\/li><\/ol><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ד': חִידוֹת בְּצִיּוּרִים<\/h3>\n<p class=\"instr\">בְּכָל חִידָה, כָּל צִיּוּר מַסְתִּיר מִסְפָּר. אוֹתוֹ צִיּוּר מַסְתִּיר תָּמִיד אוֹתוֹ מִסְפָּר.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">✿<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>☂︎ + ☂︎ + ☂︎ = 24<\/td><\/tr><tr><td>☂︎ + ✿ = 11<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>8<\/li><li><span class=\"l\">ב.<\/span>3<\/li><li><span class=\"l\">ג.<\/span>13<\/li><li><span class=\"l\">ד.<\/span>5<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">●<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>♥ + ♥ = 14<\/td><\/tr><tr><td>♥ + ● + ● + ● = 19<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>12<\/li><li><span class=\"l\">ב.<\/span>7<\/li><li><span class=\"l\">ג.<\/span>4<\/li><li><span class=\"l\">ד.<\/span>5<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">★<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>★ + ▲ = 12<\/td><\/tr><tr><td>★ + ▲ + ★ + ▲ + ★ = 31<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>7<\/li><li><span class=\"l\">ב.<\/span>19<\/li><li><span class=\"l\">ג.<\/span>5<\/li><li><span class=\"l\">ד.<\/span>6<\/li><\/ol><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ה': תַּרְגִּילֵי מְשׁוּלָּשִׁים<\/h3>\n<p class=\"instr\">בְּכָל תַּרְגִּיל הַמְּשׁוּלָּשׁ ∆ מַסְתִּיר סִפְרָה. בְּאוֹתוֹ תַּרְגִּיל כָּל הַמְּשׁוּלָּשִׁים מַסְתִּירִים אוֹתָהּ סִפְרָה.<br>אֵיזוֹ סִפְרָה מַסְתִּיר הַמְּשׁוּלָּשׁ? הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. <span class=\"ex\">1∆ + 1∆ + 1∆ = 39<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>9<\/li><li><span class=\"l\">ב.<\/span>1<\/li><li><span class=\"l\">ג.<\/span>2<\/li><li><span class=\"l\">ד.<\/span>3<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. <span class=\"ex\">2∆ + ∆2 = 77<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>5<\/li><li><span class=\"l\">ב.<\/span>3<\/li><li><span class=\"l\">ג.<\/span>7<\/li><li><span class=\"l\">ד.<\/span>4<\/li><\/ol><\/div>\n\n<p class=\"end\">סוֹף הַמִּבְחָן<\/p>\n\n<section class=\"answers\"><h2>פִּתְרוֹנוֹת – מבחן 5<\/h2>\n<table>\n<tr><th>שאלה<\/th><th>תשובה<\/th><th>הסבר + טריק<\/th><\/tr>\n<tr><th colspan=\"3\">קטע 1 – איך שומרים על שיניים בריאות? (טקסט המלצות)<\/th><\/tr>\n<tr><td>1<\/td><td>ג<\/td><td>שורות 3–4: החיידקים יוצרים מהסוכר חומצה, והחומצה יוצרת חור. ד' הופך את הסדר. טריק: מסיח שמחבר מילים מהקטע לא נכון.<\/td><\/tr>\n<tr><td>2<\/td><td>א<\/td><td>שורה 7: \"צחצוח חטוף של כמה שניות\" מול \"שתי דקות לפחות\" = קצר ומהיר. טריק: לקרוא את כל המשפט ולחפש ניגוד.<\/td><\/tr>\n<tr><td>3<\/td><td>ב<\/td><td>מיץ ופירות יבשים לא נראים כמו ממתקים – ובכל זאת יש בהם סוכר. טריק: ב\"אפילו\" שואלים \"מה היה מפתיע?\".<\/td><\/tr>\n<tr><td>4<\/td><td>ד<\/td><td>שורה 11: \"אם אכלתם משהו מתוק ואין לכם מברשת, שטפו את הפה במים\". א', ג' – יש בהם סוכר (שורה 12). טריק: שאלת יישום – למצוא את ההמלצה בטקסט ולפסול מה שהטקסט מזהיר ממנו.<\/td><\/tr>\n<tr><td>5<\/td><td>פעמיים<\/td><td>שורה 13. מתקבל גם: \"2 פעמים\", \"שתי פעמים\", \"פעמים\" עם הספרה 2. לא מתקבל: \"פעם\". טריק: השלמה – לחפש בקטע את המשפט עם אותן מילים.<\/td><\/tr>\n<tr><th colspan=\"3\">קטע 2 – היום הראשון של רותם<\/th><\/tr>\n<tr><td>1<\/td><td>ב<\/td><td>שורות 8–11: רותם התיישבה בכיתה ו' בטעות. ד' – זו הטעות של נטע (שורה 15). טריק: מסיח שנכון לדמות אחרת.<\/td><\/tr>\n<tr><td>2<\/td><td>ד<\/td><td>שורה 17: המשפט הקודם הוא \"ענתה נטע\" – \"היא\" ממשיכה את נטע. טריק: כינוי גוף – להחליף את \"היא\" בשם ולקרוא בקול.<\/td><\/tr>\n<tr><td>3<\/td><td>א<\/td><td>רותם מתביישת בטעות שלה; נטע מספרת על טעות דומה שלה כדי לעודד אותה. טריק: מטרת דיבור של דמות (לעודד/לנחם).<\/td><\/tr>\n<tr><td>4<\/td><td>ג<\/td><td>ההפסקה בשורה 7, הכניסה לכיתה ו' בשורה 8. א', ב', ד' קורים אחר כך (שורות 13–18). טריק: סדר אירועים – לסמן ליד כל אפשרות את מספר השורה.<\/td><\/tr>\n<tr><td>5<\/td><td>ד<\/td><td>שורה 22: \"נטע ואני צריכות לסיים את הציור\" – היא מחכה למחר. טריק: כוונת דובר; לזהות את השינוי מ\"נורא\" בהתחלה.<\/td><\/tr>\n<tr><td>6<\/td><td>ב<\/td><td>שורה 10: המורה חייך, לא כעס. א' (שורה 17), ג' (שורה 11), ד' (שורות 20–22) – אפשר לומר. טריק: לסמן ✓ ליד מה שנכון לפי הסיפור; לשים לב ל\"אי אפשר\".<\/td><\/tr>\n<tr><td>7<\/td><td>ג<\/td><td>התחילה ↔ סיימה – הפכים. טריק: להציב במשפט; לשים לב ל\"אינן\".<\/td><\/tr>\n<tr><th colspan=\"3\">חשבון – משימה א'<\/th><\/tr>\n<tr><td>1<\/td><td>83<\/td><td><span class=\"ex\">28+50=78<\/span>, <span class=\"ex\">78+5=83<\/span>. טריק: להשלים לעשרת.<\/td><\/tr>\n<tr><td>2<\/td><td>45<\/td><td><span class=\"ex\">64−20=44<\/span>, <span class=\"ex\">44+1=45<\/span>. בדיקה: <span class=\"ex\">45+19=64<\/span>. טריק: לבדוק חיסור בחיבור.<\/td><\/tr>\n<tr><td>3<\/td><td>54<\/td><td>לוח הכפל: <span class=\"ex\">9×6=54<\/span>. טריק: ספרות בסדר הנכון (לא 45).<\/td><\/tr>\n<tr><td>4<\/td><td>8<\/td><td><span class=\"ex\">9×8=72<\/span>. טריק: חילוק כהפוך כפל.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ב'<\/th><\/tr>\n<tr><td>1<\/td><td>39<\/td><td><span class=\"ex\">66−27=39<\/span>. טריק: כשהמחסר חסר – מחסרים את התוצאה (לא מחברים!). בדיקה: <span class=\"ex\">66−39=27<\/span>.<\/td><\/tr>\n<tr><td>2<\/td><td>54<\/td><td><span class=\"ex\">92−38=54<\/span>. טריק: נעלם במקום הראשון – פעולה הפוכה; בדיקה בהצבה (<span class=\"ex\">54+38=92<\/span>).<\/td><\/tr>\n<tr><td>3<\/td><td>9<\/td><td><span class=\"ex\">4×9=36<\/span>. טריק: חילוק כהפוך כפל.<\/td><\/tr>\n<tr><td>4<\/td><td>12<\/td><td>צד שמאל: <span class=\"ex\">7×4=28<\/span>; <span class=\"ex\">40−12=28<\/span>. טריק: מאזניים – לכסות ולפתור קודם את הצד המלא.<\/td><\/tr>\n<tr><td>5<\/td><td>כל מספר שמתחלק ב-5 וקטן מ-40 (למשל 20)<\/td><td>מחלקים באותו מספר (5) משני הצדדים – צריך מספר קטן מ-40. למשל 20 (<span class=\"ex\">8 &gt; 4<\/span>). טריק: משווים רק את מה ששונה.<\/td><\/tr>\n<tr><td>6<\/td><td>כל מספר גדול מ-25 (26 ומעלה)<\/td><td>37 משני הצדדים – משווים רק את מה ששונה. למשל 26 או 30.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ג'<\/th><\/tr>\n<tr><td>1<\/td><td>ב (16)<\/td><td>\"גדול ב-3 מ-5\" = 8; הופכים את החילוק: <span class=\"ex\">8×2=16<\/span>. בדיקה: <span class=\"ex\">16:2=8<\/span>. מסיח: 8 (תוצאת ביניים). טריק: חשבתי על מספר – להפוך את הפעולה ולבדוק בהצבה.<\/td><\/tr>\n<tr><td>2<\/td><td>ג (35)<\/td><td>בשקית אחת: <span class=\"ex\">14:2=7<\/span>; ב-5 שקיות: <span class=\"ex\">5×7=35<\/span>. מסיח: 17 (<span class=\"ex\">14+3<\/span>). טריק: יחס – למצוא קודם כמה ביחידה אחת.<\/td><\/tr>\n<tr><td>3<\/td><td>א (<span class=\"ex\">9:15<\/span>)<\/td><td>10 דקות עד <span class=\"ex\">9:00<\/span>, ועוד 15 דקות → <span class=\"ex\">9:15<\/span>. טריק: שעון – לקפוץ לשעה העגולה ואז להוסיף את השאר.<\/td><\/tr>\n<tr><td>4<\/td><td>ד (פי 4)<\/td><td><span class=\"ex\">36:9=4<\/span>. מסיח: 27 (<span class=\"ex\">36−9<\/span> = \"בכמה\"). טריק: פי כמה = חילוק, בכמה = חיסור.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ד'<\/th><\/tr>\n<tr><td>1<\/td><td>ב (3)<\/td><td><span class=\"ex\">☂︎=24:3=8<\/span>, <span class=\"ex\">✿=11−8=3<\/span>. טריק: להתחיל מהשורה עם סמל אחד בלבד.<\/td><\/tr>\n<tr><td>2<\/td><td>ג (4)<\/td><td><span class=\"ex\">♥=7<\/span>, <span class=\"ex\">●+●+●=19−7=12<\/span>, <span class=\"ex\">●=4<\/span>. טריק: סמל כפול + החלפה; בדיקה בהצבה.<\/td><\/tr>\n<tr><td>3<\/td><td>א (7)<\/td><td><span class=\"ex\">★+▲=12<\/span> היא \"חבילה\" שמופיעה פעמיים: <span class=\"ex\">31−12−12=7<\/span>. טריק: החלפת קבוצה שלמה.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ה'<\/th><\/tr>\n<tr><td>1<\/td><td>ד (3)<\/td><td><span class=\"ex\">13+13+13=39<\/span>. טריק: ספרת האחדות – <span class=\"ex\">∆+∆+∆<\/span> מסתיים ב-9 → 3.<\/td><\/tr>\n<tr><td>2<\/td><td>א (5)<\/td><td><span class=\"ex\">25+52=77<\/span>. טריק: לבדוק כל אחת מארבע האפשרויות בהצבה; ∆ הוא ספרה – פעם באחדות ופעם בעשרות.<\/td><\/tr>\n<\/table><\/section>", "id": 5, "pdf": "pdf/test_5.pdf", "questions": 31}, {"title": "מבחן תרגול 6", "html": "<section class=\"cover\">\n  <h1>מִבְחַן תִּרְגּוּל – שָׁלָב א'<\/h1>\n  <div>כִּיתָּה ב' · מִבְחָן מִסְפָּר 6<\/div>\n  <div class=\"fields\">שֵׁם: ____________________<br>תַּאֲרִיךְ: ________________<\/div>\n<\/section>\n\n<h2>חֵלֶק רִאשׁוֹן: קִטְעֵי קְרִיאָה וּשְׁאֵלוֹת<\/h2>\n<p class=\"instr\">קִרְאוּ אֶת קֶטַע הַמֵּידָע שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרָיו.<\/p>\n<div class=\"passage-title\">הַדְּבוֹרִים<\/div>\n<ol class=\"lines\">\n  <li>בְּכָל כַּוֶּרֶת חַיּוֹת יַחַד אַלְפֵי דְּבוֹרִים, וּלְכָל דְּבוֹרָה יֵשׁ תַּפְקִיד.<\/li>\n  <li>הַמַּלְכָּה הִיא הַדְּבוֹרָה הַגְּדוֹלָה בְּיוֹתֵר, וְרַק הִיא מְטִילָה בֵּיצִים.<\/li>\n  <li>דְּבוֹרִים צְעִירוֹת מְנַקּוֹת אֶת הַכַּוֶּרֶת וּמַאֲכִילוֹת אֶת הַזְּחָלִים הַקְּטַנִּים.<\/li>\n  <li>דְּבוֹרִים אֲחֵרוֹת עוֹמְדוֹת בַּפֶּתַח וְשׁוֹמְרוֹת שֶׁאוֹיֵב לֹא יִיכָּנֵס פְּנִימָה.<\/li>\n  <li>הַדְּבוֹרִים הַמְּבוּגָּרוֹת יוֹצְאוֹת הַחוּצָה וְאוֹסְפוֹת צוּף מָתוֹק מִן הַפְּרָחִים.<\/li>\n  <li>מִן הַצּוּף הַזֶּה הַדְּבוֹרִים מְכִינוֹת בַּכַּוֶּרֶת אֶת הַדְּבַשׁ.<\/li>\n  <li>כְּשֶׁדְּבוֹרָה מוֹצֵאת שָׂדֶה מָלֵא פְּרָחִים, הִיא מְמַהֶרֶת לַחֲזוֹר אֶל הַכַּוֶּרֶת.<\/li>\n  <li>אֵיךְ הִיא מְסַפֶּרֶת לַחֲבֵרוֹתֶיהָ הֵיכָן הַשָּׂדֶה? הֲרֵי דְּבוֹרִים אֵינָן מְדַבְּרוֹת!<\/li>\n  <li>הַדְּבוֹרָה רוֹקֶדֶת לִפְנֵיהֶן רִיקּוּד מְיוּחָד, וְהֵן עוֹקְבוֹת אַחֲרֶיהָ.<\/li>\n  <li>אִם הַפְּרָחִים קְרוֹבִים, הִיא רוֹקֶדֶת בְּמַעְגָּל קָטָן.<\/li>\n  <li>אִם הַפְּרָחִים רְחוֹקִים, הִיא מְנַעְנַעַת אֶת גּוּפָהּ מִצַּד לְצַד.<\/li>\n  <li>כְּכָל שֶׁהַפְּרָחִים רְחוֹקִים יוֹתֵר, הָרִיקּוּד נִמְשָׁךְ זְמַן רַב יוֹתֵר.<\/li>\n  <li>הָרִיקּוּד מַרְאֶה אֲפִילּוּ לְאֵיזֶה כִּיוּוּן צָרִיךְ לָעוּף כְּדֵי לְהַגִּיעַ אֲלֵיהֶם.<\/li>\n  <li>אֲנָשִׁים רַבִּים פּוֹחֲדִים מִדְּבוֹרִים, אֲבָל דְּבוֹרָה עוֹקֶצֶת רַק כְּשֶׁהִיא בְּסַכָּנָה.<\/li>\n  <li>לְמַעֲשֶׂה, דְּבוֹרַת הַדְּבַשׁ יְכוֹלָה לַעֲקוֹץ אָדָם רַק פַּעַם אַחַת.<\/li>\n  <li>הָעוֹקֶץ שֶׁלָּהּ נִתְקָע בָּעוֹר, וּזְמַן קָצָר אַחֲרֵי הָעֲקִיצָה הִיא מֵתָה.<\/li>\n  <li>לָכֵן, אִם לֹא תַּפְרִיעוּ לַדְּבוֹרָה, גַּם הִיא לֹא תַּפְרִיעַ לָכֶם.<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה בְּכָל שְׁאֵלָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. מַדּוּעַ דְּבוֹרָה שֶׁמָּצְאָה שָׂדֶה מָלֵא פְּרָחִים רוֹקֶדֶת לִפְנֵי חֲבֵרוֹתֶיהָ?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כְּדֵי לְשַׂמֵּחַ אֶת הַמַּלְכָּה<\/li><li><span class=\"l\">ב.<\/span>כִּי הִיא רוֹצָה לְהַפְחִיד אוֹיֵב שֶׁנִּכְנַס לַכַּוֶּרֶת<\/li><li><span class=\"l\">ג.<\/span>כְּדֵי לְסַפֵּר לָהֶן הֵיכָן נִמְצָאִים הַפְּרָחִים<\/li><li><span class=\"l\">ד.<\/span>כִּי כָּךְ הִיא מְכִינָה דְּבַשׁ מִן הַצּוּף<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. בְּשׁוּרָה 9 כָּתוּב: \"הַדְּבוֹרָה רוֹקֶדֶת לִפְנֵיהֶן רִיקּוּד מְיוּחָד, וְהֵן עוֹקְבוֹת אַחֲרֶיהָ\".<br>לְמִי אוֹ לְמָה מִתְיַיחֶסֶת הַמִּילָה \"הֵן\"?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>לַדְּבוֹרִים שֶׁרוֹאוֹת אֶת הָרִיקּוּד<\/li><li><span class=\"l\">ב.<\/span>לַבֵּיצִים שֶׁהַמַּלְכָּה מְטִילָה<\/li><li><span class=\"l\">ג.<\/span>לַדְּבוֹרִים שֶׁנִּשְׁאֲרוּ בִּשְׂדֵה הַפְּרָחִים<\/li><li><span class=\"l\">ד.<\/span>לָרַגְלַיִים שֶׁל הַדְּבוֹרָה הָרוֹקֶדֶת<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. מָה אֶפְשָׁר לִלְמוֹד מִשּׁוּרוֹת 2–5?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>שֶׁכָּל הַדְּבוֹרִים בַּכַּוֶּרֶת מְטִילוֹת בֵּיצִים<\/li><li><span class=\"l\">ב.<\/span>שֶׁלִּדְבוֹרִים שׁוֹנוֹת בַּכַּוֶּרֶת יֵשׁ תַּפְקִידִים שׁוֹנִים<\/li><li><span class=\"l\">ג.<\/span>שֶׁהַדְּבוֹרִים הַצְּעִירוֹת אוֹסְפוֹת צוּף מִן הַפְּרָחִים<\/li><li><span class=\"l\">ד.<\/span>שֶׁהַמַּלְכָּה שׁוֹמֶרֶת עַל הַפֶּתַח שֶׁל הַכַּוֶּרֶת<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. עַל אֵיזוֹ שְׁאֵלָה <u>אֵין<\/u> תְּשׁוּבָה בַּקֶּטַע?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>מִמָּה הַדְּבוֹרִים מְכִינוֹת אֶת הַדְּבַשׁ?<\/li><li><span class=\"l\">ב.<\/span>כַּמָּה פְּעָמִים יְכוֹלָה דְּבוֹרַת הַדְּבַשׁ לַעֲקוֹץ?<\/li><li><span class=\"l\">ג.<\/span>כַּמָּה זְמַן חַיָּה מַלְכַּת הַדְּבוֹרִים?<\/li><li><span class=\"l\">ד.<\/span>מָה עוֹשׂוֹת הַדְּבוֹרִים הַצְּעִירוֹת בַּכַּוֶּרֶת?<\/li><\/ol><\/div>\n\n<div class=\"q\" data-accept=\"words:ריקוד|רקוד|הריקוד|ריקודים|מחול\"><div class=\"stem\">5. הַשְׁלִימוּ אֶת הַמִּשְׁפָּט לְפִי הַקֶּטַע. כִּתְבוּ מִילָּה אַחַת עַל הַקַּו.<\/div>\n<div>הַדְּבוֹרָה מַרְאָה לַחֲבֵרוֹתֶיהָ הֵיכָן הַפְּרָחִים בְּעֶזְרַת <span class=\"blank\"><\/span> מְיוּחָד.<\/div><\/div>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">קִרְאוּ אֶת הַסִּיפּוּר שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרָיו.<\/p>\n<div class=\"passage-title\">יוֹם שִׁישִּׁי בַּשּׁוּק<\/div>\n<ol class=\"lines long\">\n  <li>בְּיוֹם שִׁישִּׁי בַּבּוֹקֶר הָלְכוּ יַעֲלִי, אִימָּא וַעֲמִית הַקָּטָן אֶל הַשּׁוּק.<\/li>\n  <li>הַשּׁוּק הָיָה הוֹמֶה: מוֹכְרִים צָעֲקוּ, אֲנָשִׁים נִדְחֲקוּ, וּמוּזִיקָה נִשְׁמְעָה מִכָּל צַד.<\/li>\n  <li>\"יַעֲלִי, הַחֲזִיקִי לַעֲמִית אֶת הַיָּד,\" בִּיקְּשָׁה אִימָּא, וְנֶעֶמְדָה בַּתּוֹר לַגְּבִינוֹת.<\/li>\n  <li>יַעֲלִי, יַלְדָּה בַּת תֵּשַׁע, אָחֲזָה הֵיטֵב בַּיָּד שֶׁל אָחִיהָ בֶּן הֶחָמֵשׁ.<\/li>\n  <li>פִּתְאוֹם רָאֲתָה דּוּכָן שֶׁל צְמִידִים צִבְעוֹנִיִּים, וְהֵרִימָה צָמִיד אֶחָד כְּדֵי לִמְדּוֹד אוֹתוֹ.<\/li>\n  <li>רַק לְרֶגַע אֶחָד הִיא שִׁחְרְרָה אֶת הַיָּד שֶׁל עֲמִית.<\/li>\n  <li>כְּשֶׁהִסְתּוֹבְבָה, עֲמִית כְּבָר לֹא הָיָה לְיָדָהּ. הַלֵּב שֶׁלָּהּ דָּפַק בְּחוֹזְקָה.<\/li>\n  <li>\"אִימָּא! עֲמִית נֶעֱלַם!\" קָרְאָה יַעֲלִי. אִימָּא הֶחֱוִירָה וְעָזְבָה מִיָּד אֶת הַתּוֹר.<\/li>\n  <li>\"צָרִיךְ לָרוּץ וּלְחַפֵּשׂ אוֹתוֹ בְּכָל הַשּׁוּק!\" אָמְרָה אִימָּא בְּבֶהָלָה.<\/li>\n  <li>גַּם יַעֲלִי רָצְתָה לָרוּץ, אֲבָל אָז נִזְכְּרָה בַּכְּלָל שֶׁאִימָּא לִימְּדָה אוֹתָם.<\/li>\n  <li>\"אִימָּא, חַכִּי,\" אָמְרָה. \"אַתְּ בְּעַצְמֵךְ לִימַּדְתְּ אוֹתָנוּ מָה עוֹשִׂים כְּשֶׁהוֹלְכִים לְאִיבּוּד:<\/li>\n  <li>עוֹמְדִים בַּמָּקוֹם, לֹא זָזִים, וּמְבַקְּשִׁים עֶזְרָה מִמּוֹכֵר. עֲמִית בֶּטַח זוֹכֵר!\"<\/li>\n  <li>אִימָּא נָשְׁמָה נְשִׁימָה עֲמוּקָּה. \"אַתְּ צוֹדֶקֶת,\" אָמְרָה. \"נְבַקֵּשׁ עֶזְרָה גַּם אֲנַחְנוּ.\"<\/li>\n  <li>הֵן נִיגְּשׁוּ אֶל מוֹכֵר הַיְּרָקוֹת, וְסִיפְּרוּ לוֹ שֶׁיֶּלֶד קָטָן בְּחוּלְצָה צְהוּבָּה נֶעֱלַם.<\/li>\n  <li>\"אַל תִּדְאֲגוּ,\" אָמַר הַמּוֹכֵר. \"כָּל הַמּוֹכְרִים כָּאן מַכִּירִים זֶה אֶת זֶה.\"<\/li>\n  <li>הוּא הוֹצִיא טֶלֶפוֹן וְהִתְקַשֵּׁר אֶל חֲבֵרָיו בַּדּוּכָנִים הָאֲחֵרִים.<\/li>\n  <li>אַחֲרֵי דַּקָּה אֲרוּכָּה הוּא חִיֵּיךְ: \"מָצְאוּ אוֹתוֹ! הוּא עוֹמֵד לְיַד דּוּכַן הַמִּיצִים.\"<\/li>\n  <li>אִימָּא וְיַעֲלִי מִיהֲרוּ לְשָׁם. עֲמִית עָמַד בְּשֶׁקֶט לְיַד מוֹכֶרֶת הַמִּיצִים, וְלֹא זָז.<\/li>\n  <li>\"רָאִיתִי בָּלוֹן אָדוֹם וְהָלַכְתִּי אַחֲרָיו,\" סִיפֵּר, \"וּפִתְאוֹם לֹא רָאִיתִי אֶתְכֶן.<\/li>\n  <li>אָז עָמַדְתִּי בַּמָּקוֹם וְאָמַרְתִּי לַמּוֹכֶרֶת שֶׁהָלַכְתִּי לְאִיבּוּד. אֲפִילּוּ לֹא בָּכִיתִי!\"<\/li>\n  <li>אִימָּא חִיבְּקָה אוֹתוֹ חָזָק. יַעֲלִי הִשְׁפִּילָה אֶת עֵינֶיהָ: \"סְלִיחָה שֶׁעָזַבְתִּי אֶת הַיָּד.\"<\/li>\n  <li>\"כּוּלָּנוּ טוֹעִים לִפְעָמִים,\" אָמְרָה אִימָּא. \"אֲבָל הַיּוֹם שְׁנֵיכֶם זְכַרְתֶּם מָה שֶׁחָשׁוּב.\"<\/li>\n  <li>מֵאָז אוֹתוֹ יוֹם, יַעֲלִי מַחֲזִיקָה לַעֲמִית אֶת הַיָּד גַּם כְּשֶׁיֵּשׁ צְמִידִים יָפִים.<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה בְּכָל שְׁאֵלָה.<\/p>\n\n<div class=\"tight\">\n<div class=\"q\"><div class=\"stem\">1. מָה פֵּירוּשׁ הַמִּילָה \"הוֹמֶה\" (שׁוּרָה 2)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>שָׁקֵט וְרֵיק<\/li><li><span class=\"l\">ב.<\/span>קָטָן וְצַר<\/li><li><span class=\"l\">ג.<\/span>נָקִי וּמְסוּדָּר<\/li><li><span class=\"l\">ד.<\/span>מָלֵא רַעַשׁ וּתְנוּעָה<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. בְּשׁוּרָה 6 כָּתוּב: \"רַק לְרֶגַע אֶחָד הִיא שִׁחְרְרָה אֶת הַיָּד שֶׁל עֲמִית\".<br>הַמַּטָּרָה שֶׁל הַמִּשְׁפָּט הַזֶּה הִיא –<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>לְהַסְבִּיר שֶׁיַּעֲלִי אֵינָהּ אוֹהֶבֶת לְהַחֲזִיק יָד<\/li><li><span class=\"l\">ב.<\/span>לְהַדְגִּישׁ שֶׁעֲמִית נֶעֱלַם בְּתוֹךְ זְמַן קָצָר מְאוֹד<\/li><li><span class=\"l\">ג.<\/span>לְסַפֵּר שֶׁאִימָּא הִרְשְׁתָה לְיַעֲלִי לַעֲזוֹב אֶת הַיָּד<\/li><li><span class=\"l\">ד.<\/span>לְהַרְאוֹת שֶׁעֲמִית מָשַׁךְ אֶת הַיָּד שֶׁלּוֹ בְּכוֹחַ<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. בְּשׁוּרָה 10 כָּתוּב: \"גַּם יַעֲלִי רָצְתָה לָרוּץ\".<br>הַמִּילָה \"גַּם\" מִתְיַיחֶסֶת לְיַעֲלִי וְגַם –<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>לְאִימָּא<\/li><li><span class=\"l\">ב.<\/span>לַעֲמִית<\/li><li><span class=\"l\">ג.<\/span>לְמוֹכֵר הַיְּרָקוֹת<\/li><li><span class=\"l\">ד.<\/span>לְמוֹכֶרֶת הַמִּיצִים<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. מַדּוּעַ יַעֲלִי בִּיקְּשָׁה מֵאִימָּא לְחַכּוֹת וְלֹא לָרוּץ (שׁוּרוֹת 11–12)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי הִיא הָיְתָה עֲיֵיפָה מִדַּי<\/li><li><span class=\"l\">ב.<\/span>כִּי רָצְתָה לִקְנוֹת קוֹדֶם אֶת הַצָּמִיד<\/li><li><span class=\"l\">ג.<\/span>כִּי חָשְׁבָה שֶׁעֲמִית עוֹמֵד בַּמָּקוֹם, כְּמוֹ שֶׁלִּימְּדוּ אוֹתוֹ<\/li><li><span class=\"l\">ד.<\/span>כִּי יָדְעָה שֶׁעֲמִית נִמְצָא לְיַד דּוּכַן הַמִּיצִים<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">5. מַדּוּעַ יַעֲלִי הִשְׁפִּילָה אֶת עֵינֶיהָ (שׁוּרָה 21)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי כָּעֲסָה עַל עֲמִית שֶׁהָלַךְ אַחֲרֵי הַבָּלוֹן<\/li><li><span class=\"l\">ב.<\/span>כִּי חִיפְּשָׂה צָמִיד שֶׁנָּפַל לָהּ<\/li><li><span class=\"l\">ג.<\/span>כִּי פָּחֲדָה מִמּוֹכֶרֶת הַמִּיצִים<\/li><li><span class=\"l\">ד.<\/span>כִּי הִצְטַעֲרָה שֶׁעָזְבָה אֶת הַיָּד שֶׁל עֲמִית<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">6. בְּאֵיזֶה צֶמֶד מִילִים הַמִּילִים <u>אֵינָן<\/u> מִילִים נִרְדָּפוֹת?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>לָחֲשָׁה – צָעֲקָה<\/li><li><span class=\"l\">ב.<\/span>אָחֲזָה – הֶחֱזִיקָה<\/li><li><span class=\"l\">ג.<\/span>מִיהֲרוּ – הִזְדָּרְזוּ<\/li><li><span class=\"l\">ד.<\/span>בֶּהָלָה – פַּחַד<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">7. אֵיזֶה שֵׁם אַחֵר מַתְאִים בְּיוֹתֵר לַסִּיפּוּר?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>הַבָּלוֹן שֶׁהִתְפּוֹצֵץ<\/li><li><span class=\"l\">ב.<\/span>הַכְּלָל שֶׁל אִימָּא<\/li><li><span class=\"l\">ג.<\/span>יַעֲלִי הוֹלֶכֶת לְאִיבּוּד<\/li><li><span class=\"l\">ד.<\/span>הַצָּמִיד הֶחָדָשׁ שֶׁל יַעֲלִי<\/li><\/ol><\/div>\n\n<p class=\"stop\">עִבְרוּ לָעַמּוּד הַבָּא רַק לְאַחַר שֶׁתְּקַבְּלוּ הוֹרָאָה לְכָךְ מֵהַמּוֹרָה.<\/p>\n<\/div>\n\n<div class=\"page-break\"><\/div>\n<h2>חֵלֶק שֵׁנִי: שְׁאֵלוֹת בְּחֶשְׁבּוֹן<\/h2>\n<div class=\"tight\">\n<h3>מְשִׂימָה א': תַּרְגִּילִים<\/h3>\n<p class=\"instr\">פִּתְרוּ אֶת הַתַּרְגִּילִים וְכִתְבוּ אֶת הַתּוֹצָאָה.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\">57 + 36 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\">81 − 45 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\">8 × 6 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">4. <span class=\"ex\">63 : 7 = <span class=\"blank\"><\/span><\/span><\/div>\n\n<h3>מְשִׂימָה ב': הַמִּסְפָּר הֶחָסֵר<\/h3>\n<p class=\"instr\">כִּתְבוּ אֶת הַמִּסְפָּר הֶחָסֵר בְּכָל תַּרְגִּיל.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\">44 + <span class=\"blank\"><\/span> = 91<\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\"><span class=\"blank\"><\/span> − 29 = 34<\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\">6 × <span class=\"blank\"><\/span> = 54<\/span><\/div>\n<div class=\"q mathq\">4. <span class=\"ex\">5 × 6 = 50 − <span class=\"blank\"><\/span><\/span><\/div>\n\n<p class=\"instr\">כִּתְבוּ עַל הַקַּו מִסְפָּר מַתְאִים.<br>שִׂימוּ לֵב: בְּכָל תַּרְגִּיל יֵשׁ יוֹתֵר מִתְּשׁוּבָה נְכוֹנָה אַחַת.<\/p>\n<div class=\"q mathq\" data-accept=\"gt:4\">5. <span class=\"ex\">7 × 4 &lt; 7 × <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\" data-accept=\"lt:30\">6. <span class=\"ex\">56 − <span class=\"blank\"><\/span> &gt; 56 − 30<\/span><\/div>\n\n<\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ג': בְּעָיוֹת מִילּוּלִיּוֹת<\/h3>\n<p class=\"instr\">קִרְאוּ כָּל בְּעָיָה וְהַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. בַּחֶדֶר שֶׁל יַרְדֵּן יֵשׁ 3 מַדָּפִים. בַּמַּדָּף הָרִאשׁוֹן יֵשׁ 9 סְפָרִים. בַּמַּדָּף הַשֵּׁנִי יֵשׁ 4 סְפָרִים פָּחוֹת מֵאֲשֶׁר בָּרִאשׁוֹן. בַּמַּדָּף הַשְּׁלִישִׁי יֵשׁ 6 סְפָרִים יוֹתֵר מֵאֲשֶׁר בַּשֵּׁנִי.<br>כַּמָּה סְפָרִים יֵשׁ בִּשְׁלוֹשֶׁת הַמַּדָּפִים בְּסַךְ הַכּוֹל?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>29<\/li><li><span class=\"l\">ב.<\/span>20<\/li><li><span class=\"l\">ג.<\/span>15<\/li><li><span class=\"l\">ד.<\/span>25<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. שִׁיעוּר הַשְּׂחִיָּיה שֶׁל טַל מַתְחִיל בְּשָׁעָה <span class=\"ex\">7:35<\/span> וְנִמְשָׁךְ 40 דַּקּוֹת.<br>בְּאֵיזוֹ שָׁעָה מִסְתַּיֵּים הַשִּׁיעוּר?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span><span class=\"ex\">8:05<\/span><\/li><li><span class=\"l\">ב.<\/span><span class=\"ex\">7:55<\/span><\/li><li><span class=\"l\">ג.<\/span><span class=\"ex\">8:15<\/span><\/li><li><span class=\"l\">ד.<\/span><span class=\"ex\">8:35<\/span><\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. יַרְדֵּן וְטַל אָסְפוּ צְדָפִים בַּחוֹף. לְיַרְדֵּן יֵשׁ 40 צְדָפִים, וּלְטַל יֵשׁ 8 צְדָפִים.<br>בְּכַמָּה צְדָפִים יֵשׁ לְיַרְדֵּן יוֹתֵר מֵאֲשֶׁר לְטַל?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>32<\/li><li><span class=\"l\">ב.<\/span>5<\/li><li><span class=\"l\">ג.<\/span>48<\/li><li><span class=\"l\">ד.<\/span>30<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. טַל קָנָה מַחְבֶּרֶת בְּ-11 שְׁקָלִים, וְשִׁילֵּם בִּשְׁטָר שֶׁל 20 שְׁקָלִים.<br>בְּאֵילוּ מַטְבְּעוֹת קִיבֵּל טַל אֶת הָעוֹדֶף?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>מַטְבֵּעַ שֶׁל 5 שְׁקָלִים, מַטְבֵּעַ שֶׁל 2 שְׁקָלִים וּמַטְבֵּעַ שֶׁל שֶׁקֶל אֶחָד<\/li><li><span class=\"l\">ב.<\/span>מַטְבֵּעַ שֶׁל 5 שְׁקָלִים וּשְׁנֵי מַטְבְּעוֹת שֶׁל 2 שְׁקָלִים<\/li><li><span class=\"l\">ג.<\/span>שְׁנֵי מַטְבְּעוֹת שֶׁל 5 שְׁקָלִים<\/li><li><span class=\"l\">ד.<\/span>אַרְבָּעָה מַטְבְּעוֹת שֶׁל 2 שְׁקָלִים<\/li><\/ol><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ד': חִידוֹת בְּצִיּוּרִים<\/h3>\n<p class=\"instr\">בְּכָל חִידָה, כָּל צִיּוּר מַסְתִּיר מִסְפָּר. אוֹתוֹ צִיּוּר מַסְתִּיר תָּמִיד אוֹתוֹ מִסְפָּר.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">♣<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>★ + ★ + ★ + ★ = 28<\/td><\/tr><tr><td>★ + ♣ = 10<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>7<\/li><li><span class=\"l\">ב.<\/span>3<\/li><li><span class=\"l\">ג.<\/span>4<\/li><li><span class=\"l\">ד.<\/span>18<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">▲<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>● + ● = 18<\/td><\/tr><tr><td>● + ▲ + ▲ = 25<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>9<\/li><li><span class=\"l\">ב.<\/span>16<\/li><li><span class=\"l\">ג.<\/span>7<\/li><li><span class=\"l\">ד.<\/span>8<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">☀&#xFE0E;<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>✿ + ☀&#xFE0E; = 13<\/td><\/tr><tr><td>✿ + ☀&#xFE0E; + ✿ = 20<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>6<\/li><li><span class=\"l\">ב.<\/span>7<\/li><li><span class=\"l\">ג.<\/span>13<\/li><li><span class=\"l\">ד.<\/span>5<\/li><\/ol><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ה': תַּרְגִּילֵי מְשׁוּלָּשִׁים<\/h3>\n<p class=\"instr\">בְּכָל תַּרְגִּיל הַמְּשׁוּלָּשׁ ∆ מַסְתִּיר סִפְרָה. בְּאוֹתוֹ תַּרְגִּיל כָּל הַמְּשׁוּלָּשִׁים מַסְתִּירִים אוֹתָהּ סִפְרָה.<br>אֵיזוֹ סִפְרָה מַסְתִּיר הַמְּשׁוּלָּשׁ? הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. <span class=\"ex\">2∆ + 3∆ = 58<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>9<\/li><li><span class=\"l\">ב.<\/span>8<\/li><li><span class=\"l\">ג.<\/span>4<\/li><li><span class=\"l\">ד.<\/span>3<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. <span class=\"ex\">∆3 + ∆3 = 66<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>6<\/li><li><span class=\"l\">ב.<\/span>2<\/li><li><span class=\"l\">ג.<\/span>4<\/li><li><span class=\"l\">ד.<\/span>3<\/li><\/ol><\/div>\n\n<p class=\"end\">סוֹף הַמִּבְחָן<\/p>\n\n<section class=\"answers\"><h2>פִּתְרוֹנוֹת – מבחן 6<\/h2>\n<table>\n<tr><th>שאלה<\/th><th>תשובה<\/th><th>הסבר + טריק<\/th><\/tr>\n<tr><th colspan=\"3\">קטע 1 – הדבורים<\/th><\/tr>\n<tr><td>1<\/td><td>ג<\/td><td>שורות 8–9: השאלה \"איך היא מספרת לחברותיה היכן השדה?\" – והתשובה: בריקוד. טריק: בוחרים רק לפי הכתוב; לקרוא שורה לפני ושורה אחרי.<\/td><\/tr>\n<tr><td>2<\/td><td>א<\/td><td>\"רוקדת לפניהן... והן עוקבות אחריה\" – הן = חברותיה (ש' 8), הדבורים שרואות את הריקוד. טריק: כינוי גוף – להחליף את המילה ולקרוא בקול.<\/td><\/tr>\n<tr><td>3<\/td><td>ב<\/td><td>מלכה מטילה, צעירות מנקות ומאכילות, אחרות שומרות, מבוגרות אוספות צוף – תפקידים שונים. טריק: לסכם את השורות במשפט אחד לפני שקוראים את האפשרויות.<\/td><\/tr>\n<tr><td>4<\/td><td>ג<\/td><td>דבש מצוף (ש' 6), עקיצה אחת (ש' 15), תפקיד הצעירות (ש' 3) – מופיעים; אורך חיי המלכה – לא. טריק: לסמן ✓ ליד מה שמופיע.<\/td><\/tr>\n<tr><td>5<\/td><td>ריקוד<\/td><td>שורה 9: \"רוקדת לפניהן ריקוד מיוחד\". מתקבל גם: הריקוד, רקוד. טריק: השלמה – לחפש בקטע את המילה שליד \"מיוחד\".<\/td><\/tr>\n<tr><th colspan=\"3\">קטע 2 – יום שישי בשוק<\/th><\/tr>\n<tr><td>1<\/td><td>ד<\/td><td>אחרי הנקודתיים בא ההסבר: מוכרים צעקו, אנשים נדחקו, מוזיקה מכל צד = רעש ותנועה. טריק: מילה לא מוכרת – לקרוא את המשך המשפט.<\/td><\/tr>\n<tr><td>2<\/td><td>ב<\/td><td>\"רק לרגע אחד\" מדגיש כמה מהר זה קרה (ש' 7: כבר לא היה לידה). טריק: מטרת משפט – כמעט תמיד \"להדגיש / להסביר\".<\/td><\/tr>\n<tr><td>3<\/td><td>א<\/td><td>שורה 9: אימא אמרה \"צריך לרוץ ולחפש\" – גם יעלי רצתה. טריק: ב\"גם\" שואלים \"מי עוד?\" וקוראים שורה לפני.<\/td><\/tr>\n<tr><td>4<\/td><td>ג<\/td><td>שורה 12: \"עומדים במקום... עמית בטח זוכר!\" ד' שגוי – היא עוד לא ידעה איפה הוא. טריק: מסיח שנכון לחלק אחר של הסיפור.<\/td><\/tr>\n<tr><td>5<\/td><td>ד<\/td><td>מיד אחר כך היא אומרת \"סליחה שעזבתי את היד\" – היא מצטערת ומתביישת. טריק: רגש – לחפש את המילים שבאות מיד אחרי.<\/td><\/tr>\n<tr><td>6<\/td><td>א<\/td><td>לחשה ↔ צעקה – הפכים. שאר הצמדים נרדפים. טריק: להציב במשפט; לשים לב ל\"אינן\".<\/td><\/tr>\n<tr><td>7<\/td><td>ב<\/td><td>כל הסיפור סובב סביב הכלל \"עומדים במקום ומבקשים עזרה ממוכר\". א' וד' לא קרו; ג' – עמית הלך לאיבוד, לא יעלי. טריק: כותרת חייבת להתאים לכל הסיפור.<\/td><\/tr>\n<tr><th colspan=\"3\">חשבון – משימה א'<\/th><\/tr>\n<tr><td>1<\/td><td>93<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">57+30=87<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">87+6=93<\/span>. טריק: להשלים לעשרת; ספרות בסדר הנכון (לא 39).<\/td><\/tr>\n<tr><td>2<\/td><td>36<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">81−40=41<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">41−5=36<\/span>. טריק: לבדוק חיסור בחיבור (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">36+45=81<\/span>).<\/td><\/tr>\n<tr><td>3<\/td><td>48<\/td><td>לוח הכפל: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">8×6=48<\/span>. טריק: ספרות בסדר הנכון (לא 84).<\/td><\/tr>\n<tr><td>4<\/td><td>9<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">9×7=63<\/span>. טריק: חילוק כהפוך כפל.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ב'<\/th><\/tr>\n<tr><td>1<\/td><td>47<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">91−44=47<\/span>. טריק: בדיקה בהצבה (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">44+47=91<\/span>).<\/td><\/tr>\n<tr><td>2<\/td><td>63<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">34+29=63<\/span>. טריק: נעלם במקום הראשון בחיסור – מחברים (לא מחסרים!); בדיקה: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">63−29=34<\/span>.<\/td><\/tr>\n<tr><td>3<\/td><td>9<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">6×9=54<\/span>. טריק: חילוק כהפוך כפל.<\/td><\/tr>\n<tr><td>4<\/td><td>20<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">5×6=30<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">50−20=30<\/span>. טריק: מאזניים – לכסות ולפתור קודם את הצד המלא.<\/td><\/tr>\n<tr><td>5<\/td><td>כל מספר גדול מ-4<\/td><td>7 משני הצדדים – משווים רק את מה ששונה: צריך מספר גדול מ-4. למשל 5.<\/td><\/tr>\n<tr><td>6<\/td><td>כל מספר קטן מ-30 (0 עד 29)<\/td><td>56 משני הצדדים; בחיסור הכיוון מתהפך: מורידים פחות → נשאר יותר. למשל 20.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ג'<\/th><\/tr>\n<tr><td>1<\/td><td>ד (25)<\/td><td>שני: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">9−4=5<\/span>; שלישי: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">5+6=11<\/span>; <span dir=\"ltr\" style=\"unicode-bidi:isolate\">9+5+11=25<\/span>. טריק: שרשרת השוואות – \"יותר ממי?\" (מהשני, לא מהראשון → 29).<\/td><\/tr>\n<tr><td>2<\/td><td>ג (8:15)<\/td><td>25 דקות עד 8:00, ועוד 15 דקות. טריק: שעון – לקפוץ לשעה העגולה ואז להוסיף את השאר.<\/td><\/tr>\n<tr><td>3<\/td><td>א (32)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">40−8=32<\/span>. טריק: \"בכמה\" = חיסור, \"פי כמה\" = חילוק (5).<\/td><\/tr>\n<tr><td>4<\/td><td>ב (5+2+2)<\/td><td>עודף: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">20−11=9<\/span>; רק <span dir=\"ltr\" style=\"unicode-bidi:isolate\">5+2+2=9<\/span>. א' ו-ד' = 8, ג' = 10. טריק: קודם לחשב את העודף, ואז לחבר את המטבעות בכל אפשרות.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ד'<\/th><\/tr>\n<tr><td>1<\/td><td>ב (3)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">★=28:4=7<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">♣=10−7=3<\/span>. טריק: להתחיל מהשורה עם סמל אחד בלבד; 7 הוא תוצאת ביניים.<\/td><\/tr>\n<tr><td>2<\/td><td>ד (8)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">●=9<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">▲+▲=25−9=16<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">▲=8<\/span>. טריק: סמל כפול + החלפה; 16 הוא תוצאת ביניים.<\/td><\/tr>\n<tr><td>3<\/td><td>א (6)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">✿+☀&#xFE0E;=13<\/span> היא \"חבילה\": <span dir=\"ltr\" style=\"unicode-bidi:isolate\">✿=20−13=7<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">☀&#xFE0E;=13−7=6<\/span>. טריק: החלפת קבוצה שלמה; לבדוק על מי שואלים (7 הוא ✿).<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ה'<\/th><\/tr>\n<tr><td>1<\/td><td>ג (4)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">24+34=58<\/span>. טריק: ספרת האחדות – <span dir=\"ltr\" style=\"unicode-bidi:isolate\">∆+∆<\/span> מסתיים ב-8 → 4 או 9; <span dir=\"ltr\" style=\"unicode-bidi:isolate\">29+39=68<\/span> לא מתאים.<\/td><\/tr>\n<tr><td>2<\/td><td>ד (3)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">33+33=66<\/span>. טריק: ∆ בעשרות – <span dir=\"ltr\" style=\"unicode-bidi:isolate\">3+3=6<\/span> באחדות, נשאר <span dir=\"ltr\" style=\"unicode-bidi:isolate\">∆+∆=6<\/span>.<\/td><\/tr>\n<\/table><\/section>", "id": 6, "pdf": "pdf/test_6.pdf", "questions": 31}, {"title": "מבחן תרגול 7", "html": "<section class=\"cover\">\n  <h1>מִבְחַן תִּרְגּוּל – שָׁלָב א'<\/h1>\n  <div>כִּיתָה ב' · מִבְחָן מִסְפָּר 7<\/div>\n  <div class=\"fields\">שֵׁם: ____________________<br>תַּאֲרִיךְ: ________________<\/div>\n<\/section>\n\n<h2>חֵלֶק רִאשׁוֹן: קִטְעֵי קְרִיאָה וּשְׁאֵלוֹת<\/h2>\n<p class=\"instr\">קִרְאוּ אֶת הַהוֹרָאוֹת שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרֵיהֶן.<\/p>\n<div class=\"passage-title\">אֵיךְ מְכִינִים מַאֲכִיל צִיפּוֹרִים מִבַּקְבּוּק?<\/div>\n<ol class=\"lines\">\n  <li>בַּחוֹרֶף קָשֶׁה לַצִּיפּוֹרִים לִמְצוֹא אוֹכֶל. רוֹצִים לַעֲזוֹר לָהֶן?<\/li>\n  <li>אֶפְשָׁר לְהָכִין לָהֶן מַאֲכִיל פָּשׁוּט, אֲפִילּוּ מִבַּקְבּוּק שֶׁעָמַדְתֶּם לִזְרוֹק.<\/li>\n  <li>מָה צָרִיךְ לְהָכִין? בַּקְבּוּק פְּלַסְטִיק רֵיק עִם פְּקָק, כַּף עֵץ אֲרוּכָּה,<\/li>\n  <li>חוּט חָזָק, מִסְפָּרַיִים וְשַׂקִּית שֶׁל זְרָעִים. וְעַכְשָׁיו – לַעֲבוֹדָה!<\/li>\n  <li>שָׁלָב 1: שׁוֹטְפִים אֶת הַבַּקְבּוּק הֵיטֵב וּמְיַיבְּשִׁים אוֹתוֹ לְגַמְרֵי.<\/li>\n  <li>שָׁלָב 2: חוֹתְכִים בַּבַּקְבּוּק שְׁנֵי חוֹרִים זֶה מוּל זֶה – אֶחָד קָטָן וְאֶחָד גָּדוֹל.<\/li>\n  <li>זִכְרוּ: חוֹתְכִים רַק יַחַד עִם מְבוּגָּר, כִּי הַמִּסְפָּרַיִים חַדִּים!<\/li>\n  <li>שָׁלָב 3: מַשְׁחִילִים כַּף עֵץ דֶּרֶךְ הַחוֹרִים. מֵהַחוֹר הַגָּדוֹל יִפְּלוּ זְרָעִים לַכַּף.<\/li>\n  <li>שָׁלָב 4: מְמַלְּאִים אֶת הַבַּקְבּוּק בִּזְרָעִים וְסוֹגְרִים אוֹתוֹ בַּפְּקָק.<\/li>\n  <li>שָׁלָב 5: קוֹשְׁרִים חוּט סְבִיב צַוַּואר הַבַּקְבּוּק וְתוֹלִים אוֹתוֹ עַל עָנָף.<\/li>\n  <li>כַּמָּה עֵצוֹת חֲשׁוּבוֹת: תְּלוּ אֶת הַמַּאֲכִיל בְּמָקוֹם גָּבוֹהַּ וּמוּצָל.<\/li>\n  <li>בְּמָקוֹם גָּבוֹהַּ הַצִּיפּוֹרִים מוּגַנּוֹת מִפְּנֵי חֲתוּלִים,<\/li>\n  <li>וּבְמָקוֹם מוּצָל הַזְּרָעִים אֵינָם מִתְקַלְקְלִים מֵהַחוֹם.<\/li>\n  <li>בִּדְקוּ אֶת הַמַּאֲכִיל כָּל כַּמָּה יָמִים. אִם הַזְּרָעִים אוֹזְלִים, מַלְּאוּ אוֹתוֹ שׁוּב.<\/li>\n  <li>אַל תִּתְאַכְזְבוּ אִם בַּיָּמִים הָרִאשׁוֹנִים אַף צִיפּוֹר לֹא תָּבוֹא.<\/li>\n  <li>הַצִּיפּוֹרִים חַשְׁדָנִיּוֹת, וְהֵן צְרִיכוֹת זְמַן כְּדֵי לְהִתְרַגֵּל לְדָבָר חָדָשׁ.<\/li>\n  <li>חַכּוּ בְּסַבְלָנוּת, וּבְקָרוֹב תִּרְאוּ אוֹרְחוֹת מְצַיְּיצוֹת לְיַד הַחַלּוֹן.<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה בְּכָל שְׁאֵלָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. מָה עוֹשִׂים מִיָּד לִפְנֵי שֶׁמְּמַלְּאִים אֶת הַבַּקְבּוּק בִּזְרָעִים?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>קוֹשְׁרִים חוּט סְבִיב צַוַּואר הַבַּקְבּוּק<\/li><li><span class=\"l\">ב.<\/span>שׁוֹטְפִים אֶת הַבַּקְבּוּק וּמְיַיבְּשִׁים אוֹתוֹ<\/li><li><span class=\"l\">ג.<\/span>מַשְׁחִילִים אֶת כַּף הָעֵץ דֶּרֶךְ הַחוֹרִים<\/li><li><span class=\"l\">ד.<\/span>תּוֹלִים אֶת הַבַּקְבּוּק עַל עָנָף<\/li><\/ol><\/div>\n<div class=\"q\"><div class=\"stem\">2. מָה פֵּירוּשׁ הַמִּילָה \"אוֹזְלִים\" (שׁוּרָה 14)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>נִגְמָרִים<\/li><li><span class=\"l\">ב.<\/span>נִרְטָבִים<\/li><li><span class=\"l\">ג.<\/span>צוֹמְחִים<\/li><li><span class=\"l\">ד.<\/span>מַבְרִיקִים<\/li><\/ol><\/div>\n<div class=\"q\"><div class=\"stem\">3. יַלְדָּה הֵכִינָה מַאֲכִיל צִיפּוֹרִים לְפִי הַהוֹרָאוֹת שֶׁבַּקֶּטַע.<br>אֵיפֹה כְּדַאי לָהּ לִתְלוֹת אוֹתוֹ?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>עַל גָּדֵר נְמוּכָה, בְּמָקוֹם מוּצָל<\/li><li><span class=\"l\">ב.<\/span>עַל עָנָף גָּבוֹהַּ, בְּצֵל הָעֵץ<\/li><li><span class=\"l\">ג.<\/span>עַל עַמּוּד גָּבוֹהַּ, בְּמָקוֹם שֶׁהַשֶּׁמֶשׁ זוֹרַחַת עָלָיו כָּל הַיּוֹם<\/li><li><span class=\"l\">ד.<\/span>עַל רִצְפַּת הַמִּרְפֶּסֶת, בְּמָקוֹם שֶׁהַשֶּׁמֶשׁ זוֹרַחַת עָלָיו<\/li><\/ol><\/div>\n<div class=\"q\"><div class=\"stem\">4. בְּשׁוּרָה 7 כָּתוּב: \"כִּי הַמִּסְפָּרַיִים חַדִּים!\"<br>הַמַּטָּרָה שֶׁל הַמִּילִים הָאֵלֶּה הִיא –<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>לְסַפֵּר אֵילוּ מִסְפָּרַיִים כְּדַאי לִקְנוֹת<\/li><li><span class=\"l\">ב.<\/span>לְשַׁכְנֵעַ אוֹתָנוּ לֹא לְהָכִין מַאֲכִיל צִיפּוֹרִים<\/li><li><span class=\"l\">ג.<\/span>לְהַדְגִּישׁ שֶׁהַבַּקְבּוּק עָשׂוּי מִפְּלַסְטִיק קָשֶׁה<\/li><li><span class=\"l\">ד.<\/span>לְהַסְבִּיר מַדּוּעַ חוֹתְכִים רַק יַחַד עִם מְבוּגָּר<\/li><\/ol><\/div>\n<div class=\"q\"><div class=\"stem\">5. בְּשׁוּרָה 2 כָּתוּב: \"אֲפִילּוּ מִבַּקְבּוּק שֶׁעָמַדְתֶּם לִזְרוֹק\".<br>מַדּוּעַ כָּתוּב \"אֲפִילּוּ\"?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כְּדֵי לְהַדְגִּישׁ שֶׁלֹּא צָרִיךְ חוֹמָרִים מְיוּחָדִים – גַּם בַּקְבּוּק יָשָׁן מַתְאִים<\/li><li><span class=\"l\">ב.<\/span>כִּי צִיפּוֹרִים אוֹהֲבוֹת בַּקְבּוּקִים יוֹתֵר מִכָּל דָּבָר אַחֵר<\/li><li><span class=\"l\">ג.<\/span>כִּי אָסוּר לִזְרוֹק בַּקְבּוּקִים לַפַּח<\/li><li><span class=\"l\">ד.<\/span>כִּי מַאֲכִיל מִבַּקְבּוּק טוֹב יוֹתֵר מִמַּאֲכִיל מֵעֵץ<\/li><\/ol><\/div>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">קִרְאוּ אֶת הַסִּיפּוּר שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרָיו.<\/p>\n<div class=\"passage-title\">הַשְּׁתִיקָה שֶׁל רוֹעִי<\/div>\n<ol class=\"lines long\">\n  <li>בַּבּוֹקֶר רָאָה אָדָם אֶת רוֹעִי, חֲבֵרוֹ הַטּוֹב, בִּשְׁעַר בֵּית הַסֵּפֶר.<\/li>\n  <li>רוֹעִי עָטַף אֶת צַוָּוארוֹ בְּצָעִיף עָבֶה, אַף עַל פִּי שֶׁהַיּוֹם הָיָה חָמִים.<\/li>\n  <li>\"בּוֹקֶר טוֹב, רוֹעִי! מָה שְׁלוֹמְךָ?\" קָרָא אָדָם.<\/li>\n  <li>רוֹעִי לֹא עָנָה. הוּא רַק הֵנִיד בְּרֹאשׁוֹ וְהִמְשִׁיךְ לָלֶכֶת.<\/li>\n  <li>\"מוּזָר,\" חָשַׁב אָדָם. \"אוּלַי הוּא לֹא שָׁמַע אוֹתִי.\"<\/li>\n  <li>בַּהַפְסָקָה שָׁאַל אָדָם: \"בָּא לְךָ לְשַׂחֵק כַּדּוּרֶגֶל?\"<\/li>\n  <li>רוֹעִי הִצְבִּיעַ עַל גְּרוֹנוֹ, מָשַׁךְ בִּכְתֵפָיו וְנִשְׁאַר לָשֶׁבֶת עַל הַסַּפְסָל.<\/li>\n  <li>אָדָם לֹא הֵבִין אֶת הַתְּנוּעָה. לִיבּוֹ הִתְכַּוֵּוץ.<\/li>\n  <li>\"הוּא בֶּטַח כּוֹעֵס עָלַיי,\" חָשַׁב. \"אֶתְמוֹל לֹא מָסַרְתִּי לוֹ אֶת הַכַּדּוּר,<\/li>\n  <li>וְהַקְּבוּצָה שֶׁלָּנוּ הִפְסִידָה. עַכְשָׁיו הוּא לֹא רוֹצֶה לְדַבֵּר אִיתִּי.\"<\/li>\n  <li>גַּם בַּאֲרוּחַת הָעֶשֶׂר יָשַׁב רוֹעִי בְּשֶׁקֶט וְלֹא אָמַר אַף מִילָּה.<\/li>\n  <li>כָּל הַיּוֹם הִסְתּוֹבֵב אָדָם עָצוּב. הוּא אֲפִילּוּ לֹא נָגַע בַּכָּרִיךְ שֶׁלּוֹ.<\/li>\n  <li>בְּסוֹף הַיּוֹם אָזַר אָדָם אוֹמֶץ וְנִיגַּשׁ אֶל רוֹעִי.<\/li>\n  <li>\"סְלִיחָה שֶׁלֹּא מָסַרְתִּי לְךָ אֶת הַכַּדּוּר. אַל תִּכְעַס עָלַיי,\" אָמַר בְּקוֹל רוֹעֵד.<\/li>\n  <li>רוֹעִי פָּקַח עֵינַיִים גְּדוֹלוֹת, כָּתַב מַשֶּׁהוּ בְּמַחְבֶּרֶת וְהוֹשִׁיט אוֹתָהּ לְאָדָם.<\/li>\n  <li>אָדָם קָרָא: \"אֲנִי לֹא כּוֹעֵס בִּכְלָל! יֵשׁ לִי דַּלֶּקֶת בַּגָּרוֹן,<\/li>\n  <li>וְהַקּוֹל שֶׁלִּי נֶעֱלַם. הָרוֹפֵא אָמַר לִי לֹא לְדַבֵּר שְׁלוֹשָׁה יָמִים.\"<\/li>\n  <li>אָדָם הִבִּיט בַּצָּעִיף, נִזְכַּר בַּיָּד שֶׁהִצְבִּיעָה עַל הַגָּרוֹן, וּפָרַץ בִּצְחוֹק.<\/li>\n  <li>\"וַאֲנִי דָּאַגְתִּי כָּל הַיּוֹם לְחִינָּם!\" אָמַר. \"לָמָּה לֹא כָּתַבְתָּ לִי בַּבּוֹקֶר?\"<\/li>\n  <li>רוֹעִי חִיֵּיךְ וְכָתַב: \"לֹא חָשַׁבְתִּי עַל זֶה. וְלָמָּה אַתָּה לֹא שָׁאַלְתָּ?\"<\/li>\n  <li>\"צוֹדֵק,\" אָמַר אָדָם. \"בַּפַּעַם הַבָּאָה אֶשְׁאַל, וְלֹא אֲנַחֵשׁ לְבַד.\"<\/li>\n  <li>מֵאוֹתוֹ יוֹם, כְּשֶׁמַּשֶּׁהוּ מַטְרִיד אֶת אָדָם, הוּא קוֹדֶם כּוֹל שׁוֹאֵל.<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה בְּכָל שְׁאֵלָה.<\/p>\n\n<div class=\"tight\">\n<div class=\"q\"><div class=\"stem\">1. מַדּוּעַ חָשַׁב אָדָם שֶׁרוֹעִי כּוֹעֵס עָלָיו?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי רוֹעִי אָמַר לוֹ בַּבּוֹקֶר שֶׁהוּא כּוֹעֵס<\/li><li><span class=\"l\">ב.<\/span>כִּי יוֹם קוֹדֶם לֹא מָסַר לְרוֹעִי אֶת הַכַּדּוּר, וְהַקְּבוּצָה הִפְסִידָה<\/li><li><span class=\"l\">ג.<\/span>כִּי שָׁכַח לְהָבִיא לְרוֹעִי כָּרִיךְ לַאֲרוּחַת הָעֶשֶׂר<\/li><li><span class=\"l\">ד.<\/span>כִּי לֹא הִזְמִין אֶת רוֹעִי לְשַׂחֵק כַּדּוּרֶגֶל בַּהַפְסָקָה<\/li><\/ol><\/div>\n<div class=\"q\"><div class=\"stem\">2. בְּשׁוּרָה 15 כָּתוּב: \"וְהוֹשִׁיט אוֹתָהּ לְאָדָם\".<br>אֵיזוֹ מִילָה יְכוֹלָה לְהַחְלִיף אֶת הַמִּילָה \"הוֹשִׁיט\"?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>הֶחְבִּיא<\/li><li><span class=\"l\">ב.<\/span>קָרַע<\/li><li><span class=\"l\">ג.<\/span>סָגַר<\/li><li><span class=\"l\">ד.<\/span>הִגִּישׁ<\/li><\/ol><\/div>\n<div class=\"q\"><div class=\"stem\">3. מָה פֵּירוּשׁ הַמִּילָה \"לְחִינָּם\" (שׁוּרָה 19)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>בְּלִי סִיבָּה אֲמִיתִּית<\/li><li><span class=\"l\">ב.<\/span>בְּלִי לְשַׁלֵּם כֶּסֶף<\/li><li><span class=\"l\">ג.<\/span>בְּקוֹל רָם<\/li><li><span class=\"l\">ד.<\/span>לִזְמַן קָצָר<\/li><\/ol><\/div>\n<div class=\"q\"><div class=\"stem\">4. מַדּוּעַ בֶּאֱמֶת לֹא עָנָה רוֹעִי לְאָדָם כָּל הַיּוֹם?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי לֹא שָׁמַע אֶת מָה שֶׁאָדָם אָמַר לוֹ<\/li><li><span class=\"l\">ב.<\/span>כִּי כָּעַס עַל אָדָם שֶׁלֹּא מָסַר לוֹ אֶת הַכַּדּוּר<\/li><li><span class=\"l\">ג.<\/span>כִּי הָיְתָה לוֹ דַּלֶּקֶת בַּגָּרוֹן, וְהוּא לֹא הָיָה יָכוֹל לְדַבֵּר<\/li><li><span class=\"l\">ד.<\/span>כִּי הוּא הֶעֱדִיף לִכְתּוֹב בַּמַּחְבֶּרֶת וְלֹא לְדַבֵּר<\/li><\/ol><\/div>\n<div class=\"q\"><div class=\"stem\">5. אֵיזֶה מִשְׁפָּט <u>אִי אֶפְשָׁר<\/u> לוֹמַר עַל פִּי הַסִּיפּוּר?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>אָדָם וְרוֹעִי לוֹמְדִים בְּאוֹתוֹ בֵּית סֵפֶר.<\/li><li><span class=\"l\">ב.<\/span>רוֹעִי הָיָה אֵצֶל רוֹפֵא.<\/li><li><span class=\"l\">ג.<\/span>אָדָם לֹא אָכַל אֶת הַכָּרִיךְ שֶׁלּוֹ.<\/li><li><span class=\"l\">ד.<\/span>רוֹעִי שִׂיחֵק כַּדּוּרֶגֶל בַּהַפְסָקָה.<\/li><\/ol><\/div>\n<div class=\"q\"><div class=\"stem\">6. בְּאֵיזֶה צֶמֶד מִילִים הַמִּילִים <u>אֵינָן<\/u> מִילִים נִרְדָּפוֹת?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>מוּזָר – מְשׁוּנֶּה<\/li><li><span class=\"l\">ב.<\/span>נִיגַּשׁ – הִתְקָרֵב<\/li><li><span class=\"l\">ג.<\/span>נֶעֱלַם – הוֹפִיעַ<\/li><li><span class=\"l\">ד.<\/span>הִבִּיט – הִסְתַּכֵּל<\/li><\/ol><\/div>\n<div class=\"q\"><div class=\"stem\">7. מַדּוּעַ פָּרַץ אָדָם בִּצְחוֹק (שׁוּרָה 18)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי הֵבִין שֶׁהַסִּימָנִים הָיוּ מוּל עֵינָיו כָּל הַיּוֹם, וְהוּא דָּאַג בְּלִי סִיבָּה<\/li><li><span class=\"l\">ב.<\/span>כִּי כְּתַב הַיָּד שֶׁל רוֹעִי הָיָה מַצְחִיק<\/li><li><span class=\"l\">ג.<\/span>כִּי רָצָה לִלְעוֹג לְרוֹעִי עַל הַצָּעִיף שֶׁלּוֹ<\/li><li><span class=\"l\">ד.<\/span>כִּי שָׂמַח שֶׁהַקְּבוּצָה שֶׁלָּהֶם הִפְסִידָה בַּמִּשְׂחָק<\/li><\/ol><\/div>\n<p class=\"stop\">עִבְרוּ לָעַמּוּד הַבָּא רַק לְאַחַר שֶׁתְּקַבְּלוּ הוֹרָאָה לְכָךְ מֵהַמּוֹרָה.<\/p>\n\n<\/div>\n<div class=\"page-break\"><\/div>\n<h2>חֵלֶק שֵׁנִי: שְׁאֵלוֹת בְּחֶשְׁבּוֹן<\/h2>\n<h3>מְשִׂימָה א': תַּרְגִּילִים<\/h3>\n<p class=\"instr\">פִּתְרוּ אֶת הַתַּרְגִּילִים וְכִתְבוּ אֶת הַתּוֹצָאָה.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\">48 + 45 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\">90 − 37 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\">7 × 9 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">4. <span class=\"ex\">48 : 8 = <span class=\"blank\"><\/span><\/span><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ב': הַמִּסְפָּר הֶחָסֵר<\/h3>\n<p class=\"instr\">כִּתְבוּ אֶת הַמִּסְפָּר הֶחָסֵר בְּכָל תַּרְגִּיל.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\"><span class=\"blank\"><\/span> − 35 = 27<\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\">63 + <span class=\"blank\"><\/span> = 100<\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\"><span class=\"blank\"><\/span> × 8 = 56<\/span><\/div>\n<p class=\"instr\">כִּתְבוּ עַל הַקַּו מִסְפָּר מַתְאִים.<br>שִׂימוּ לֵב: בְּכָל תַּרְגִּיל יֵשׁ יוֹתֵר מִתְּשׁוּבָה נְכוֹנָה אַחַת.<\/p>\n<div class=\"q mathq\" data-accept=\"mult:3,lt:30\">4. <span class=\"ex\">30 : 3 &gt; <span class=\"blank\"><\/span> : 3<\/span><\/div>\n<div class=\"q mathq\" data-accept=\"range:0-2\">5. <span class=\"ex\">42 + <span class=\"blank\"><\/span> &lt; 45<\/span><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ג': בְּעָיוֹת מִילּוּלִיּוֹת<\/h3>\n<p class=\"instr\">קִרְאוּ כָּל בְּעָיָה וְהַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. מַתָּן אָמַר: \"חָשַׁבְתִּי עַל מִסְפָּר. הוֹסַפְתִּי לוֹ 5,<br>וְאֶת מָה שֶׁקִּיבַּלְתִּי כָּפַלְתִּי בְּ-2. יָצָא לִי 30.\"<br>עַל אֵיזֶה מִסְפָּר חָשַׁב מַתָּן?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>15<\/li><li><span class=\"l\">ב.<\/span>10<\/li><li><span class=\"l\">ג.<\/span>20<\/li><li><span class=\"l\">ד.<\/span>12<\/li><\/ol><\/div>\n<div class=\"q\"><div class=\"stem\">2. בַּחֲנוּת, 4 עֶפְרוֹנוֹת עוֹלִים 10 שְׁקָלִים.<br>אֲבִיגַיִל קָנְתָה 12 עֶפְרוֹנוֹת כָּאֵלֶּה. כַּמָּה שְׁקָלִים שִׁילְּמָה?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>18<\/li><li><span class=\"l\">ב.<\/span>40<\/li><li><span class=\"l\">ג.<\/span>22<\/li><li><span class=\"l\">ד.<\/span>30<\/li><\/ol><\/div>\n<div class=\"q\"><div class=\"stem\">3. מַתָּן כָּתַב סִדְרָה שֶׁל מִסְפָּרִים לְפִי חוּקִיּוּת:<br><span class=\"ex\">20, 15, 18, 13, 16, <span class=\"blank\"><\/span><\/span><br>אֵיזֶה מִסְפָּר צָרִיךְ לִהְיוֹת עַל הַקַּו?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>11<\/li><li><span class=\"l\">ב.<\/span>19<\/li><li><span class=\"l\">ג.<\/span>14<\/li><li><span class=\"l\">ד.<\/span>21<\/li><\/ol><\/div>\n<div class=\"q\"><div class=\"stem\">4. לַמְּסִיבָּה שֶׁל אֲבִיגַיִל בָּאוּ 45 יְלָדִים. לְיַד כָּל שׁוּלְחָן יֵשׁ 8 מְקוֹמוֹת.<br>כַּמָּה שׁוּלְחָנוֹת צָרִיךְ <u>לְפָחוֹת<\/u>, כְּדֵי שֶׁלְּכָל הַיְּלָדִים יִהְיֶה מָקוֹם לָשֶׁבֶת?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>5<\/li><li><span class=\"l\">ב.<\/span>37<\/li><li><span class=\"l\">ג.<\/span>6<\/li><li><span class=\"l\">ד.<\/span>7<\/li><\/ol><\/div>\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ד': חִידוֹת בְּצִיּוּרִים<\/h3>\n<p class=\"instr\">בְּכָל חִידָה, כָּל צִיּוּר מַסְתִּיר מִסְפָּר. אוֹתוֹ צִיּוּר מַסְתִּיר תָּמִיד אוֹתוֹ מִסְפָּר.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">✈&#xFE0E;<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>♠ + ♠ = 14<\/td><\/tr><tr><td>♠ + ✈&#xFE0E; = 20<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>7<\/li><li><span class=\"l\">ב.<\/span>6<\/li><li><span class=\"l\">ג.<\/span>10<\/li><li><span class=\"l\">ד.<\/span>13<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">♥<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>☂&#xFE0E; + ☂&#xFE0E; + ☂&#xFE0E; = 12<\/td><\/tr><tr><td>☂&#xFE0E; + ♥ + ♥ = 20<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>16<\/li><li><span class=\"l\">ב.<\/span>8<\/li><li><span class=\"l\">ג.<\/span>4<\/li><li><span class=\"l\">ד.<\/span>6<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">●<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>● + ★ = 15<\/td><\/tr><tr><td>● + ★ + ★ = 22<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>7<\/li><li><span class=\"l\">ב.<\/span>9<\/li><li><span class=\"l\">ג.<\/span>8<\/li><li><span class=\"l\">ד.<\/span>15<\/li><\/ol><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ה': תַּרְגִּילֵי מְשׁוּלָּשִׁים<\/h3>\n<p class=\"instr\">בְּכָל תַּרְגִּיל הַמְּשׁוּלָּשׁ ∆ מַסְתִּיר סִפְרָה. בְּאוֹתוֹ תַּרְגִּיל כָּל הַמְּשׁוּלָּשִׁים מַסְתִּירִים אוֹתָהּ סִפְרָה.<br>אֵיזוֹ סִפְרָה מַסְתִּיר הַמְּשׁוּלָּשׁ? הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. <span class=\"ex\">1∆ + 1∆ = 36<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>8<\/li><li><span class=\"l\">ב.<\/span>3<\/li><li><span class=\"l\">ג.<\/span>6<\/li><li><span class=\"l\">ד.<\/span>9<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. <span class=\"ex\">3∆ + ∆3 = 88<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>4<\/li><li><span class=\"l\">ב.<\/span>5<\/li><li><span class=\"l\">ג.<\/span>8<\/li><li><span class=\"l\">ד.<\/span>3<\/li><\/ol><\/div>\n\n<p class=\"end\">סוֹף הַמִּבְחָן<\/p>\n\n<section class=\"answers\"><h2>פִּתְרוֹנוֹת – מבחן 7<\/h2>\n<table>\n<tr><th>שאלה<\/th><th>תשובה<\/th><th>הסבר + טריק<\/th><\/tr>\n<tr><th colspan=\"3\">קטע 1 – איך מכינים מאכיל ציפורים מבקבוק? (טקסט הוראות)<\/th><\/tr>\n<tr><td>1<\/td><td>ג<\/td><td>מילוי בזרעים = שלב 4 (ש' 9); מיד לפניו שלב 3 – משחילים את הכף (ש' 8). ב' = שלב 1 (הרבה לפני), א' ו-ד' = שלב 5 (אחרי). טריק: סדר שלבים – למצוא את השלב ולקרוא את המספר שלפניו; לשים לב ל\"לפני\"/\"אחרי\".<\/td><\/tr>\n<tr><td>2<\/td><td>א<\/td><td>\"אם הזרעים אוזלים, מלאו אותו שוב\" – ממלאים שוב כשנגמר. טריק: לקרוא את כל המשפט שסביב המילה.<\/td><\/tr>\n<tr><td>3<\/td><td>ב<\/td><td>ש' 11: \"במקום גבוה ומוצל\" – צריך את שני התנאים. א' = מוצל אבל נמוך (חתולים), ג' = גבוה אבל בשמש (הזרעים מתקלקלים), ד' = לא זה ולא זה. טריק: שאלת יישום – לחפש את ההמלצה ולבדוק כל תנאי בנפרד.<\/td><\/tr>\n<tr><td>4<\/td><td>ד<\/td><td>המילה \"כי\" מנמקת את האזהרה שלפניה: חותכים רק עם מבוגר. טריק: \"מטרת המשפט\" → כדי להסביר; לקרוא את תחילת המשפט.<\/td><\/tr>\n<tr><td>5<\/td><td>א<\/td><td>\"אפילו\" מדגיש דבר לא צפוי: גם מבקבוק שנראה כמו אשפה אפשר להכין מאכיל. טריק: ב\"אפילו\" שואלים \"מה מפתיע כאן?\".<\/td><\/tr>\n<tr><th colspan=\"3\">קטע 2 – השתיקה של רועי (סיפור עם תפנית)<\/th><\/tr>\n<tr><td>1<\/td><td>ב<\/td><td>ש' 9–10: \"אתמול לא מסרתי לו את הכדור, והקבוצה שלנו הפסידה\". רועי לא אמר דבר (א'); אדם דווקא הזמין אותו לשחק (ד'). טריק: בוחרים רק לפי הכתוב.<\/td><\/tr>\n<tr><td>2<\/td><td>ד<\/td><td>הושיט את המחברת = הגיש אותה, ואז אדם קרא בה (ש' 16). טריק: להציב כל מילה במשפט ולבדוק שהמשמעות נשמרת.<\/td><\/tr>\n<tr><td>3<\/td><td>א<\/td><td>אדם דאג כל היום, ובסוף התברר שלא הייתה סיבה לדאגה. ב' = פירוש אחר של \"חינם\" שלא מתאים למשפט. טריק: מילה עם שני פירושים – לבחור את זה שמתאים למשפט.<\/td><\/tr>\n<tr><td>4<\/td><td>ג<\/td><td>ש' 16–17: דלקת בגרון, הקול נעלם, הרופא אסר לדבר. ב' = מה שאדם חשב (החשד), לא מה שקרה. רמזים מוקדמים: הצעיף (ש' 2), ההצבעה על הגרון (ש' 7). טריק: \"מה באמת קרה?\" – להבדיל בין מה שהדמות חשבה למה שהתברר בסוף.<\/td><\/tr>\n<tr><td>5<\/td><td>ד<\/td><td>ש' 7: רועי נשאר לשבת על הספסל – הוא לא שיחק. א' – שער בית הספר (ש' 1); ב' – \"הרופא אמר לי\" (ש' 17); ג' – \"לא נגע בכריך\" (ש' 12). טריק: לסמן ✓ ליד כל משפט שיש לו הוכחה בסיפור; מה שנשאר – התשובה.<\/td><\/tr>\n<tr><td>6<\/td><td>ג<\/td><td>נעלם ↔ הופיע – הפכים. שאר הצמדים קרובים במשמעות. טריק: לשים לב ל\"אינן\"; להציב במשפט.<\/td><\/tr>\n<tr><td>7<\/td><td>א<\/td><td>ש' 18: הוא מביט בצעיף ונזכר בהצבעה על הגרון – מבין שהרמזים היו שם, ואומר \"דאגתי לחינם\" (ש' 19). טריק: רגש של דמות – לקרוא שורה לפני ושורה אחרי.<\/td><\/tr>\n<tr><th colspan=\"3\">חשבון – משימה א'<\/th><\/tr>\n<tr><td>1<\/td><td>93<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">48+45 = 50+43 = 93<\/span>. טריק: להשלים לעשרת.<\/td><\/tr>\n<tr><td>2<\/td><td>53<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">90−40=50<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">50+3=53<\/span>. בדיקה: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">53+37=90<\/span>. טריק: לבדוק חיסור בחיבור.<\/td><\/tr>\n<tr><td>3<\/td><td>63<\/td><td>לוח הכפל: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">7×9=63<\/span>. טריק: ספרות בסדר הנכון (לא 36).<\/td><\/tr>\n<tr><td>4<\/td><td>6<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">6×8=48<\/span>, ולכן <span dir=\"ltr\" style=\"unicode-bidi:isolate\">48:8=6<\/span>. טריק: חילוק כהפוך כפל.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ב'<\/th><\/tr>\n<tr><td>1<\/td><td>62<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">27+35=62<\/span>. טריק: נעלם במקום הראשון בחיסור – מחברים (לא <span dir=\"ltr\" style=\"unicode-bidi:isolate\">35−27<\/span>)! בדיקה: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">62−35=27<\/span>.<\/td><\/tr>\n<tr><td>2<\/td><td>37<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">100−63=37<\/span>. טריק: השלמה ל-100: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">63+7=70<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">70+30=100<\/span>.<\/td><\/tr>\n<tr><td>3<\/td><td>7<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">7×8=56<\/span>. טריק: חילוק כהפוך כפל (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">56:8<\/span>).<\/td><\/tr>\n<tr><td>4<\/td><td>כל מספר שמתחלק ב-3 וקטן מ-30 (0, 3, 6, … 27)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">30:3=10<\/span>; מחלקים באותו מספר, ולכן המחולק צריך להיות קטן מ-30 – ולהתחלק ב-3. למשל 15 (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">15:3=5<\/span>). טריק: אותו מחלק משני הצדדים – משווים רק את מה ששונה.<\/td><\/tr>\n<tr><td>5<\/td><td>0, 1 או 2<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">42+3=45<\/span> כבר לא קטן מ-45. טריק: גבול עליון – למצוא מתי מגיעים בדיוק ל-45 ולבחור פחות.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ג'<\/th><\/tr>\n<tr><td>1<\/td><td>ב (10)<\/td><td>הולכים אחורה: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">30:2=15<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">15−5=10<\/span>. בדיקה: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">10+5=15<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">15×2=30<\/span>. טריק: \"חשבתי על מספר\" – להפוך את הפעולות מהסוף להתחלה; 15 = תוצאת ביניים.<\/td><\/tr>\n<tr><td>2<\/td><td>ד (30)<\/td><td>12 עפרונות = 3 קבוצות של 4; <span dir=\"ltr\" style=\"unicode-bidi:isolate\">3×10=30<\/span>. טריק: יחס – כמה פעמים נכנסת הקבוצה; לא להוסיף 8 (18) ולא לכפול <span dir=\"ltr\" style=\"unicode-bidi:isolate\">4×10<\/span> (40).<\/td><\/tr>\n<tr><td>3<\/td><td>א (11)<\/td><td>החוקיות: פחות 5, ועוד 3, וחוזר חלילה. אחרי 16 – פחות 5: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">16−5=11<\/span>. טריק: סדרה מתחלפת – לכתוב את ההפרשים מתחת, או להסתכל על כל מספר שני (15, 13, 11).<\/td><\/tr>\n<tr><td>4<\/td><td>ג (6)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">5×8=40<\/span> – נשארים 5 ילדים בלי מקום; <span dir=\"ltr\" style=\"unicode-bidi:isolate\">6×8=48<\/span> מספיק. טריק: \"כמה לפחות\" – מעגלים כלפי מעלה; 37 = חיסור במקום חילוק.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ד'<\/th><\/tr>\n<tr><td>1<\/td><td>ד (13)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">♠=14:2=7<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">✈&#xFE0E;=20−7=13<\/span>. טריק: להתחיל מהשורה עם סמל אחד בלבד (7 = הערך של ♠, לא מה שנשאל; 6 = <span dir=\"ltr\" style=\"unicode-bidi:isolate\">20−14<\/span>).<\/td><\/tr>\n<tr><td>2<\/td><td>ב (8)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">☂&#xFE0E;=12:3=4<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">♥+♥=20−4=16<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">♥=8<\/span>. טריק: סמל כפול + החלפה; לא לשכוח לחלק ב-2 (16).<\/td><\/tr>\n<tr><td>3<\/td><td>ג (8)<\/td><td>השורה השנייה = השורה הראשונה ועוד ★ אחד: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">★=22−15=7<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">●=15−7=8<\/span>. טריק: החלפת \"חבילה\" (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">●+★=15<\/span>); לענות על הסמל שנשאל (7 = ★).<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ה'<\/th><\/tr>\n<tr><td>1<\/td><td>א (8)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">18+18=36<\/span>. טריק: ספרת האחדות – <span dir=\"ltr\" style=\"unicode-bidi:isolate\">∆+∆<\/span> מסתיים ב-6 → 3 או 8; <span dir=\"ltr\" style=\"unicode-bidi:isolate\">13+13=26<\/span> לא מתאים.<\/td><\/tr>\n<tr><td>2<\/td><td>ב (5)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">35+53=88<\/span>. טריק: ספרת האחדות – <span dir=\"ltr\" style=\"unicode-bidi:isolate\">∆+3<\/span> מסתיים ב-8 → <span dir=\"ltr\" style=\"unicode-bidi:isolate\">∆=5<\/span>; בדיקה בעשרות: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">3+5=8<\/span>.<\/td><\/tr>\n<\/table><\/section>", "id": 7, "pdf": "pdf/test_7.pdf", "questions": 30}, {"title": "מבחן תרגול 8", "html": "<section class=\"cover\">\n  <h1>מִבְחַן תִּרְגּוּל – שָׁלָב א'<\/h1>\n  <div>כִּיתָּה ב' · מִבְחָן מִסְפָּר 8<\/div>\n  <div class=\"fields\">שֵׁם: ____________________<br>תַּאֲרִיךְ: ________________<\/div>\n<\/section>\n\n<h2>חֵלֶק רִאשׁוֹן: קִטְעֵי קְרִיאָה וּשְׁאֵלוֹת<\/h2>\n<p class=\"instr\">קִרְאוּ אֶת קֶטַע הַמֵּידָע שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרָיו.<\/p>\n<div class=\"passage-title\">הַלֵּב<\/div>\n<ol class=\"lines\">\n  <li>קִפְצוּ אֶת כַּף הַיָּד לְאֶגְרוֹף. זֶה בְּעֵרֶךְ הַגּוֹדֶל שֶׁל הַלֵּב שֶׁלָּכֶם.<\/li>\n  <li>הַלֵּב נִמְצָא בְּתוֹךְ הֶחָזֶה, כִּמְעַט בָּאֶמְצַע, וְנוֹטֶה מְעַט לְצַד שְׂמֹאל.<\/li>\n  <li>הַלֵּב הוּא שְׁרִיר, כְּמוֹ הַשְּׁרִירִים שֶׁבַּיָּדַיִים וּבָרַגְלַיִים.<\/li>\n  <li>אֲבָל שְׁרִירֵי הָרַגְלַיִים מִתְעַיְּיפִים וְנָחִים, וְהַלֵּב אֵינוֹ נָח אַף פַּעַם.<\/li>\n  <li>הוּא עוֹבֵד בַּיּוֹם וּבַלַּיְלָה, גַּם כְּשֶׁאֲנַחְנוּ יְשֵׁנִים שֵׁינָה עֲמוּקָה.<\/li>\n  <li>מָה הָעֲבוֹדָה שֶׁל הַלֵּב? הוּא מִתְכַּוֵּוץ וְדוֹחֵף אֶת הַדָּם אֶל כָּל הַגּוּף.<\/li>\n  <li>הַדָּם זוֹרֵם בְּתוֹךְ צִינּוֹרוֹת דַּקִּים, וּמֵבִיא לְכָל אֵיבָר חַמְצָן וּמָזוֹן.<\/li>\n  <li>כָּל הִתְכַּוְּוצוּת שֶׁל הַלֵּב נִקְרֵאת פְּעִימָה.<\/li>\n  <li>כְּשֶׁאַתֶּם יוֹשְׁבִים בְּשֶׁקֶט, הַלֵּב שֶׁלָּכֶם פּוֹעֵם בְּעֵרֶךְ 90 פְּעָמִים בְּדַקָּה.<\/li>\n  <li>כְּשֶׁאַתֶּם רָצִים אוֹ קוֹפְצִים, הַשְּׁרִירִים זְקוּקִים לְהַרְבֵּה יוֹתֵר חַמְצָן.<\/li>\n  <li>לָכֵן הַלֵּב מַתְחִיל לִפְעוֹם מַהֵר יוֹתֵר, וְשׁוֹלֵחַ אֲלֵיהֶם עוֹד וְעוֹד דָּם.<\/li>\n  <li>אַחֲרֵי כַּמָּה דַּקּוֹת שֶׁל מְנוּחָה, הַלֵּב חוֹזֵר לִפְעוֹם בַּקֶּצֶב הָרָגִיל.<\/li>\n  <li>רוֹצִים לְהַרְגִּישׁ אֶת הַלֵּב שֶׁלָּכֶם עוֹבֵד? אֵין צוֹרֶךְ בְּמַכְשִׁיר מְיוּחָד.<\/li>\n  <li>הַנִּיחוּ שְׁתֵּי אֶצְבָּעוֹת עַל שׁוֹרֶשׁ כַּף הַיָּד, מִתַּחַת לָאֲגוּדָל.<\/li>\n  <li>לַחֲצוּ בַּעֲדִינוּת, וְתַרְגִּישׁוּ נְקִישׁוֹת קְטַנּוֹת. לַנְּקִישׁוֹת הָאֵלֶּה קוֹרְאִים דּוֹפֶק.<\/li>\n  <li>כָּל נְקִישָׁה כָּזֹאת הִיא פְּעִימָה אַחַת שֶׁל הַלֵּב שֶׁלָּכֶם.<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה בְּכָל שְׁאֵלָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. מַדּוּעַ הַלֵּב פּוֹעֵם מַהֵר יוֹתֵר בִּזְמַן רִיצָה?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי בִּזְמַן רִיצָה הַלֵּב מִתְעַיֵּיף וְרוֹצֶה לָנוּחַ<\/li><li><span class=\"l\">ב.<\/span>כִּי בִּזְמַן רִיצָה הַדָּם מַפְסִיק לִזְרוֹם בַּצִּינּוֹרוֹת<\/li><li><span class=\"l\">ג.<\/span>כִּי בִּזְמַן רִיצָה הַשְּׁרִירִים זְקוּקִים לְיוֹתֵר חַמְצָן<\/li><li><span class=\"l\">ד.<\/span>כִּי בִּזְמַן רִיצָה הַלֵּב גָּדֵל וְנַעֲשֶׂה גָּדוֹל מֵאֶגְרוֹף<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. בְּשׁוּרָה 11 כָּתוּב: \"וְשׁוֹלֵחַ אֲלֵיהֶם עוֹד וְעוֹד דָּם\".<br>לְמִי אוֹ לְמָה מִתְיַיחֶסֶת הַמִּילָה \"אֲלֵיהֶם\"?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>לַשְּׁרִירִים<\/li><li><span class=\"l\">ב.<\/span>לַיְּלָדִים הַיְּשֵׁנִים<\/li><li><span class=\"l\">ג.<\/span>לָאֶצְבָּעוֹת וְלָאֲגוּדָל<\/li><li><span class=\"l\">ד.<\/span>לַחַמְצָן וְלַמָּזוֹן<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. מָה אֶפְשָׁר לִלְמוֹד מִשּׁוּרוֹת 13–16?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>שֶׁהַלֵּב נִמְצָא בְּשׁוֹרֶשׁ כַּף הַיָּד, מִתַּחַת לָאֲגוּדָל<\/li><li><span class=\"l\">ב.<\/span>שֶׁרַק רוֹפֵא עִם מַכְשִׁיר מְיוּחָד יָכוֹל לִבְדּוֹק אֶת הַדּוֹפֶק<\/li><li><span class=\"l\">ג.<\/span>שֶׁהַלֵּב פּוֹעֵם מַהֵר יוֹתֵר כְּשֶׁלּוֹחֲצִים עַל כַּף הַיָּד<\/li><li><span class=\"l\">ד.<\/span>שֶׁכָּל אֶחָד יָכוֹל לְהַרְגִּישׁ אֶת פְּעִימוֹת הַלֵּב שֶׁלּוֹ בְּעֶזְרַת הָאֶצְבָּעוֹת<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. עַל אֵיזוֹ שְׁאֵלָה <u>אֵין<\/u> תְּשׁוּבָה בַּקֶּטַע?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>מָה מֵבִיא הַדָּם אֶל הָאֵיבָרִים שֶׁבַּגּוּף?<\/li><li><span class=\"l\">ב.<\/span>כַּמָּה דָּם יֵשׁ בַּגּוּף שֶׁל יֶלֶד?<\/li><li><span class=\"l\">ג.<\/span>אֵיפֹה בַּגּוּף נִמְצָא הַלֵּב?<\/li><li><span class=\"l\">ד.<\/span>אֵיךְ אֶפְשָׁר לְהַרְגִּישׁ אֶת הַדּוֹפֶק?<\/li><\/ol><\/div>\n\n<div class=\"q\" data-accept=\"words:אגרוף|האגרוף|אגרוף קפוץ|אגרוף היד|אגרוף של יד|כף יד קפוצה\"><div class=\"stem\">5. הַשְׁלִימוּ אֶת הַמִּשְׁפָּט לְפִי הַקֶּטַע. כִּתְבוּ מִילָּה אַחַת עַל הַקַּו.<\/div>\n<div>הַלֵּב שֶׁל כָּל אֶחָד מֵאִיתָּנוּ הוּא בְּעֵרֶךְ בַּגּוֹדֶל שֶׁל <span class=\"blank\"><\/span> .<\/div><\/div>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">קִרְאוּ אֶת הַסִּיפּוּר שֶׁלִּפְנֵיכֶם וַעֲנוּ עַל הַשְּׁאֵלוֹת שֶׁאַחֲרָיו.<\/p>\n<div class=\"passage-title\">הַפֶּתֶק הַיָּשָׁן<\/div>\n<ol class=\"lines long\">\n  <li>בְּיוֹם שִׁישִּׁי בַּבּוֹקֶר בָּאָה אֵלָה אֶל הַבַּיִת שֶׁל סָבְתָא שׁוֹשַׁנָּה.<\/li>\n  <li>סָבְתָא הוֹצִיאָה מֵהַמְּגֵירָה פֶּתֶק יָשָׁן וְצָהוֹב, מְקוּפָּל לְאַרְבָּעָה.<\/li>\n  <li>\"זֶה הַמַּתְכּוֹן לָעוּגָה שֶׁל אִימָּא שֶׁלִּי, סָבְתָא רַבְּתָא שֶׁלָּךְ,\" אָמְרָה.<\/li>\n  <li>\"הִיא כָּתְבָה אוֹתוֹ לִפְנֵי שָׁנִים רַבּוֹת, וַאֲנִי שׁוֹמֶרֶת עָלָיו מֵאָז.\"<\/li>\n  <li>אֵלָה קָרְאָה: \"שָׁלוֹשׁ בֵּיצִים, כּוֹס סוּכָּר, שְׁתֵּי כּוֹסוֹת קֶמַח, וַחֲצִי כּוֹס מִיץ...\"<\/li>\n  <li>כָּאן נִמְרַח הַדְּיוֹ, וְאִי אֶפְשָׁר הָיָה לִקְרוֹא אֵיזֶה מִיץ כָּתוּב שָׁם.<\/li>\n  <li>\"אוּלַי נָכִין עוּגָה אַחֶרֶת?\" הִצִּיעָה אֵלָה. אֲבָל סָבְתָא לֹא הִסְכִּימָה.<\/li>\n  <li>\"לֹא מְוַותְּרִים כָּל כָּךְ מַהֵר! נְנַסֶּה לְגַלּוֹת בְּעַצְמֵנוּ מָה הָיָה כָּתוּב שָׁם.\"<\/li>\n  <li>בַּנִּיסָּיוֹן הָרִאשׁוֹן הֵן סָחֲטוּ לִימוֹן. הָעוּגָה יָצְאָה חֲמוּצָה מְאוֹד.<\/li>\n  <li>סָבְתָא טָעֲמָה וְעִיוְּותָה אֶת פָּנֶיהָ. \"לֹא, זֶה לֹא הַטַּעַם שֶׁאֲנִי זוֹכֶרֶת.\"<\/li>\n  <li>בַּנִּיסָּיוֹן הַשֵּׁנִי הֵן שָׁפְכוּ מִיץ תַּפּוּחִים. הָעוּגָה יָצְאָה תְּפֵלָה, כִּמְעַט בְּלִי טַעַם.<\/li>\n  <li>אֵלָה הִבִּיטָה בַּעֲרֵמַת הַכֵּלִים שֶׁבַּכִּיּוֹר וְנֶאֶנְחָה. \"אוּלַי בֶּאֱמֶת נַפְסִיק?\"<\/li>\n  <li>הִיא נִיגְּשָׁה אֶל הַחַלּוֹן, וְהִבְחִינָה בְּעֵץ גָּדוֹל בֶּחָצֵר, עָמוּס תַּפּוּזִים.<\/li>\n  <li>\"סָבְתָא, הָעֵץ הַזֶּה הָיָה כָּאן כְּשֶׁהָיִית יַלְדָּה?\" שָׁאֲלָה פִּתְאוֹם.<\/li>\n  <li>\"בְּוַודַּאי. אִימָּא שֶׁלִּי שָׁתְלָה אוֹתוֹ, וְקָטְפָה מִמֶּנּוּ תַּפּוּזִים כָּל חוֹרֶף.\"<\/li>\n  <li>עֵינֶיהָ שֶׁל אֵלָה נָצְצוּ. \"אָז אוּלַי הִיא שָׂמָה בָּעוּגָה מִיץ תַּפּוּזִים?\"<\/li>\n  <li>הֵן קָטְפוּ שְׁלוֹשָׁה תַּפּוּזִים, סָחֲטוּ אוֹתָם, וְהִכְנִיסוּ עוּגָה שְׁלִישִׁית לַתַּנּוּר.<\/li>\n  <li>כַּעֲבוֹר חֲצִי שָׁעָה הִתְמַלֵּא הַמִּטְבָּח בְּרֵיחַ מָתוֹק.<\/li>\n  <li>סָבְתָא טָעֲמָה פְּרוּסָה, עָצְמָה אֶת עֵינֶיהָ, וְדִמְעָה קְטַנָּה זָלְגָה עַל לֶחְיָהּ.<\/li>\n  <li>\"זֶה בְּדִיּוּק הַטַּעַם,\" לָחֲשָׁה. \"כְּאִילּוּ אִימָּא שֶׁלִּי עוֹמֶדֶת כָּאן בַּמִּטְבָּח.\"<\/li>\n  <li>אֵלָה לָקְחָה עֵט, וְכָתְבָה עַל פֶּתֶק חָדָשׁ אֶת הַמִּילָה הַחֲסֵרָה.<\/li>\n  <li>\"גַּם אֲנִי אֶשְׁמוֹר עַל הַמַּתְכּוֹן,\" אָמְרָה, \"וְיוֹם אֶחָד אָכִין אוֹתוֹ עִם הַנְּכָדִים שֶׁלִּי.\"<\/li>\n<\/ol>\n<p class=\"next\">עִבְרוּ לָעַמּוּד הַבָּא.<\/p>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כָּעֵת, עֲנוּ עַל הַשְּׁאֵלוֹת שֶׁלִּפְנֵיכֶם.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה בְּכָל שְׁאֵלָה.<\/p>\n\n<div class=\"tight\">\n<div class=\"q\"><div class=\"stem\">1. מָה פֵּירוּשׁ הַמִּילָה \"תְּפֵלָה\" (שׁוּרָה 11)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>מְתוּקָה מְאוֹד<\/li><li><span class=\"l\">ב.<\/span>חַסְרַת טַעַם<\/li><li><span class=\"l\">ג.<\/span>שְׂרוּפָה<\/li><li><span class=\"l\">ד.<\/span>קְטַנָּה מִדַּי<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. בְּשׁוּרָה 12 כָּתוּב שֶׁאֵלָה הִבִּיטָה בַּעֲרֵמַת הַכֵּלִים שֶׁבַּכִּיּוֹר.<br>הַמַּטָּרָה שֶׁל הַמִּשְׁפָּט הַזֶּה הִיא –<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>לְהַסְבִּיר שֶׁסָּבְתָא אֵינָהּ אוֹהֶבֶת לִשְׁטוֹף כֵּלִים<\/li><li><span class=\"l\">ב.<\/span>לְהַרְאוֹת שֶׁהַמִּטְבָּח שֶׁל סָבְתָא קָטָן מְאוֹד<\/li><li><span class=\"l\">ג.<\/span>לְסַפֵּר שֶׁאֵלָה בָּאָה כְּדֵי לַעֲזוֹר בִּשְׁטִיפַת הַכֵּלִים<\/li><li><span class=\"l\">ד.<\/span>לְהַדְגִּישׁ שֶׁהֵן כְּבָר עָבְדוּ הַרְבֵּה, וְלָכֵן אֵלָה כִּמְעַט הִתְיָיאֲשָׁה<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. מָה קָרָה <u>לִפְנֵי<\/u> שֶׁאֵלָה הִבְחִינָה בָּעֵץ שֶׁבֶּחָצֵר?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>הָעוּגָה יָצְאָה חֲמוּצָה מְאוֹד<\/li><li><span class=\"l\">ב.<\/span>הֵן קָטְפוּ שְׁלוֹשָׁה תַּפּוּזִים<\/li><li><span class=\"l\">ג.<\/span>דִּמְעָה זָלְגָה עַל לֶחְיָהּ שֶׁל סָבְתָא<\/li><li><span class=\"l\">ד.<\/span>אֵלָה כָּתְבָה עַל פֶּתֶק חָדָשׁ<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. מַדּוּעַ דִּמְעָה זָלְגָה עַל לֶחְיָהּ שֶׁל סָבְתָא (שׁוּרָה 19)?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי הָעוּגָה הַשְּׁלִישִׁית הָיְתָה חֲמוּצָה מִדַּי<\/li><li><span class=\"l\">ב.<\/span>כִּי הִצְטַעֲרָה שֶׁהַדְּיוֹ בַּפֶּתֶק הַיָּשָׁן נִמְרַח<\/li><li><span class=\"l\">ג.<\/span>כִּי הַטַּעַם הִזְכִּיר לָהּ אֶת אִימָּא שֶׁלָּהּ, וְהִיא הִתְרַגְּשָׁה<\/li><li><span class=\"l\">ד.<\/span>כִּי הָיְתָה עֲיֵיפָה מְאוֹד אַחֲרֵי שָׁלוֹשׁ עוּגוֹת<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">5. בְּשׁוּרָה 22 אֵלָה אוֹמֶרֶת: \"גַּם אֲנִי אֶשְׁמוֹר עַל הַמַּתְכּוֹן\".<br>מַדּוּעַ הִיא אוֹמֶרֶת \"גַּם\"?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>כִּי סָבְתָא שׁוֹשַׁנָּה שָׁמְרָה עַל הַמַּתְכּוֹן שָׁנִים רַבּוֹת<\/li><li><span class=\"l\">ב.<\/span>כִּי אֵלָה שׁוֹמֶרֶת בַּמְּגֵירָה שֶׁלָּהּ הַרְבֵּה פְּתָקִים<\/li><li><span class=\"l\">ג.<\/span>כִּי הַנְּכָדִים שֶׁל אֵלָה כְּבָר שׁוֹמְרִים עַל הַמַּתְכּוֹן<\/li><li><span class=\"l\">ד.<\/span>כִּי אֵלָה רוֹצָה לִשְׁמוֹר גַּם פְּרוּסָה מֵהָעוּגָה<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">6. בְּאֵיזֶה צֶמֶד מִילִים הַמִּילִים <u>אֵינָן<\/u> מִילִים נִרְדָּפוֹת?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>הִבְחִינָה – רָאֲתָה<\/li><li><span class=\"l\">ב.<\/span>לָחֲשָׁה – צָעֲקָה<\/li><li><span class=\"l\">ג.<\/span>עָמוּס – מָלֵא<\/li><li><span class=\"l\">ד.<\/span>כַּעֲבוֹר – אַחֲרֵי<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">7. אֵיזוֹ כּוֹתֶרֶת אַחֶרֶת מַתְאִימָה בְּיוֹתֵר לַסִּיפּוּר?<\/div>\n<ol class=\"opts\"><li><span class=\"l\">א.<\/span>יוֹם הַהוּלֶּדֶת שֶׁל אֵלָה<\/li><li><span class=\"l\">ב.<\/span>הָעוּגָה הַחֲמוּצָה<\/li><li><span class=\"l\">ג.<\/span>סָבְתָא קוֹנָה עוּגָה<\/li><li><span class=\"l\">ד.<\/span>מְנַסּוֹת, טוֹעוֹת וּמַצְלִיחוֹת<\/li><\/ol><\/div>\n\n<p class=\"stop\">עִבְרוּ לָעַמּוּד הַבָּא רַק לְאַחַר שֶׁתְּקַבְּלוּ הוֹרָאָה לְכָךְ מֵהַמּוֹרָה.<\/p>\n\n<\/div>\n<div class=\"page-break\"><\/div>\n<h2>חֵלֶק שֵׁנִי: שְׁאֵלוֹת בְּחֶשְׁבּוֹן<\/h2>\n<h3>מְשִׂימָה א': תַּרְגִּילִים<\/h3>\n<p class=\"instr\">פִּתְרוּ אֶת הַתַּרְגִּילִים וְכִתְבוּ אֶת הַתּוֹצָאָה.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\">66 + 27 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\">75 − 38 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\">9 × 8 = <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\">4. <span class=\"ex\">81 : 9 = <span class=\"blank\"><\/span><\/span><\/div>\n\n<h3>מְשִׂימָה ב': הַמִּסְפָּר הֶחָסֵר<\/h3>\n<p class=\"instr\">כִּתְבוּ אֶת הַמִּסְפָּר הֶחָסֵר בְּכָל תַּרְגִּיל.<\/p>\n<div class=\"q mathq\">1. <span class=\"ex\">37 + <span class=\"blank\"><\/span> = 82<\/span><\/div>\n<div class=\"q mathq\">2. <span class=\"ex\">100 − <span class=\"blank\"><\/span> = 64<\/span><\/div>\n<div class=\"q mathq\">3. <span class=\"ex\">3 × <span class=\"blank\"><\/span> = 27<\/span><\/div>\n<div class=\"q mathq\">4. <span class=\"ex\">32 : 4 = 15 − <span class=\"blank\"><\/span><\/span><\/div>\n\n<div class=\"page-break\"><\/div>\n<p class=\"instr\">כִּתְבוּ עַל הַקַּו מִסְפָּר מַתְאִים.<br>שִׂימוּ לֵב: בְּכָל תַּרְגִּיל יֵשׁ יוֹתֵר מִתְּשׁוּבָה נְכוֹנָה אַחַת.<\/p>\n<div class=\"q mathq\" data-accept=\"lt:38\">5. <span class=\"ex\">25 + 38 &gt; 25 + <span class=\"blank\"><\/span><\/span><\/div>\n<div class=\"q mathq\" data-accept=\"gt:40,le:72\">6. <span class=\"ex\">72 − <span class=\"blank\"><\/span> &lt; 72 − 40<\/span><\/div>\n\n<h3>מְשִׂימָה ג': בְּעָיוֹת מִילּוּלִיּוֹת<\/h3>\n<p class=\"instr\">קִרְאוּ כָּל בְּעָיָה וְהַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. עָמְרִי, עִנְבָּר וְסַבָּא אָסְפוּ צְדָפִים בְּחוֹף הַיָּם. לְעָמְרִי יֵשׁ 2 צְדָפִים.<br>לְעִנְבָּר יֵשׁ פִּי 3 צְדָפִים מֵאֲשֶׁר לְעָמְרִי. לְסַבָּא יֵשׁ פִּי 2 צְדָפִים מֵאֲשֶׁר לְעִנְבָּר.<br>כַּמָּה צְדָפִים יֵשׁ לְסַבָּא?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>6<\/li><li><span class=\"l\">ב.<\/span>8<\/li><li><span class=\"l\">ג.<\/span>12<\/li><li><span class=\"l\">ד.<\/span>20<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. שִׁיעוּר הַצִּיּוּר שֶׁל עִנְבָּר הִסְתַּיֵּים בְּשָׁעָה <span class=\"ex\">12:20<\/span>. הַשִּׁיעוּר נִמְשַׁךְ 45 דַּקּוֹת.<br>בְּאֵיזוֹ שָׁעָה <u>הִתְחִיל<\/u> הַשִּׁיעוּר?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span><span class=\"ex\">13:05<\/span><\/li><li><span class=\"l\">ב.<\/span><span class=\"ex\">11:35<\/span><\/li><li><span class=\"l\">ג.<\/span><span class=\"ex\">11:45<\/span><\/li><li><span class=\"l\">ד.<\/span><span class=\"ex\">11:25<\/span><\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. לְאֵיזֶה תַּרְגִּיל יֵשׁ הַתּוֹצָאָה <u>הַגְּדוֹלָה<\/u> בְּיוֹתֵר?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span><span class=\"ex\">6 × 7<\/span><\/li><li><span class=\"l\">ב.<\/span><span class=\"ex\">90 − 49<\/span><\/li><li><span class=\"l\">ג.<\/span><span class=\"ex\">80 : 2<\/span><\/li><li><span class=\"l\">ד.<\/span><span class=\"ex\">25 + 18<\/span><\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">4. לְעָמְרִי יֵשׁ 27 גּוּלּוֹת, וּלְעִנְבָּר יֵשׁ 13 גּוּלּוֹת.<br>כַּמָּה גּוּלּוֹת צָרִיךְ עָמְרִי לָתֵת לְעִנְבָּר כְּדֵי שֶׁיִּהְיֶה לִשְׁנֵיהֶם אוֹתוֹ מִסְפַּר גּוּלּוֹת?<\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>7<\/li><li><span class=\"l\">ב.<\/span>14<\/li><li><span class=\"l\">ג.<\/span>20<\/li><li><span class=\"l\">ד.<\/span>40<\/li><\/ol><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ד': חִידוֹת בְּצִיּוּרִים<\/h3>\n<p class=\"instr\">בְּכָל חִידָה, כָּל צִיּוּר מַסְתִּיר מִסְפָּר. אוֹתוֹ צִיּוּר מַסְתִּיר תָּמִיד אוֹתוֹ מִסְפָּר.<br>הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">☀&#xFE0E;<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>▲ + ▲ + ▲ = 18<\/td><\/tr><tr><td>▲ + ☀&#xFE0E; = 15<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>6<\/li><li><span class=\"l\">ב.<\/span>9<\/li><li><span class=\"l\">ג.<\/span>12<\/li><li><span class=\"l\">ד.<\/span>3<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">✿<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>♥ + ♥ + ♥ + ♥ = 20<\/td><\/tr><tr><td>♥ + ✿ + ✿ = 19<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>14<\/li><li><span class=\"l\">ב.<\/span>5<\/li><li><span class=\"l\">ג.<\/span>7<\/li><li><span class=\"l\">ד.<\/span>9<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">3. אֵיזֶה מִסְפָּר מַסְתִּיר הַצִּיּוּר <span class=\"sym\">♣<\/span> ?<\/div>\n<div class=\"pz\"><table class=\"puzzle\"><tr><td>★ + ● = 16<\/td><\/tr><tr><td>★ + ● + ★ + ● + ♣ = 35<\/td><\/tr><\/table><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>3<\/li><li><span class=\"l\">ב.<\/span>19<\/li><li><span class=\"l\">ג.<\/span>16<\/li><li><span class=\"l\">ד.<\/span>13<\/li><\/ol><\/div>\n\n<div class=\"page-break\"><\/div>\n<h3>מְשִׂימָה ה': תַּרְגִּילֵי מְשׁוּלָּשִׁים<\/h3>\n<p class=\"instr\">בְּכָל תַּרְגִּיל הַמְּשׁוּלָּשׁ ∆ מַסְתִּיר סִפְרָה. בְּאוֹתוֹ תַּרְגִּיל כָּל הַמְּשׁוּלָּשִׁים מַסְתִּירִים אוֹתָהּ סִפְרָה.<br>אֵיזוֹ סִפְרָה מַסְתִּיר הַמְּשׁוּלָּשׁ? הַקִּיפוּ אֶת הַתְּשׁוּבָה הַנְּכוֹנָה.<\/p>\n\n<div class=\"q\"><div class=\"stem\">1. <span class=\"ex\">4∆ + 1∆ = 60<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>0<\/li><li><span class=\"l\">ב.<\/span>3<\/li><li><span class=\"l\">ג.<\/span>6<\/li><li><span class=\"l\">ד.<\/span>5<\/li><\/ol><\/div>\n\n<div class=\"q\"><div class=\"stem\">2. <span class=\"ex\">∆∆ + ∆ = 48<\/span><\/div>\n<ol class=\"opts row\"><li><span class=\"l\">א.<\/span>2<\/li><li><span class=\"l\">ב.<\/span>8<\/li><li><span class=\"l\">ג.<\/span>4<\/li><li><span class=\"l\">ד.<\/span>6<\/li><\/ol><\/div>\n\n<p class=\"end\">סוֹף הַמִּבְחָן<\/p>\n\n<section class=\"answers\"><h2>פִּתְרוֹנוֹת – מבחן 8<\/h2>\n<table>\n<tr><th>שאלה<\/th><th>תשובה<\/th><th>הסבר + טריק<\/th><\/tr>\n<tr><th colspan=\"3\">קטע 1 – הלב<\/th><\/tr>\n<tr><td>1<\/td><td>ג<\/td><td>שורות 10–11: \"השרירים זקוקים להרבה יותר חמצן. לכן הלב מתחיל לפעום מהר יותר\". טריק: \"לכן\" מסמן סיבה – לקרוא שורה לפני.<\/td><\/tr>\n<tr><td>2<\/td><td>א<\/td><td>שורה 10 מדברת על השרירים שזקוקים לחמצן; הלב שולח \"אליהם\" = אל השרירים. טריק: כינוי גוף – להחליף את המילה ולקרוא בקול.<\/td><\/tr>\n<tr><td>3<\/td><td>ד<\/td><td>\"אין צורך במכשיר מיוחד\" + \"הניחו שתי אצבעות\" – כל אחד יכול להרגיש את הדופק. א' מחבר מילים מהקטע לא נכון (הלב בחזה). טריק: לסכם את השורות במשפט אחד לפני שקוראים את האפשרויות.<\/td><\/tr>\n<tr><td>4<\/td><td>ב<\/td><td>חמצן ומזון (ש' 7), בחזה (ש' 2), אצבעות על שורש כף היד (ש' 14–15) – מופיעים; כמות הדם – לא. טריק: לסמן ✓ ליד מה שמופיע.<\/td><\/tr>\n<tr><td>5<\/td><td>אגרוף<\/td><td>שורה 1: \"קפצו את כף היד לאגרוף. זה בערך הגודל של הלב\". מתקבל גם: האגרוף / אגרוף קפוץ / אגרוף היד / כף יד קפוצה. לא מתקבל: \"כף היד\", \"שריר\". טריק: השלמה – לחפש בקטע את המשפט עם אותן מילים (\"הגודל\").<\/td><\/tr>\n<tr><th colspan=\"3\">קטע 2 – הפתק הישן<\/th><\/tr>\n<tr><td>1<\/td><td>ב<\/td><td>ההסבר צמוד למילה: \"תפלה, כמעט בלי טעם\". טריק: מילה לא מוכרת – לקרוא את המשך המשפט.<\/td><\/tr>\n<tr><td>2<\/td><td>ד<\/td><td>ערמת כלים אחרי שתי עוגות שלא הצליחו + \"נאנחה... אולי באמת נפסיק?\" – מדגיש את המאמץ והייאוש. טריק: מטרת משפט – לקרוא שורה לפני ושורה אחרי.<\/td><\/tr>\n<tr><td>3<\/td><td>א<\/td><td>עוגה חמוצה – שורה 9; אלה מבחינה בעץ – שורה 13. שאר האירועים בשורות 17, 19, 21 – אחרי. טריק: סדר אירועים – לסמן מספר שורה ליד כל אפשרות.<\/td><\/tr>\n<tr><td>4<\/td><td>ג<\/td><td>שורה 20: \"זה בדיוק הטעם... כאילו אימא שלי עומדת כאן\" – דמעה של התרגשות וגעגוע. טריק: רגש – לחפש את המילים שמיד אחרי.<\/td><\/tr>\n<tr><td>5<\/td><td>א<\/td><td>שורה 4: סבתא אומרת \"ואני שומרת עליו מאז\" – אלה תשמור כמו סבתא. טריק: ב\"גם\" שואלים \"מי עוד?\".<\/td><\/tr>\n<tr><td>6<\/td><td>ב<\/td><td>לחשה (בשקט) ↔ צעקה (בקול רם) – הפכים. טריק: להציב במשפט; לשים לב ל\"אינן\".<\/td><\/tr>\n<tr><td>7<\/td><td>ד<\/td><td>הסיפור כולו: שני ניסיונות שנכשלו ושלישי שהצליח. ב' – רק פרט אחד; א', ג' – לא קרו בסיפור. טריק: כותרת חייבת להתאים לכל הסיפור.<\/td><\/tr>\n<tr><th colspan=\"3\">חשבון – משימה א'<\/th><\/tr>\n<tr><td>1<\/td><td>93<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">66+20=86<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">86+7=93<\/span>. טריק: להשלים לעשרת; ספרות בסדר הנכון (לא 39).<\/td><\/tr>\n<tr><td>2<\/td><td>37<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">75−40=35<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">35+2=37<\/span>. טריק: לבדוק חיסור בחיבור (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">37+38=75<\/span>).<\/td><\/tr>\n<tr><td>3<\/td><td>72<\/td><td>לוח הכפל: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">9×8=72<\/span>. טריק: ספרות בסדר הנכון (לא 27).<\/td><\/tr>\n<tr><td>4<\/td><td>9<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">9×9=81<\/span>. טריק: חילוק כהפוך כפל.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ב'<\/th><\/tr>\n<tr><td>1<\/td><td>45<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">82−37=45<\/span>. טריק: בדיקה בהצבה (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">37+45=82<\/span>).<\/td><\/tr>\n<tr><td>2<\/td><td>36<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">100−64=36<\/span>. טריק: כשהמחסר חסר – מחסרים את התוצאה מהמספר הראשון (לא מחברים!).<\/td><\/tr>\n<tr><td>3<\/td><td>9<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">3×9=27<\/span>. טריק: חילוק כהפוך כפל.<\/td><\/tr>\n<tr><td>4<\/td><td>7<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">32:4=8<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">15−7=8<\/span>. טריק: מאזניים – לכסות ולפתור קודם את הצד המלא.<\/td><\/tr>\n<tr><td>5<\/td><td>כל מספר קטן מ-38 (0–37)<\/td><td>25 משני הצדדים – משווים רק את מה ששונה: צריך מספר קטן מ-38. למשל 30. לא מתקבל: 38 ומעלה.<\/td><\/tr>\n<tr><td>6<\/td><td>כל מספר מ-41 עד 72<\/td><td>72 משני הצדדים; בחיסור הכיוון מתהפך: מורידים יותר → נשאר פחות. למשל 50 (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">22 &lt; 32<\/span>). לא מתקבל: 40 ומטה.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ג'<\/th><\/tr>\n<tr><td>1<\/td><td>ג (12)<\/td><td>ענבר: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">2×3=6<\/span>; סבא: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">6×2=12<\/span>. טריק: שרשרת כפלית – \"פי 2 ממי?\" (מענבר, לא מעמרי); 6 הוא תוצאת ביניים.<\/td><\/tr>\n<tr><td>2<\/td><td>ב (11:35)<\/td><td>הולכים אחורה: 20 דקות עד 12:00, ועוד 25 דקות אחורה → 11:35. טריק: שעון – \"הסתיים\" = מחסרים; לקפוץ לשעה העגולה (13:05 = חיבור בטעות).<\/td><\/tr>\n<tr><td>3<\/td><td>ד (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">25 + 18<\/span>)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">6×7=42<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">90−49=41<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">80:2=40<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">25+18=43<\/span>. טריק: הגדול מבין ארבעה – לחשב כל אחד ולכתוב את התוצאה לידו.<\/td><\/tr>\n<tr><td>4<\/td><td>א (7)<\/td><td>ההפרש <span dir=\"ltr\" style=\"unicode-bidi:isolate\">27−13=14<\/span>, נותנים חצי ממנו: 7. בדיקה: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">27−7=20<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">13+7=20<\/span>. טריק: העברה – חצי מההפרש (14 = ההפרש כולו).<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ד'<\/th><\/tr>\n<tr><td>1<\/td><td>ב (9)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">▲=18:3=6<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">☀&#xFE0E;=15−6=9<\/span>. טריק: להתחיל מהשורה עם סמל אחד בלבד; 6 הוא תוצאת ביניים.<\/td><\/tr>\n<tr><td>2<\/td><td>ג (7)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">♥=20:4=5<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">✿+✿=19−5=14<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">✿=7<\/span>. טריק: סמל כפול + החלפה; 14 הוא שני פרחים, לא אחד.<\/td><\/tr>\n<tr><td>3<\/td><td>א (3)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">★+●=16<\/span> היא \"חבילה\" שמופיעה פעמיים: <span dir=\"ltr\" style=\"unicode-bidi:isolate\">16+16=32<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">35−32=3<\/span>. טריק: החלפת קבוצה שלמה.<\/td><\/tr>\n<tr><th colspan=\"3\">משימה ה'<\/th><\/tr>\n<tr><td>1<\/td><td>ד (5)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">45+15=60<\/span>. טריק: ספרת האחדות – <span dir=\"ltr\" style=\"unicode-bidi:isolate\">∆+∆<\/span> מסתיים ב-0 → 0 או 5; <span dir=\"ltr\" style=\"unicode-bidi:isolate\">40+10=50<\/span> לא מתאים.<\/td><\/tr>\n<tr><td>2<\/td><td>ג (4)<\/td><td><span dir=\"ltr\" style=\"unicode-bidi:isolate\">44+4=48<\/span>. טריק: לבדוק כל אפשרות בהצבה (<span dir=\"ltr\" style=\"unicode-bidi:isolate\">22+2=24<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">66+6=72<\/span>, <span dir=\"ltr\" style=\"unicode-bidi:isolate\">88+8=96<\/span>).<\/td><\/tr>\n<\/table><\/section>", "id": 8, "pdf": "pdf/test_8.pdf", "questions": 31}];
